// 6. Daily Planner Drag-and-Drop & Inline Editing Engine
class DndPlanner {
  static bind(containerEl, plan, onUpdate) {
    if (!containerEl || !plan || !Array.isArray(plan.tasks)) return;
    let draggedItem = null;
    let draggedId = null;

    const items = containerEl.querySelectorAll('[data-task-item]');
    items.forEach(item => {
      item.setAttribute('draggable', 'true');
      item.addEventListener('dragstart', (e) => {
        draggedItem = item;
        draggedId = item.dataset.taskItem;
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', draggedId);
        item.classList.add('is-dragging');
      });
      item.addEventListener('dragend', () => {
        if (draggedItem) draggedItem.classList.remove('is-dragging');
        containerEl.querySelectorAll('.is-dragover').forEach(el => el.classList.remove('is-dragover'));
        draggedItem = null;
        draggedId = null;
      });
      item.addEventListener('dragover', (e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        if (item !== draggedItem) item.classList.add('is-dragover');
      });
      item.addEventListener('dragleave', () => item.classList.remove('is-dragover'));
      item.addEventListener('drop', (e) => {
        e.preventDefault();
        item.classList.remove('is-dragover');
        const targetId = item.dataset.taskItem;
        if (!draggedId || draggedId === targetId) return;

        const fromIdx = plan.tasks.findIndex(t => t.id === draggedId);
        const toIdx = plan.tasks.findIndex(t => t.id === targetId);
        if (fromIdx !== -1 && toIdx !== -1) {
          const [moved] = plan.tasks.splice(fromIdx, 1);
          plan.tasks.splice(toIdx, 0, moved);
          if (typeof onUpdate === 'function') onUpdate();
        }
      });
    });

    const inputs = containerEl.querySelectorAll('.task-inline-edit');
    inputs.forEach(input => {
      input.addEventListener('keydown', (e) => {
        const taskId = input.dataset.taskId;
        const task = plan.tasks.find(t => t.id === taskId);
        if (!task) return;

        if (e.key === 'Enter') {
          e.preventDefault();
          const nextIdx = plan.tasks.findIndex(t => t.id === taskId) + 1;
          const newTask = {
            id: uid(),
            text: 'New task',
            category: 'default',
            priority: 'normal',
            done: false,
            estimatedMins: 30
          };
          plan.tasks.splice(nextIdx, 0, newTask);
          if (typeof onUpdate === 'function') onUpdate();
          setTimeout(() => {
            const nextInput = containerEl.querySelector(`.task-inline-edit[data-task-id="${newTask.id}"]`);
            if (nextInput) {
              nextInput.focus();
              nextInput.select();
            }
          }, 60);
        } else if (e.key === 'Backspace' && input.value.trim() === '') {
          e.preventDefault();
          const curIdx = plan.tasks.findIndex(t => t.id === taskId);
          plan.tasks = plan.tasks.filter(t => t.id !== taskId);
          if (typeof onUpdate === 'function') onUpdate();
          if (curIdx > 0) {
            setTimeout(() => {
              const prevTask = plan.tasks[curIdx - 1];
              if (prevTask) {
                const prevInput = containerEl.querySelector(`.task-inline-edit[data-task-id="${prevTask.id}"]`);
                if (prevInput) prevInput.focus();
              }
            }, 60);
          }
        }
      });

      input.addEventListener('change', () => {
        const taskId = input.dataset.taskId;
        const task = plan.tasks.find(t => t.id === taskId);
        if (task) {
          task.text = input.value.trim() || 'Untitled Task';
          if (typeof onUpdate === 'function') onUpdate();
        }
      });
    });
  }
}

// 7. Selective CSV Exporter
function downloadCsv(csvContent, filename) {
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(a.href);
}

function escapeCsvField(val) {
  if (val === null || val === undefined) return '""';
  const str = String(val).replace(/"/g, '""');
  return `"${str}"`;
}

class CsvExporter {
  static exportFinance(store) {
    const list = (store && store.finance) || [];
    if (!list.length) return false;
    let csv = 'Date,Type,Category,Amount,Note\n';
    list.forEach(f => {
      csv += [escapeCsvField(f.date), escapeCsvField(f.type), escapeCsvField(f.category), escapeCsvField(f.amount), escapeCsvField(f.note || '')].join(',') + '\n';
    });
    downloadCsv(csv, `daystack_finance_${todayStr()}.csv`);
    return true;
  }

  static exportAttendance(store) {
    const schedules = (store && store.college && store.college.schedules) || {};
    const dates = Object.keys(schedules);
    if (!dates.length) return false;
    let csv = 'Date,Subject,Faculty,Room,ClassType,StartTime,EndTime,AttendanceStatus,Agenda\n';
    dates.forEach(d => {
      (schedules[d].classes || []).forEach(c => {
        csv += [escapeCsvField(d), escapeCsvField(c.subject), escapeCsvField(c.faculty), escapeCsvField(c.room), escapeCsvField(c.classType), escapeCsvField(c.startTime), escapeCsvField(c.endTime), escapeCsvField(c.attendance), escapeCsvField(c.agenda || '')].join(',') + '\n';
      });
    });
    downloadCsv(csv, `daystack_attendance_${todayStr()}.csv`);
    return true;
  }

  static exportHabits(store) {
    const habits = (store && store.habits) || [];
    const habitLogs = (store && store.habitLogs) || {};
    const dates = Object.keys(habitLogs).sort();
    if (!habits.length || !dates.length) return false;
    let csv = 'Date,' + habits.map(h => escapeCsvField(h.name)).join(',') + '\n';
    dates.forEach(d => {
      const row = [escapeCsvField(d)];
      habits.forEach(h => {
        row.push(escapeCsvField(habitLogs[d][h.id] || 'unlogged'));
      });
      csv += row.join(',') + '\n';
    });
    downloadCsv(csv, `daystack_habits_${todayStr()}.csv`);
    return true;
  }

  static exportDojo(store) {
    const tasks = (store && store.dojo && store.dojo.codingTasks) || [];
    if (!tasks.length) return false;
    let csv = 'Title,Platform,Topic,Difficulty,Language,Status,Approach,TimeComplexity,SpaceComplexity,TargetDate,Notes\n';
    tasks.forEach(t => {
      csv += [escapeCsvField(t.title), escapeCsvField(t.platform), escapeCsvField(t.topic), escapeCsvField(t.difficulty), escapeCsvField(t.language), escapeCsvField(t.status), escapeCsvField(t.approach || ''), escapeCsvField(t.timeComplexity || ''), escapeCsvField(t.spaceComplexity || ''), escapeCsvField(t.targetDate || ''), escapeCsvField(t.notes || '')].join(',') + '\n';
    });
    downloadCsv(csv, `daystack_dojo_dsa_${todayStr()}.csv`);
    return true;
  }

  static exportPlanner(store) {
    const planner = (store && store.plannerData) || {};
    const dates = Object.keys(planner).sort();
    if (!dates.length) return false;
    let csv = 'Date,Task,Priority,EstimatedMins,Status,Category\n';
    dates.forEach(d => {
      (planner[d].tasks || []).forEach(t => {
        csv += [escapeCsvField(d), escapeCsvField(t.text), escapeCsvField(t.priority || 'normal'), escapeCsvField(t.estimatedMins || 0), escapeCsvField(t.done ? 'Done' : 'Pending'), escapeCsvField(t.category || 'default')].join(',') + '\n';
      });
    });
    downloadCsv(csv, `daystack_planner_tasks_${todayStr()}.csv`);
    return true;
  }

  static exportExams(store) {
    const subjects = (store && store.exams && store.exams.subjects) || [];
    if (!subjects.length) return false;
    let csv = 'Subject,Category,Date,TargetMarks,AchievedMarks,PrepPercentage,Status,ImportantTopics\n';
    subjects.forEach(s => {
      csv += [escapeCsvField(s.subject), escapeCsvField(s.category), escapeCsvField(s.date), escapeCsvField(s.targetMarks), escapeCsvField(s.achievedMarks ?? ''), escapeCsvField(s.prepPct || 0), escapeCsvField(s.status), escapeCsvField(s.importantTopics || '')].join(',') + '\n';
    });
    downloadCsv(csv, `daystack_exams_${todayStr()}.csv`);
    return true;
  }
}

// 8. Recurring Finance Processor
class RecurringFinance {
  static getDefaultRecurring() {
    return []; // No pre-filled sample data — user adds their own
  }

  static processDueExpenses(store) {
    if (!store) return 0;
    if (!Array.isArray(store.recurringExpenses)) store.recurringExpenses = [];
    if (!Array.isArray(store.finance)) store.finance = [];

    const now = new Date();
    const currentYearMonth = now.toISOString().slice(0, 7);
    const currentDay = now.getDate();
    let processedCount = 0;

    store.recurringExpenses.forEach(rule => {
      if (!rule.active) return;
      const targetDay = Number(rule.dayOfMonth) || 1;
      if (currentDay >= targetDay) {
        const expectedDate = `${currentYearMonth}-${String(targetDay).padStart(2, '0')}`;
        const alreadyLogged = store.finance.some(f =>
          f.recurringRuleId === rule.id &&
          f.date.startsWith(currentYearMonth)
        );

        if (!alreadyLogged) {
          store.finance.push({
            id: uid(),
            recurringRuleId: rule.id,
            type: 'expense',
            amount: Number(rule.amount) || 0,
            category: rule.category || 'Subscriptions',
            date: expectedDate,
            note: `[Recurring] ${rule.name}`
          });
          rule.lastProcessed = currentYearMonth;
          processedCount++;
        }
      }
    });

    return processedCount;
  }
}

