// 10. Accessibility & Focus Trapping Manager
class A11yManager {
  static activeModalEl = null;
  static previousFocusedEl = null;
  static trapKeyHandler = null;

  static trapFocus(modalEl) {
    if (!modalEl) return;
    this.releaseFocus();

    this.activeModalEl = modalEl;
    this.previousFocusedEl = document.activeElement;

    modalEl.setAttribute('role', 'dialog');
    modalEl.setAttribute('aria-modal', 'true');

    const focusableSelector = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
    const focusableElements = modalEl.querySelectorAll(focusableSelector);
    const firstFocusable = focusableElements[0];

    if (firstFocusable) {
      setTimeout(() => firstFocusable.focus(), 50);
    }

    this.trapKeyHandler = (e) => {
      if (e.key !== 'Tab') return;
      const currentFocusables = modalEl.querySelectorAll(focusableSelector);
      if (!currentFocusables.length) return;
      const first = currentFocusables[0];
      const last = currentFocusables[currentFocusables.length - 1];

      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault();
          last.focus();
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };

    document.addEventListener('keydown', this.trapKeyHandler);
  }

  static releaseFocus() {
    if (this.trapKeyHandler) {
      document.removeEventListener('keydown', this.trapKeyHandler);
      this.trapKeyHandler = null;
    }
    if (this.previousFocusedEl && typeof this.previousFocusedEl.focus === 'function') {
      try { this.previousFocusedEl.focus(); } catch (err) {}
      this.previousFocusedEl = null;
    }
    this.activeModalEl = null;
  }
}

/* ---------------------------- CONSTANTS & CORE HELPERS ---------------------------- */
function getActiveStoreKey() {
  if (typeof STORE !== 'undefined' && STORE && STORE.user && STORE.user.id) {
    return `lifeos_user_${STORE.user.id}`;
  }
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith('sb-') && k.endsWith('-auth-token')) {
        const s = JSON.parse(localStorage.getItem(k));
        if (s && s.user && s.user.id) {
          return `lifeos_user_${s.user.id}`;
        }
      }
    }
  } catch (e) {}
  return 'lifeos_guest_v1';
}

function uid(){ return Math.random().toString(36).slice(2,10) + Date.now().toString(36).slice(-4); }
function fmtDate(d){
  if (!(d instanceof Date) || isNaN(d.getTime())) return todayStr();
  const y = d.getFullYear(), m = String(d.getMonth()+1).padStart(2,'0'), day = String(d.getDate()).padStart(2,'0');
  return `${y}-${m}-${day}`;
}
function todayStr(){ return fmtDate(new Date()); }

function parseDate(s){
  if (!s) return new Date();
  if (s instanceof Date) return isNaN(s.getTime()) ? new Date() : s;
  const cleanStr = String(s).trim().split(/[T ]/)[0];
  const parts = cleanStr.split('-').map(Number);
  if (parts.length === 3 && !isNaN(parts[0]) && !isNaN(parts[1]) && !isNaN(parts[2])) {
    return new Date(parts[0], parts[1] - 1, parts[2]);
  }
  const fallback = new Date(s);
  return isNaN(fallback.getTime()) ? new Date() : fallback;
}

function addDays(dateStr, n){
  const cleanStr = String(dateStr || todayStr()).trim().split(/[T ]/)[0];
  const parts = cleanStr.split('-').map(Number);
  if (parts.length === 3 && !isNaN(parts[0]) && !isNaN(parts[1]) && !isNaN(parts[2])) {
    const d = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2] + Number(n || 0)));
    const y = d.getUTCFullYear();
    const m = String(d.getUTCMonth() + 1).padStart(2, '0');
    const day = String(d.getUTCDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  }
  const d = parseDate(dateStr);
  d.setDate(d.getDate() + Number(n || 0));
  return fmtDate(d);
}

function diffDays(a, b){
  const cleanA = String(a || todayStr()).trim().split(/[T ]/)[0].split('-').map(Number);
  const cleanB = String(b || todayStr()).trim().split(/[T ]/)[0].split('-').map(Number);
  if (cleanA.length === 3 && cleanB.length === 3 && !cleanA.some(isNaN) && !cleanB.some(isNaN)) {
    const utcA = Date.UTC(cleanA[0], cleanA[1] - 1, cleanA[2]);
    const utcB = Date.UTC(cleanB[0], cleanB[1] - 1, cleanB[2]);
    return Math.round((utcB - utcA) / 86400000);
  }
  const da = parseDate(a);
  const db = parseDate(b);
  return Math.round((Date.UTC(db.getFullYear(), db.getMonth(), db.getDate()) - Date.UTC(da.getFullYear(), da.getMonth(), da.getDate())) / 86400000);
}

// Robust Date of Birth and Age Verification Helper (Handling leap years, birthdays today, invalid/future dates)
function calculateAge(dobStr, asOfDateStr = todayStr()) {
  if (!dobStr || typeof dobStr !== 'string') return null;
  const cleanDob = dobStr.trim().split(/[T ]/)[0];
  const parts = cleanDob.split('-').map(Number);
  if (parts.length !== 3 || parts.some(isNaN)) return null;
  const [birthYear, birthMonth, birthDay] = parts;
  if (birthYear < 1900 || birthMonth < 1 || birthMonth > 12 || birthDay < 1 || birthDay > 31) return null;

  const cleanAsOf = String(asOfDateStr || todayStr()).trim().split(/[T ]/)[0];
  const asOfParts = cleanAsOf.split('-').map(Number);
  if (asOfParts.length !== 3 || asOfParts.some(isNaN)) return null;
  const [curYear, curMonth, curDay] = asOfParts;

  // Future DOB is invalid
  if (curYear < birthYear || (curYear === birthYear && (curMonth < birthMonth || (curMonth === birthMonth && curDay < birthDay)))) {
    return null;
  }

  let age = curYear - birthYear;
  // If current month/day is strictly before birth month/day, subtract 1
  if (curMonth < birthMonth || (curMonth === birthMonth && curDay < birthDay)) {
    age--;
  }
  return Math.max(0, age);
}

function isUnder18(dobStr, asOfDateStr = todayStr()) {
  const age = calculateAge(dobStr, asOfDateStr);
  return (age !== null && age >= 0 && age < 18);
}

// Dynamic cycle date helpers (Pure mathematical duration calculation without hardcoded dates)
function getDefaultCycleDates(duration = 90, customStart = null) {
  const start = customStart || todayStr();
  const dur = Math.max(1, Number(duration) || 90);
  const end = addDays(start, dur - 1);
  return { startDate: start, endDate: end, durationDays: dur };
}

function niceDate(dateStr){
  const d = parseDate(dateStr);
  return d.toLocaleDateString('en-US', { weekday:'short', month:'short', day:'numeric', year:'numeric' });
}
function clamp(n,min,max){ return Math.max(min, Math.min(max,n)); }
function toast(msg){
  const t = document.getElementById('toast');
  if(!t) return;
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toast._t);
  toast._t = setTimeout(() => t.classList.remove('show'), 2600);
}
function showToast(msg){ toast(msg); }

