/* Global Expand/Collapse & Pin Section State */
const EXPANDED_SECTIONS = {};

function isSectionPinned(key){
  if(!STORE) return false;
  if(!STORE.pinnedSections) STORE.pinnedSections = {};
  if(STORE.pinnedSections[key]) return true;
  const baseKey = key.replace(/_\d{4}-\d{2}-\d{2}$/, '');
  if(baseKey !== key && STORE.pinnedSections[baseKey]) return true;
  return false;
}

function isSectionExpanded(key, defaultExpanded = false){
  if(isSectionPinned(key)) return true;
  if(EXPANDED_SECTIONS[key] === undefined){
    if(STORE && STORE.expandedSections && STORE.expandedSections[key] !== undefined){
      return !!STORE.expandedSections[key];
    }
    return defaultExpanded;
  }
  return !!EXPANDED_SECTIONS[key];
}

function toggleSectionExpanded(key){
  if(isSectionPinned(key)) return;
  const next = !isSectionExpanded(key);
  EXPANDED_SECTIONS[key] = next;
  if(STORE){
    if(!STORE.expandedSections) STORE.expandedSections = {};
    STORE.expandedSections[key] = next;
    save();
  }
}

function toggleSectionPinned(key, pinnedVal){
  if(!STORE) return;
  if(!STORE.pinnedSections) STORE.pinnedSections = {};
  STORE.pinnedSections[key] = !!pinnedVal;
  const baseKey = key.replace(/_\d{4}-\d{2}-\d{2}$/, '');
  if(baseKey !== key){
    STORE.pinnedSections[baseKey] = !!pinnedVal;
  }
  if(pinnedVal){
    EXPANDED_SECTIONS[key] = true;
    if(!STORE.expandedSections) STORE.expandedSections = {};
    STORE.expandedSections[key] = true;
    if(baseKey !== key) STORE.expandedSections[baseKey] = true;
  }
  save();
}

function renderCollapsibleSection({ key, title, icon = '📋', countLabel = '', defaultExpanded = false, contentHtml, actionBtnHtml = '' }){
  const pinned = isSectionPinned(key);
  const expanded = pinned || isSectionExpanded(key, defaultExpanded);

  return `
    <div class="card collapsible-card ${expanded ? 'is-expanded' : 'is-collapsed'} ${pinned ? 'is-pinned' : ''}" id="card_${key}">
      <div class="collapsible-header flex between align-center gap-10" style="cursor:pointer; user-select:none; flex-wrap:wrap; padding:2px 0;" data-toggle-expand="${key}">
        <div class="collapsible-title-group flex align-center gap-10" style="flex:1; min-width:160px;">
          <span class="expand-chevron" style="display:inline-flex; align-items:center; justify-content:center; width:26px; height:26px; border-radius:8px; background:${pinned ? 'var(--accent)' : 'var(--accent-dim)'}; color:${pinned ? '#ffffff' : 'var(--accent)'}; font-size:11px; transition:transform 0.25s ease; transform:${expanded ? 'rotate(90deg)' : 'rotate(0deg)'}; font-weight:700; flex-shrink:0;">▶</span>
          <div style="min-width:0; flex:1;">
            <div class="flex align-center gap-6" style="flex-wrap:wrap;">
              <span style="font-family:var(--font-display); font-size:14px; font-weight:700; color:var(--text-bright); white-space:nowrap;">${icon} ${escapeHtml(title)}</span>
              ${countLabel ? `<span class="pill pill-dim" style="font-size:11px; font-weight:600; white-space:nowrap;">${escapeHtml(countLabel)}</span>` : ''}
              ${pinned ? `<span class="pill pill-accent" style="font-size:10px; font-weight:700; white-space:nowrap;">📌 Open</span>` : ''}
            </div>
            <div class="dim collapsible-subtext" style="font-size:11px; margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:100%; opacity:0.75;">
              ${pinned ? '📌 Locked open — untick box to allow collapse' : expanded ? 'Tap header to collapse section' : 'Tap header to expand & view stored details'}
            </div>
          </div>
        </div>
        <div class="collapsible-controls flex align-center gap-8" onclick="event.stopPropagation();" style="flex-shrink:0; justify-content:flex-end;">
          ${actionBtnHtml ? `<div style="display:inline-flex; align-items:center;">${actionBtnHtml}</div>` : ''}
          <label class="pin-tickbox-label flex align-center gap-6" style="cursor:pointer; font-size:11.5px; font-weight:600; color:${pinned ? 'var(--accent)' : 'var(--text-dim)'}; background:${pinned ? 'var(--accent-dim)' : 'var(--bg-3)'}; padding:4px 9px; border-radius:8px; border:1px solid ${pinned ? 'var(--accent)' : 'var(--border-soft)'}; user-select:none; transition:all 0.2s ease; white-space:nowrap;" title="Tick to keep all details in this section open until unticked">
            <input type="checkbox" data-pin-section="${key}" ${pinned ? 'checked' : ''} style="cursor:pointer; accent-color:var(--accent); width:14px; height:14px;" />
            <span>${pinned ? '✓ Keep Open' : 'Keep Open'}</span>
          </label>
        </div>
      </div>
      <div class="collapsible-body" style="${expanded ? '' : 'display:none;'} margin-top:12px; border-top:1px solid var(--border-soft); padding-top:14px;">
        ${contentHtml}
      </div>
    </div>
  `;
}

function openRoutineItemModal(plan, item = null, defaultBlock = 'morning'){
  const isEdit = !!item;
  const block = item ? item.block : defaultBlock;
  const text = item ? item.text : '';
  const time = item ? (item.time || '') : '';
  const notes = item ? (item.notes || '') : '';
  const done = item ? item.done : false;

  const modalHtml = `
    <div class="modal-title" style="font-family:var(--font-display); font-size:18px; font-weight:700; margin-bottom:14px; color:var(--text-bright);">${isEdit ? '✏️ Edit Routine Item' : '➕ Add Routine Item'}</div>
    <div class="form-row">
      <label>Routine Block</label>
      <select id="rtBlock" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-2); color:var(--text);">
        <option value="morning" ${block==='morning'?'selected':''}>🌅 Morning Routine</option>
        <option value="evening" ${block==='evening'?'selected':''}>🌇 Evening Routine</option>
        <option value="night" ${block==='night'?'selected':''}>🌙 Night Routine</option>
      </select>
    </div>
    <div class="form-row" style="margin-top:10px;">
      <label>Item / Task Title *</label>
      <input id="rtText" value="${escapeHtml(text)}" placeholder="e.g. 10-Min Stretch, Meditate, Review Goals" autofocus style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-2); color:var(--text);"/>
    </div>
    <div class="form-grid" style="margin-top:10px; display:grid; grid-template-columns: 1fr 1fr; gap:10px;">
      <div class="form-row">
        <label>Time (optional)</label>
        <input type="time" id="rtTime" value="${escapeHtml(time)}" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-2); color:var(--text);"/>
      </div>
      <div class="form-row">
        <label>Status</label>
        <select id="rtDone" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-2); color:var(--text);">
          <option value="false" ${!done?'selected':''}>Incomplete</option>
          <option value="true" ${done?'selected':''}>Completed ✓</option>
        </select>
      </div>
    </div>
    <div class="form-row" style="margin-top:10px;">
      <label>Notes / Instructions (optional)</label>
      <input id="rtNotes" value="${escapeHtml(notes)}" placeholder="e.g. 2 glasses of water, 15 reps, journal thoughts" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-2); color:var(--text);"/>
    </div>
    <div class="form-actions" style="margin-top:18px; display:flex; justify-content:flex-end; gap:8px;">
      ${isEdit ? `<button class="btn btn-danger" id="rtDelBtn">Delete Item</button>` : ''}
      <button class="btn btn-ghost" id="rtCancelBtn">Cancel</button>
      <button class="btn btn-accent" id="rtSaveBtn">Save Item</button>
    </div>
  `;
  openModal(isEdit ? 'Edit Routine Item' : 'Add Routine Item', modalHtml, modalEl => {
    modalEl.querySelector('#rtCancelBtn')?.addEventListener('click', closeModal);
    if(modalEl.querySelector('#rtDelBtn')){
      modalEl.querySelector('#rtDelBtn')?.addEventListener('click', () => {
        if(confirm('Delete this routine item?')){
          plan.checklist = plan.checklist.filter(i => i.id !== item.id);
          save(); closeModal(); render();
          showToast('Routine item deleted');
        }
      });
    }
    modalEl.querySelector('#rtSaveBtn')?.addEventListener('click', () => {
      const newText = modalEl.querySelector('#rtText').value.trim();
      if(!newText) return toast('Please enter a routine item title');
      const newBlock = modalEl.querySelector('#rtBlock').value;
      const newTime = modalEl.querySelector('#rtTime').value;
      const newDone = modalEl.querySelector('#rtDone').value === 'true';
      const newNotes = modalEl.querySelector('#rtNotes').value.trim();

      if(isEdit){
        Object.assign(item, { block: newBlock, text: newText, time: newTime, notes: newNotes, done: newDone });
      } else {
        plan.checklist.push({ id: uid(), block: newBlock, text: newText, time: newTime, notes: newNotes, done: newDone });
      }
      save(); closeModal(); render();
      showToast(isEdit ? 'Routine item updated' : 'Routine item added');
    });
  });
}

