function normalizeAndMigrateStore(store) {
  if (!store || typeof store !== 'object') store = defaultStore();
  const def = defaultStore();

  // 1. Pinned and Expanded UI state
  if (!store.pinnedSections || typeof store.pinnedSections !== 'object') store.pinnedSections = {};
  if (!store.expandedSections || typeof store.expandedSections !== 'object') store.expandedSections = {};

  // 2. Habits & Logs
  if (!Array.isArray(store.habits)) store.habits = [];
  if (!store.habitLogs || typeof store.habitLogs !== 'object') store.habitLogs = {};
  store.habits.forEach((h, idx) => {
    if (!h.id) h.id = uid();
    if (!h.category) h.category = 'growth';
    if (!h.createdAt) h.createdAt = todayStr();
  });

  // 3. Planner Data
  if (!store.plannerData || typeof store.plannerData !== 'object') store.plannerData = {};

  // 4. Contests Tracker (Competitive Programming)
  if (!store.contests || typeof store.contests !== 'object') {
    store.contests = { entries: [], goals: [] };
  } else {
    if (!Array.isArray(store.contests.entries)) store.contests.entries = [];
    if (!Array.isArray(store.contests.goals)) store.contests.goals = [];
  }

  // 5. Exams & Academic Performance
  if (!store.exams || typeof store.exams !== 'object') {
    store.exams = { list: [], sgpaCourses: [], cgpaSemesters: [] };
  } else {
    if (!Array.isArray(store.exams.list)) {
      const legacySubjects = Array.isArray(store.exams.subjects) ? store.exams.subjects : [];
      if (legacySubjects.length > 0) {
        store.exams.list = [
          {
            id: 'exam_migrated_cat1',
            name: 'CAT 1 / MID 1',
            type: 'Internal / CAT',
            date: todayStr(),
            startTime: '09:30',
            endTime: '12:30',
            semester: 'Sem 3',
            notes: store.exams.notes || '',
            subjects: legacySubjects.map(s => ({
              name: s.name || s.subject || 'Subject',
              prepStatus: s.prepStatus || 'Not Started',
              maxMarks: Number(s.maxMarks) || 100,
              targetMarks: Number(s.targetMarks) || 85,
              obtainedMarks: s.obtainedMarks || '',
              grade: s.grade || 'O',
              notes: s.notes || ''
            }))
          }
        ];
      } else {
        store.exams.list = [];
      }
    }
    if (!Array.isArray(store.exams.sgpaCourses)) store.exams.sgpaCourses = [];
    if (!Array.isArray(store.exams.cgpaSemesters)) store.exams.cgpaSemesters = [];
  }

  // 6. Universal Notification Center, Deduplication & Escalation State
  if (!store.notificationsConfig || typeof store.notificationsConfig !== 'object') {
    store.notificationsConfig = { enabled: true, leadMinutes: 5, cooldownMinutes: 15, audioEnabled: true, vibrationEnabled: true, importantAlertsEnabled: true, browserEnabled: false };
  } else {
    if (typeof store.notificationsConfig.enabled !== 'boolean') store.notificationsConfig.enabled = true;
    if (typeof store.notificationsConfig.audioEnabled !== 'boolean') store.notificationsConfig.audioEnabled = true;
    if (typeof store.notificationsConfig.vibrationEnabled !== 'boolean') store.notificationsConfig.vibrationEnabled = true;
    if (typeof store.notificationsConfig.importantAlertsEnabled !== 'boolean') store.notificationsConfig.importantAlertsEnabled = true;
    if (typeof store.notificationsConfig.leadMinutes !== 'number') store.notificationsConfig.leadMinutes = 5;
    if (typeof store.notificationsConfig.cooldownMinutes !== 'number') store.notificationsConfig.cooldownMinutes = 15;
  }
  // 6a. Category Preferences — per-source toggle schema (migrate existing stores)
  if (!store.notificationsConfig.categoryPrefs || typeof store.notificationsConfig.categoryPrefs !== 'object') {
    store.notificationsConfig.categoryPrefs = {
      habits: true, routines: true, planner: true, goals: true,
      calendar: true, fitness: true, contests: true, exams: true,
      importantTasks: true, guardianAlerts: true
    };
  } else {
    const cp = store.notificationsConfig.categoryPrefs;
    const catDefaults = ['habits','routines','planner','goals','calendar','fitness','contests','exams','importantTasks','guardianAlerts'];
    catDefaults.forEach(k => { if (typeof cp[k] !== 'boolean') cp[k] = true; });
  }
  // 6b. Silent/DND mode awareness flag (user has acknowledged OS limitation disclosure)
  if (typeof store.notificationsConfig.silentModeAware !== 'boolean') store.notificationsConfig.silentModeAware = false;

  if (!Array.isArray(store.notificationsReadIds)) store.notificationsReadIds = [];
  if (!Array.isArray(store.notificationsDismissedIds)) store.notificationsDismissedIds = [];
  if (!Array.isArray(store.deliveredNotifIds)) store.deliveredNotifIds = [];
  if (!Array.isArray(store.notificationsLog)) store.notificationsLog = [];
  if (!store.notificationsState || typeof store.notificationsState !== 'object') store.notificationsState = {};
  if (!Array.isArray(store.guardianAlertsLog)) store.guardianAlertsLog = [];

  // 6c. Daily cleanup of deliveredNotifIds — remove entries from prior dates (keeps dedup list lean)
  const _todayPrefix = (function(){ const d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); })();
  if (Array.isArray(store.deliveredNotifIds)) {
    store.deliveredNotifIds = store.deliveredNotifIds.filter(id => typeof id === 'string' && id.endsWith(_todayPrefix));
  }

  // 7. Settings & Target Cycle
  if (!store.settings || typeof store.settings !== 'object') store.settings = def.settings;
  if (!store.settings.schedule || typeof store.settings.schedule !== 'object') store.settings.schedule = def.settings.schedule;
  if (typeof store.settings.name !== 'string' || !store.settings.name) store.settings.name = 'Friend';
  if (typeof store.settings.schedule.editsRemaining !== 'number') store.settings.schedule.editsRemaining = 3;
  if (typeof store.settings.schedule.locked !== 'boolean') store.settings.schedule.locked = false;
  if (typeof store.settings.schedule.currentCycle !== 'number') store.settings.schedule.currentCycle = 1;
  if (typeof store.settings.schedule.maxCycles !== 'number') store.settings.schedule.maxCycles = 3;
  if (typeof store.settings.schedule.cycleGoal !== 'string') {
    const dDays = Number(store.settings.schedule.durationDays) || 90;
    store.settings.schedule.cycleGoal = `Complete ${dDays}-day Productivity Journey`;
  }

  // 8. User Profile
  if (!store.user || typeof store.user !== 'object') store.user = defaultUser();
  if (!store.user.profile || typeof store.user.profile !== 'object') store.user.profile = defaultUser().profile;

  // 9. College, Dojo, Fitness, History
  if (!store.college || typeof store.college !== 'object') store.college = defaultCollege();
  if (!Array.isArray(store.college.updates)) store.college.updates = [];
  if (!store.college.schedules || typeof store.college.schedules !== 'object') store.college.schedules = {};
  if (!Array.isArray(store.college.defaultClasses)) store.college.defaultClasses = defaultCollege().defaultClasses;
  if (!Array.isArray(store.college.semesterSubjects)) store.college.semesterSubjects = [];

  if (!store.dojo || typeof store.dojo !== 'object') store.dojo = def.dojo;
  else {
    const dojoDefaults = def.dojo;
    store.dojo.belts = Array.isArray(store.dojo.belts) && store.dojo.belts.length >= 10 ? store.dojo.belts : dojoDefaults.belts;
    store.dojo.dsaTopics = store.dojo.dsaTopics || dojoDefaults.dsaTopics;
    store.dojo.languages = store.dojo.languages || dojoDefaults.languages;
    store.dojo.beltTargets = Array.isArray(store.dojo.beltTargets) ? store.dojo.beltTargets : [];
    store.dojo.attempts = Array.isArray(store.dojo.attempts) ? store.dojo.attempts : [];
    store.dojo.codingTasks = Array.isArray(store.dojo.codingTasks) ? store.dojo.codingTasks : [];
  }

  if (!store.academics || typeof store.academics !== 'object') store.academics = { sgpaCourses: GpaCalculator.getDefaultCourses(), cgpaSemesters: GpaCalculator.getDefaultSemesters() };
  if (!Array.isArray(store.academics.sgpaCourses)) store.academics.sgpaCourses = GpaCalculator.getDefaultCourses();
  if (!Array.isArray(store.academics.cgpaSemesters)) store.academics.cgpaSemesters = GpaCalculator.getDefaultSemesters();

  if (!Array.isArray(store.fitnessTrackers)) store.fitnessTrackers = [];
  if (!Array.isArray(store.fitnessGoals)) store.fitnessGoals = [];
  if (!Array.isArray(store.cycleHistory)) store.cycleHistory = [];
  if (!Array.isArray(store.history)) store.history = [];
  if (!Array.isArray(store.pomodoroHistory)) store.pomodoroHistory = [];
  if (!Array.isArray(store.journal)) store.journal = [];
  if (!Array.isArray(store.finance)) store.finance = [];
  if (!Array.isArray(store.goals)) store.goals = [];
  if (!Array.isArray(store.notes)) store.notes = [];
  if (!Array.isArray(store.mistakes)) store.mistakes = [];

  // 10. Onboarding & Section Tours State
  if (!store.onboarding || typeof store.onboarding !== 'object') {
    store.onboarding = { completed: false, tourCompleted: false, step: 0, completedAt: null, sectionToursCompleted: {} };
  } else {
    if (typeof store.onboarding.completed !== 'boolean') store.onboarding.completed = false;
    if (typeof store.onboarding.tourCompleted !== 'boolean') store.onboarding.tourCompleted = false;
    if (typeof store.onboarding.step !== 'number') store.onboarding.step = 0;
    if (!store.onboarding.sectionToursCompleted || typeof store.onboarding.sectionToursCompleted !== 'object') {
      store.onboarding.sectionToursCompleted = {};
    }
  }

  return store;
}

const CLEAN_RESET_KEY = 'orvyn_clean_slate_reset_v2';

function resetAllUserGeneratedData(store){
  if(!store || typeof store !== 'object') store = defaultStore();
  store.habits = [];
  store.habitLogs = {};
  store.plannerData = {};
  store.studySessions = [];
  store.projects = [];
  store.books = [];
  store.fitnessLogs = {};
  store.healthLogs = {};
  store.fitnessTrackers = [];
  store.fitnessGoals = [];
  store.unlockedBadges = [];
  store.finance = [];
  store.journal = [];
  store.mistakes = [];
  store.goals = [];
  store.notes = [];
  store.history = [];
  store.pomodoroHistory = [];
  store.exams = { list: [], sgpaCourses: [], cgpaSemesters: [] };
  store.contests = { entries: [], goals: [] };
  store.college = { schedules: {}, updates: [], defaultClasses: [], semesterSubjects: [] };
  store.academics = { sgpaCourses: [], cgpaSemesters: [] };
  store.recurringExpenses = [];
  store.cycleHistory = [];
  store.notificationsReadIds = [];
  store.notificationsDismissedIds = [];
  store.deliveredNotifIds = [];
  store.notificationsLog = [];
  if(store.dojo){
    store.dojo.beltTargets = [];
    store.dojo.attempts = [];
    store.dojo.codingTasks = [];
  }
  return store;
}

function load(){
  try{
    const activeKey = getActiveStoreKey();
    const raw = localStorage.getItem(activeKey);
    let parsed = raw ? JSON.parse(raw) : defaultStore();

    // Check if clean slate reset needs to be applied
    let resetDone = false;
    try { resetDone = localStorage.getItem(CLEAN_RESET_KEY) === 'true'; } catch(_) {}
    if (!resetDone) {
      parsed = resetAllUserGeneratedData(parsed);
      try {
        localStorage.setItem(CLEAN_RESET_KEY, 'true');
        localStorage.removeItem('lifeos_guest_v1');
        localStorage.removeItem('lifeos_store');
        localStorage.removeItem('orvyn_store_v1');
      } catch(_) {}
    }

    STORE = normalizeAndMigrateStore(parsed);

    if (!resetDone) {
      save();
    }

    // Auto snapshot and IDB sync
    if (typeof storageAdapter !== 'undefined' && storageAdapter.autoMigrate) {
      storageAdapter.autoMigrate(activeKey).then(() => {
        if (typeof BackupManager !== 'undefined') {
          BackupManager.checkAutoSnapshots(STORE);
        }
      }).catch(e => console.warn('Storage sync note:', e));
    }
  }catch(e){
    console.error('Error loading store, restoring default state:', e);
    STORE = defaultStore();
  }
}

function save(){
  const activeKey = getActiveStoreKey();
  try {
    localStorage.setItem(activeKey, JSON.stringify(STORE));
  } catch (err) {
    console.warn('LocalStorage save warning:', err);
  }
  if (typeof storageAdapter !== 'undefined' && storageAdapter.set) {
    storageAdapter.set(activeKey, STORE).catch(e => console.warn('IDB save note:', e));
  }
  if (typeof CrossTabSyncEngine !== 'undefined') {
    CrossTabSyncEngine.broadcastMutation();
  }
  if (typeof LiveSyncEngine !== 'undefined') {
    LiveSyncEngine.schedulePush();
  }
}

/* ---------------------------- REAL-TIME CROSS-TAB SYNC ENGINE ---------------------------- */
const CrossTabSyncEngine = {
  channel: null,
  isApplyingRemoteUpdate: false,
  tabId: null,

  init() {
    if (typeof window === 'undefined') return;
    this.tabId = 'tab_' + Math.random().toString(36).slice(2, 9) + '_' + Date.now();

    // 1. BroadcastChannel API for instantaneous, sub-millisecond sync across open tabs
    if ('BroadcastChannel' in window) {
      try {
        this.channel = new BroadcastChannel('orvyn_cross_tab_sync');
        this.channel.onmessage = (event) => {
          if (event && event.data && event.data.type === 'STORE_MUTATED') {
            this.handleRemoteMutation(event.data);
          }
        };
      } catch (e) {
        this.channel = null;
      }
    }

    // 2. Storage event fallback for cross-tab notifications
    window.addEventListener('storage', (e) => {
      if (!e.key) return;
      const currentActiveKey = getActiveStoreKey();
      if (e.key === currentActiveKey && e.newValue) {
        this.handleRemoteMutation({
          key: e.key,
          tabId: 'storage_event_fallback',
          timestamp: Date.now()
        });
      }
    });
  },

  broadcastMutation() {
    if (this.isApplyingRemoteUpdate) return;
    try {
      if (this.channel) {
        this.channel.postMessage({
          type: 'STORE_MUTATED',
          key: getActiveStoreKey(),
          tabId: this.tabId,
          timestamp: Date.now()
        });
      }
    } catch (err) {}
  },

  handleRemoteMutation(data) {
    if (!data) return;
    if (data.tabId === this.tabId) return; // Prevent echoing back to self
    const activeKey = getActiveStoreKey();
    if (data.key && data.key !== activeKey) return; // Only process active user key

    this.isApplyingRemoteUpdate = true;
    try {
      const raw = localStorage.getItem(activeKey);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === 'object') {
          STORE = normalizeAndMigrateStore(parsed);
          // Re-render UI in background tab
          if (typeof render === 'function') {
            render();
          }
          // Synchronize active Pomodoro clock if running
          if (typeof initOrRestorePomoState === 'function') {
            initOrRestorePomoState();
          }
        }
      }
    } catch (err) {
      console.warn('CrossTabSyncEngine remote sync note:', err);
    } finally {
      this.isApplyingRemoteUpdate = false;
    }
  }
};

/* ---------------------------- CROSS-DEVICE LIVE SYNC ENGINE ---------------------------- */
const LiveSyncEngine = {
  syncTimeout: null,
  isPushing: false,
  isPulling: false,
  lastSyncedAt: null,
  lastPushedAt: null,   // tracks when THIS device last pushed (to avoid re-pulling own data)
  isOnlineServer: false,
  serverUrl: null,

  init() {
    this.fetchNetworkInfo();
    this.pullFromServer(true);

    // Visibility change / Tab focus -> auto pull latest updates smoothly
    document.addEventListener('visibilitychange', () => {
      if (!document.hidden) this.pullFromServer();
    });
    window.addEventListener('focus', () => {
      this.pullFromServer();
    });

    // Gentle background heartbeat (30s) instead of aggressive 2s flicker
    setInterval(() => {
      if (!document.hidden && !this.isPushing && !this.isPulling) {
        this.pullFromServer();
      }
    }, 30000);
  },

  fetchNetworkInfo() {
    if (typeof fetch === 'undefined' || window.location.protocol === 'file:') return;
    fetch('/api/network-info')
      .then(res => res.json())
      .then(data => {
        if (data && data.url) {
          this.serverUrl = data.url;
          this.isOnlineServer = true;
          this.updateSyncUI();
        }
      })
      .catch(() => {});
  },

  schedulePush() {
    if (typeof fetch === 'undefined' || window.location.protocol === 'file:') return;
    if (this.syncTimeout) clearTimeout(this.syncTimeout);
    this.syncTimeout = setTimeout(() => {
      this.pushToServer();
    }, 350);
  },

  async pushToServer() {
    if (this.isPushing) return;
    if (typeof fetch === 'undefined' || window.location.protocol === 'file:') return;
    try {
      this.isPushing = true;
      const now = new Date().toISOString();
      STORE._syncedAt = now;
      this.lastSyncedAt = now;
      this.lastPushedAt = now;
      const res = await fetch('/api/store', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(STORE)
      });
      if (res.ok) {
        const responseData = await res.json();
        if (responseData && responseData.syncedAt) {
          this.lastPushedAt = responseData.syncedAt;
          STORE._syncedAt = responseData.syncedAt;
          try { localStorage.setItem(getActiveStoreKey(), JSON.stringify(STORE)); } catch(_) {}
        }
        this.isOnlineServer = true;
        this.updateSyncUI();
      }
    } catch (_) {
      // Offline / standalone mode - ignore silently
    } finally {
      this.isPushing = false;
    }
  },

  async pullFromServer(isInitial = false) {
    if (this.isPushing || this.isPulling) return;
    if (typeof fetch === 'undefined' || window.location.protocol === 'file:') return;
    try {
      this.isPulling = true;
      const res = await fetch('/api/store');
      if (res.status === 200) {
        const data = await res.json();
        if (data && data.success && data.store) {
          const remoteStore = data.store;
          const remoteSyncedAt = remoteStore._syncedAt || data.syncedAt;
          const localSyncedAt = STORE._syncedAt || this.lastSyncedAt;

          // Skip if we are the ones who just pushed this exact version
          if (!isInitial && this.lastPushedAt && remoteSyncedAt === this.lastPushedAt) {
            this.isPulling = false;
            return;
          }

          // If remote is newer or this is initial load and remote has valid data
          const isModalOpen = document.getElementById('modalOverlay')?.classList.contains('open');
          const activeEl = document.activeElement;
          const activeTag = activeEl ? activeEl.tagName.toLowerCase() : '';
          const isEditing = activeTag === 'input' || activeTag === 'textarea' || activeEl?.isContentEditable;

          // Do NOT interrupt active user input or open modals with re-renders
          if (!isInitial && (isEditing || isModalOpen)) {
            this.isPulling = false;
            return;
          }

          const shouldApply = isInitial ||
            !localSyncedAt ||
            (remoteSyncedAt && remoteSyncedAt > localSyncedAt);

          if (shouldApply) {
            const currentJson = JSON.stringify(STORE);
            const normalizedRemote = normalizeAndMigrateStore(remoteStore);
            const newJson = JSON.stringify(normalizedRemote);

            // Only trigger re-render if the state content has actually changed!
            const hasChanged = currentJson !== newJson;

            STORE = normalizedRemote;
            this.lastSyncedAt = remoteSyncedAt;
            this.isOnlineServer = true;
            try {
              localStorage.setItem(getActiveStoreKey(), JSON.stringify(STORE));
            } catch (_) {}

            if (hasChanged || isInitial) {
              render();
              updateTargetButtonUI();
              updateNotificationBadges();
            }
            this.updateSyncUI();
          }
        }
      } else if (res.status === 404 && isInitial) {
        this.pushToServer();
      }
    } catch (_) {
      // Standalone / server down
    } finally {
      this.isPulling = false;
    }
  },

  updateSyncUI(state) {
    // Mobile topbar sync dot: green=online, yellow=syncing, grey=offline
    const dot = document.getElementById('mobileSyncDot');
    if (dot) {
      if (state === 'syncing') {
        dot.style.background = '#facc15';
        dot.style.boxShadow = '0 0 6px #facc15';
      } else if (this.isOnlineServer) {
        dot.style.background = '#4ade80';
        dot.style.boxShadow = '0 0 5px #4ade80';
      } else {
        dot.style.background = '#6b7280';
        dot.style.boxShadow = 'none';
      }
    }
  }
};

/* ---------------------------- CHART MEMORY LEAK PREVENTION ---------------------------- */
function safeDestroyChart(chartKey){
  if(charts && charts[chartKey] && typeof charts[chartKey].destroy === 'function'){
    try { charts[chartKey].destroy(); } catch(_){}
    charts[chartKey] = null;
  }
}

/* ---------------------------- GOAL-TASK ADVANCEMENT HELPER ---------------------------- */
function checkAndAdvanceLinkedGoal(goalId){
  if(!STORE.goals || !goalId) return;
  const goal = STORE.goals.find(g => g.id === goalId);
  if(goal){
    if(goal.subtasks && goal.subtasks.length){
      const pending = goal.subtasks.find(s => !s.done);
      if(pending){
        pending.done = true;
        const doneCount = goal.subtasks.filter(s => s.done).length;
        if(doneCount === goal.subtasks.length) goal.done = true;
        toast(`🎯 Goal Progress: "${goal.title}" (${doneCount}/${goal.subtasks.length} milestones)`);
      }
    } else {
      goal.done = true;
      toast(`🎯 Completed Goal: "${goal.title}"!`);
    }
    save();
  }
}

/* ---------------------------- QUICK CAPTURE 'Q' MODAL ---------------------------- */
function openQuickCaptureModal(){
  let captureType = 'task';
  const goalsList = (STORE.goals || []).filter(g => !g.done);
  const habitsList = (STORE.habits || []);

  const modalHtml = `
    <div style="font-size:14px; line-height:1.6; color:var(--text);">
      <div style="display:flex; align-items:center; gap:10px; margin-bottom:14px; padding:10px 14px; background:var(--accent-dim); border:1px solid var(--accent); border-radius:10px;">
        <span style="font-size:24px;">⚡</span>
        <div>
          <strong style="color:var(--text-bright); font-size:14px;">Instant Quick Capture</strong>
          <div class="dim" style="font-size:12px;">Capture thoughts, tasks, expenses, notes or habits instantly from anywhere (Hotkeys: 'Q' or 'N').</div>
        </div>
      </div>

      <div class="tabs" style="margin-bottom:14px;">
        <button class="tab active" data-qc-tab="task">☑ Task</button>
        <button class="tab" data-qc-tab="note">📝 Note</button>
        <button class="tab" data-qc-tab="habit">🔁 Habit Check</button>
        <button class="tab" data-qc-tab="expense">💸 Expense</button>
        <button class="tab" data-qc-tab="mistake">⚠️ Mistake</button>
      </div>

      <div id="qcContentArea">
        <!-- Task Form Default -->
        <div class="form-row"><label>Task Description *</label><input id="qcTaskText" placeholder="e.g. Finish DSA Binary Search Trees assignment" autofocus/></div>
        <div class="form-grid">
          <div class="form-row"><label>Priority</label>
            <select id="qcTaskPriority"><option value="high">🔥 High (MIT)</option><option value="medium" selected>⚡ Medium</option><option value="low">☕ Low</option></select>
          </div>
          <div class="form-row"><label>Due Time</label><input type="time" id="qcTaskTime" value="18:00"/></div>
        </div>
        <div class="form-row"><label>Link to Active Goal (Optional)</label>
          <select id="qcTaskGoal"><option value="">-- No Linked Goal --</option>${goalsList.map(g=>`<option value="${g.id}">🎯 ${escapeHtml(g.title)} (${g.timeframe})</option>`).join('')}</select>
        </div>
      </div>
    </div>

    <div class="form-actions" style="display:flex; justify-content:space-between; align-items:center; margin-top:14px;">
      <span class="dim" style="font-size:11.5px;">Press Enter to save</span>
      <div class="flex gap-8">
        <button class="btn btn-ghost" id="qcCancelBtn">Cancel</button>
        <button class="btn btn-accent" id="qcSaveBtn">Save Entry →</button>
      </div>
    </div>
  `;

  openModal('⚡ Quick Capture (Press Q)', modalHtml, modal => {
    const renderQcForm = (type) => {
      captureType = type;
      modal.querySelectorAll('[data-qc-tab]').forEach(t => t.classList.toggle('active', t.dataset.qcTab === type));
      const area = modal.querySelector('#qcContentArea');
      if(!area) return;

      if(type === 'task'){
        area.innerHTML = `
          <div class="form-row"><label>Task Description *</label><input id="qcTaskText" placeholder="e.g. Finish DSA Binary Search Trees assignment"/></div>
          <div class="form-grid">
            <div class="form-row"><label>Priority</label>
              <select id="qcTaskPriority"><option value="high">🔥 High (MIT)</option><option value="medium" selected>⚡ Medium</option><option value="low">☕ Low</option></select>
            </div>
            <div class="form-row"><label>Due Time</label><input type="time" id="qcTaskTime" value="18:00"/></div>
          </div>
          <div class="form-row"><label>Link to Active Goal (Optional)</label>
            <select id="qcTaskGoal"><option value="">-- No Linked Goal --</option>${goalsList.map(g=>`<option value="${g.id}">🎯 ${escapeHtml(g.title)} (${g.timeframe})</option>`).join('')}</select>
          </div>
        `;
      } else if(type === 'note'){
        area.innerHTML = `
          <div class="form-row"><label>Note Title *</label><input id="qcNoteTitle" placeholder="e.g. React performance memoization rules"/></div>
          <div class="form-row"><label>Tags (comma separated)</label><input id="qcNoteTags" placeholder="dsa, frontend, ideas"/></div>
          <div class="form-row"><label>Content</label><textarea id="qcNoteContent" placeholder="Key ideas, code snippets, takeaways…" style="min-height:90px;"></textarea></div>
        `;
      } else if(type === 'habit'){
        const today = todayStr();
        const log = STORE.habitLogs[today] || {};
        area.innerHTML = `
          <div class="form-row"><label>Select Habit to Complete Today *</label>
            ${habitsList.length ? `
              <div style="display:flex; flex-direction:column; gap:6px; max-height:180px; overflow-y:auto;">
                ${habitsList.map(h => {
                  const isDone = log[h.id] === 'done';
                  return `
                    <label class="flex between items-center" style="padding:8px 12px; background:var(--bg-2); border-radius:8px; cursor:pointer; border:1px solid ${isDone ? 'var(--accent)' : 'var(--border)'};">
                      <span style="font-weight:600;">${escapeHtml(h.name)} <span class="dim" style="font-size:11px;">(${h.category})</span></span>
                      <input type="checkbox" class="qc-habit-chk" data-hid="${h.id}" ${isDone ? 'checked' : ''} style="accent-color:var(--accent); width:18px; height:18px;" />
                    </label>
                  `;
                }).join('')}
              </div>
            ` : '<div class="dim">No habits configured yet. Add habits first.</div>'}
          </div>
        `;
      } else if(type === 'expense'){
        area.innerHTML = `
          <div class="form-grid">
            <div class="form-row"><label>Amount (₹) *</label><input type="number" id="qcAmount" placeholder="e.g. 150"/></div>
            <div class="form-row"><label>Category</label>
              <select id="qcExpenseCat">${EXPENSE_CATEGORIES.map(c=>`<option value="${c}">${c}</option>`).join('')}</select>
            </div>
          </div>
          <div class="form-row"><label>Note / Description</label><input id="qcExpenseNote" placeholder="e.g. Lunch with team / campus canteen"/></div>
        `;
      } else if(type === 'mistake'){
        area.innerHTML = `
          <div class="form-row"><label>What went wrong? *</label><input id="qcMistakeDesc" placeholder="e.g. Missed edge case in binary search with duplicate elements"/></div>
          <div class="form-row"><label>Lesson Learned (Spaced Repetition Review)</label><textarea id="qcMistakeLesson" placeholder="Always check low <= high and handle duplicates explicitly..." style="min-height:70px;"></textarea></div>
          <div class="form-row"><label>Category</label>
            <select id="qcMistakeCat">${MISTAKE_CATEGORIES.map(c=>`<option value="${c}">${c}</option>`).join('')}</select>
          </div>
        `;
      }
    };

    modal.querySelectorAll('[data-qc-tab]').forEach(btn => {
      btn.addEventListener('click', () => renderQcForm(btn.dataset.qcTab));
    });

    modal.querySelector('#qcCancelBtn')?.addEventListener('click', closeModal);

    modal.querySelector('#qcSaveBtn')?.addEventListener('click', () => {
      const today = todayStr();
      if(captureType === 'task'){
        const text = modal.querySelector('#qcTaskText')?.value?.trim();
        if(!text) return toast('Please enter a task description');
        const priority = modal.querySelector('#qcTaskPriority')?.value || 'medium';
        const time = modal.querySelector('#qcTaskTime')?.value || '';
        const goalId = modal.querySelector('#qcTaskGoal')?.value || null;
        if(!STORE.plannerData) STORE.plannerData = {};
        if(!STORE.plannerData[today]) STORE.plannerData[today] = { tasks: [], mood: null, water: 0, notes: '' };
        STORE.plannerData[today].tasks.push({ id: uid(), text, priority, time, goalId, notes: '', done: false, createdAt: new Date().toISOString() });
        save(); closeModal(); render();
        toast('⚡ Task added to Daily Planner!');
      } else if(captureType === 'note'){
        const title = modal.querySelector('#qcNoteTitle')?.value?.trim();
        if(!title) return toast('Please enter a note title');
        const tags = modal.querySelector('#qcNoteTags')?.value?.trim() || '';
        const content = modal.querySelector('#qcNoteContent')?.value?.trim() || '';
        STORE.notes.unshift({ id: uid(), title, tags, content, updatedAt: today });
        save(); closeModal(); render();
        toast('📝 Note saved to Knowledge Base!');
      } else if(captureType === 'habit'){
        modal.querySelectorAll('.qc-habit-chk').forEach(chk => {
          const hid = chk.dataset.hid;
          if(!STORE.habitLogs[today]) STORE.habitLogs[today] = {};
          STORE.habitLogs[today][hid] = chk.checked ? 'done' : 'skipped';
        });
        save(); closeModal(); render();
        toast('🔁 Habits updated!');
      } else if(captureType === 'expense'){
        const amount = Number(modal.querySelector('#qcAmount')?.value) || 0;
        if(amount <= 0) return toast('Please enter a valid amount');
        const category = modal.querySelector('#qcExpenseCat')?.value || 'Food';
        const note = modal.querySelector('#qcExpenseNote')?.value?.trim() || '';
        STORE.finance.push({ id: uid(), type: 'expense', amount, category, note, date: today });
        save(); closeModal(); render();
        toast(`💸 Logged ₹${amount} expense under ${category}`);
      } else if(captureType === 'mistake'){
        const description = modal.querySelector('#qcMistakeDesc')?.value?.trim();
        if(!description) return toast('Please describe the mistake');
        const lesson = modal.querySelector('#qcMistakeLesson')?.value?.trim() || 'Review and practice';
        const category = modal.querySelector('#qcMistakeCat')?.value || 'Coding';
        STORE.mistakes.push({ id: uid(), description, lesson, prevention: 'Consistent practice and check', category, date: today, srsStage: 0, reviewCount: 0, nextReviewDate: today });
        save(); closeModal(); render();
        toast('⚠️ Mistake logged for Spaced Repetition Review!');
      }
    });
  });
}

/* ---------------------------- AI FLASHCARDS & STUDY ASSISTANT ---------------------------- */
function generateFlashcardDeck(sourceFilter = 'all'){
  const cards = [];
  
  // From Mistakes (SRS)
  if(sourceFilter === 'all' || sourceFilter === 'mistakes'){
    (STORE.mistakes || []).forEach(m => {
      cards.push({
        id: 'fc_m_' + m.id,
        sourceType: 'Mistake & Lesson',
        sourceColor: '#f87171',
        front: m.description,
        back: `<strong>💡 Lesson Learned:</strong><br/>${mdLite(escapeHtml(m.lesson))}${m.prevention ? `<br/><br/><strong>🛡️ Prevention Action:</strong><br/>${escapeHtml(m.prevention)}` : ''}`,
        tag: m.category || 'General',
        srsStage: m.srsStage || 0,
        rawObj: m
      });
    });
  }

  // From Notes
  if(sourceFilter === 'all' || sourceFilter === 'notes'){
    (STORE.notes || []).forEach(n => {
      cards.push({
        id: 'fc_n_' + n.id,
        sourceType: 'Knowledge Note',
        sourceColor: '#17e0b8',
        front: n.title,
        back: mdLite(escapeHtml(n.content)),
        tag: n.tags || 'Note',
        srsStage: 0,
        rawObj: n
      });
    });
  }

  // From Exams Topics
  if(sourceFilter === 'all' || sourceFilter === 'exams'){
    ((STORE.exams?.list || []).flatMap(e => e.subjects || [])).forEach(s => {
      if(s.importantTopics || s.notes){
        cards.push({
          id: 'fc_e_' + (s.id || uid()),
          sourceType: `Exam: ${s.name || s.subject || 'Subject'}`,
          sourceColor: '#8c93ff',
          front: `Exam Revision: ${s.name || s.subject || 'Subject'} (${(s.category || s.examType || s.type || 'Exam').toUpperCase()})`,
          back: `<strong>📌 Key Topics:</strong><br/>${escapeHtml(s.importantTopics || 'None')}<br/><br/><strong>📝 Study Notes:</strong><br/>${escapeHtml(s.notes || 'None')}`,
          tag: s.category || s.examType || 'Exam',
          srsStage: 0,
          rawObj: s
        });
      }
    });
  }

  return cards;
}

function openFlashcardsStudyModal(initialSource = 'all'){
  let currentDeck = generateFlashcardDeck(initialSource);
  let currentIndex = 0;
  let isFlipped = false;

  const modalHtml = `
    <div style="font-size:14px; line-height:1.6; color:var(--text);">
      <div class="flex between items-center wrap gap-8 mb-10">
        <div class="flex items-center gap-8">
          <span style="font-size:24px;">🎴</span>
          <div>
            <strong style="color:var(--text-bright); font-size:15px;">Smart Flashcards &amp; SRS Study Mode</strong>
            <div class="dim" style="font-size:11.5px;">Test your memory and advance spaced repetition mastery.</div>
          </div>
        </div>
        <div class="flex gap-4">
          <button class="btn btn-xs ${initialSource==='all'?'btn-accent':'btn-ghost'}" data-fc-source="all">All Sources</button>
          <button class="btn btn-xs ${initialSource==='mistakes'?'btn-accent':'btn-ghost'}" data-fc-source="mistakes">Mistakes</button>
          <button class="btn btn-xs ${initialSource==='notes'?'btn-accent':'btn-ghost'}" data-fc-source="notes">Notes</button>
          <button class="btn btn-xs ${initialSource==='exams'?'btn-accent':'btn-ghost'}" data-fc-source="exams">Exams</button>
        </div>
      </div>

      <div id="fcPlayerContainer">
        <!-- Dynamic Player Injected Here -->
      </div>
    </div>
  `;

  openModal('🎴 Flashcard Study Mode', modalHtml, modal => {
    function renderCardUI(){
      const container = modal.querySelector('#fcPlayerContainer');
      if(!container) return;

      if(!currentDeck.length){
        container.innerHTML = `
          <div class="card text-center" style="padding:36px 20px;">
            <div style="font-size:36px; margin-bottom:10px;">📭</div>
            <div style="font-weight:700; font-size:15px; color:var(--text-bright); margin-bottom:4px;">No Flashcards in this Category</div>
            <div class="dim" style="font-size:12.5px; margin-bottom:16px;">Add notes in Knowledge Base, log mistakes with lessons, or add exam subjects to generate cards.</div>
            <button class="btn btn-accent" id="fcCreateNoteBtn">+ Add a Note to Study</button>
          </div>
        `;
        modal.querySelector('#fcCreateNoteBtn')?.addEventListener('click', () => { closeModal(); openNoteModal(); });
        return;
      }

      const card = currentDeck[currentIndex];
      const total = currentDeck.length;

      container.innerHTML = `
        <div class="flex between align-center mb-6">
          <span class="pill" style="background:${card.sourceColor}22; color:${card.sourceColor}; border:1px solid ${card.sourceColor}55; font-size:11px; font-weight:700;">
            ${escapeHtml(card.sourceType)} · ${escapeHtml(card.tag)}
          </span>
          <span class="mono dim" style="font-size:12px; font-weight:700;">Card ${currentIndex + 1} / ${total}</span>
        </div>

        <!-- 3D Flip Card -->
        <div class="flashcard-box ${isFlipped ? 'flipped' : ''}" id="flashcardElement" title="Click or tap to flip card">
          <div class="flashcard-inner">
            <div class="flashcard-front">
              <div class="dim" style="font-size:11px; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:10px;">Prompt / Question</div>
              <div style="font-size:18px; font-weight:700; color:var(--text-bright); line-height:1.5;">${escapeHtml(card.front)}</div>
              <div class="dim" style="font-size:11px; margin-top:20px;">(Click anywhere on card to flip &amp; reveal answer 🔄)</div>
            </div>
            <div class="flashcard-back">
              <div class="dim" style="font-size:11px; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:8px; color:var(--accent);">Answer &amp; Takeaway</div>
              <div style="font-size:14px; text-align:left; color:var(--text-bright); width:100%; line-height:1.6;">${card.back}</div>
            </div>
          </div>
        </div>

        <!-- Rating & Navigation Controls -->
        <div class="flex between align-center wrap gap-8 mt-12 pt-10" style="border-top:1px solid var(--border-soft);">
          <div class="flex gap-6">
            <button class="btn btn-sm btn-ghost" id="fcPrevBtn" ${currentIndex === 0 ? 'disabled style="opacity:0.4;"' : ''}>← Prev</button>
            <button class="btn btn-sm btn-ghost" id="fcShuffleBtn" title="Shuffle Deck">🔀 Shuffle</button>
            <button class="btn btn-sm btn-accent" id="fcFlipBtn">🔄 Flip</button>
            <button class="btn btn-sm btn-ghost" id="fcNextBtn" ${currentIndex === total - 1 ? 'disabled style="opacity:0.4;"' : ''}>Next →</button>
          </div>

          <div class="flex gap-6 items-center">
            <span class="dim" style="font-size:11px;">Grade mastery:</span>
            <button class="btn btn-sm btn-danger" id="fcGradeHardBtn" title="Difficult / Repeat">🔴 Hard</button>
            <button class="btn btn-sm btn-ghost" id="fcGradeMedBtn" style="border:1px solid #fbbf24; color:#fbbf24;" title="Good Recall (+1 SRS)">🟡 Medium</button>
            <button class="btn btn-sm btn-accent" id="fcGradeEasyBtn" title="Mastered (+2 SRS)">🟢 Easy</button>
          </div>
        </div>
      `;

      // Card Flip Click
      modal.querySelector('#flashcardElement')?.addEventListener('click', () => {
        isFlipped = !isFlipped;
        modal.querySelector('#flashcardElement')?.classList.toggle('flipped', isFlipped);
      });
      modal.querySelector('#fcFlipBtn')?.addEventListener('click', () => {
        isFlipped = !isFlipped;
        modal.querySelector('#flashcardElement')?.classList.toggle('flipped', isFlipped);
      });

      modal.querySelector('#fcPrevBtn')?.addEventListener('click', () => {
        if(currentIndex > 0){ currentIndex--; isFlipped = false; renderCardUI(); }
      });
      modal.querySelector('#fcNextBtn')?.addEventListener('click', () => {
        if(currentIndex < total - 1){ currentIndex++; isFlipped = false; renderCardUI(); }
      });
      modal.querySelector('#fcShuffleBtn')?.addEventListener('click', () => {
        currentDeck = currentDeck.sort(() => Math.random() - 0.5);
        currentIndex = 0; isFlipped = false; renderCardUI();
        toast('🔀 Flashcard deck shuffled!');
      });

      // SRS Grading Actions
      modal.querySelector('#fcGradeHardBtn')?.addEventListener('click', () => {
        if(card.rawObj && card.sourceType.includes('Mistake')){
          card.rawObj.srsStage = Math.max(0, (card.rawObj.srsStage || 0) - 1);
          card.rawObj.nextReviewDate = todayStr();
          save();
        }
        toast('🔴 Marked as Hard. Scheduled for quick repeat!');
        if(currentIndex < total - 1){ currentIndex++; isFlipped = false; renderCardUI(); }
      });
      modal.querySelector('#fcGradeMedBtn')?.addEventListener('click', () => {
        if(card.rawObj && card.sourceType.includes('Mistake')){
          card.rawObj.srsStage = Math.min(5, (card.rawObj.srsStage || 0) + 1);
          card.rawObj.reviewCount = (card.rawObj.reviewCount || 0) + 1;
          const intervals = [1, 3, 7, 14, 30, 60];
          card.rawObj.nextReviewDate = addDays(todayStr(), intervals[card.rawObj.srsStage] || 30);
          save();
        }
        toast('🟡 Good Recall! SRS stage increased.');
        if(currentIndex < total - 1){ currentIndex++; isFlipped = false; renderCardUI(); }
      });
      modal.querySelector('#fcGradeEasyBtn')?.addEventListener('click', () => {
        if(card.rawObj && card.sourceType.includes('Mistake')){
          card.rawObj.srsStage = Math.min(5, (card.rawObj.srsStage || 0) + 2);
          card.rawObj.reviewCount = (card.rawObj.reviewCount || 0) + 1;
          const intervals = [1, 3, 7, 14, 30, 60];
          card.rawObj.nextReviewDate = addDays(todayStr(), intervals[card.rawObj.srsStage] || 30);
          save();
        }
        toast('🟢 Mastered! Advanced spaced repetition interval.');
        if(currentIndex < total - 1){ currentIndex++; isFlipped = false; renderCardUI(); }
      });
    }

    modal.querySelectorAll('[data-fc-source]').forEach(btn => {
      btn.addEventListener('click', () => {
        const src = btn.dataset.fcSource;
        modal.querySelectorAll('[data-fc-source]').forEach(b => b.classList.toggle('btn-accent', b.dataset.fcSource === src));
        modal.querySelectorAll('[data-fc-source]').forEach(b => b.classList.toggle('btn-ghost', b.dataset.fcSource !== src));
        currentDeck = generateFlashcardDeck(src);
        currentIndex = 0;
        isFlipped = false;
        renderCardUI();
      });
    });

    renderCardUI();
  });
}

/* ---------------------------- SERVER-ENFORCED CYCLE WORKFLOW ---------------------------- */
let SERVER_CYCLE_STATE = null;
let SERVER_CYCLE_RULES = {
  minScoreForReset: 85,
  cycle1LockPeriodDays: 30,
  maxCycles: 3,
  requireReasonForReset: true,
  defaultCycleDurationDays: 90
};

function fetchAndSyncServerCycleState(cb){
  const scores = evaluateCyclePerformanceScores();
  const sched = STORE.settings?.schedule || {};
  fetch('/api/cycle/sync', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      currentScores: scores,
      clientToday: todayStr(),
      clientSchedule: sched.startDate ? {
        startDate: sched.startDate,
        endDate: sched.endDate,
        currentCycle: sched.currentCycle,
        cycleGoal: sched.cycleGoal,
        durationDays: sched.durationDays
      } : null
    })
  })
  .then(res => res.json())
  .then(data => {
    if(data && data.state){
      SERVER_CYCLE_STATE = data.state;
      if(data.rules) SERVER_CYCLE_RULES = data.rules;
      if(STORE && STORE.settings && STORE.settings.schedule){
        // Only update local schedule from server if local schedule does NOT have a user-selected start date
        // OR if server state has a higher cycle number / newer confirmed state
        if(!STORE.settings.schedule.startDate && SERVER_CYCLE_STATE.target_schedule_date?.startDate){
          STORE.settings.schedule.startDate = SERVER_CYCLE_STATE.target_schedule_date.startDate;
          STORE.settings.schedule.endDate = SERVER_CYCLE_STATE.target_schedule_date.endDate;
          STORE.settings.schedule.currentCycle = SERVER_CYCLE_STATE.cycle_number || 1;
          STORE.settings.schedule.cycleGoal = SERVER_CYCLE_STATE.cycle_goal || STORE.settings.schedule.cycleGoal;
          STORE.settings.schedule.durationDays = SERVER_CYCLE_STATE.duration_days || STORE.settings.schedule.durationDays;
        } else if(SERVER_CYCLE_STATE.cycle_number && STORE.settings.schedule.currentCycle && SERVER_CYCLE_STATE.cycle_number > STORE.settings.schedule.currentCycle){
          STORE.settings.schedule.currentCycle = SERVER_CYCLE_STATE.cycle_number;
          if(SERVER_CYCLE_STATE.target_schedule_date?.startDate){
            STORE.settings.schedule.startDate = SERVER_CYCLE_STATE.target_schedule_date.startDate;
            STORE.settings.schedule.endDate = SERVER_CYCLE_STATE.target_schedule_date.endDate;
          }
        }
        STORE.settings.schedule.locked = (SERVER_CYCLE_STATE.status === 'LOCKED' || SERVER_CYCLE_STATE.status === 'ACTIVE');
        STORE.settings.schedule.lockUntil = SERVER_CYCLE_STATE.lock_until || STORE.settings.schedule.lockUntil;
        STORE.settings.schedule.cycleState = SERVER_CYCLE_STATE;
        save();
      }
    }
    if(typeof cb === 'function') cb(SERVER_CYCLE_STATE);
  })
  .catch(err => {
    console.warn('Server cycle sync note:', err);
    if(typeof cb === 'function') cb(null);
  });
}

function evaluateCyclePerformanceScores(){
  const sched = getSchedule();
  const today = todayStr();
  
  // 1. Habit Completion Average
  const logDates = Object.keys(STORE.habitLogs || {});
  let totalHabitScore = 0;
  let habitDayCount = 0;
  logDates.forEach(d => {
    const r = dayCompletionRatio(d);
    if(r !== null){
      totalHabitScore += Math.round(r * 100);
      habitDayCount++;
    }
  });
  const avgHabitScore = habitDayCount > 0 ? Math.round(totalHabitScore / habitDayCount) : 85;

  // 2. Daily Tasks Completion
  const planDates = Object.keys(STORE.plannerData || {});
  let totalTaskScore = 0;
  let taskDayCount = 0;
  planDates.forEach(d => {
    const plan = STORE.plannerData[d];
    if(plan && Array.isArray(plan.tasks) && plan.tasks.length > 0){
      const done = plan.tasks.filter(t => t.done).length;
      totalTaskScore += Math.round((done / plan.tasks.length) * 100);
      taskDayCount++;
    }
  });
  const avgTaskScore = taskDayCount > 0 ? Math.round(totalTaskScore / taskDayCount) : 85;

  // 3. Productivity & Journey Overall Score
  const journeyPct = overallCompletionPct();
  const prodToday = getProductivityForDate(today);
  const overallDisciplineScore = Math.min(100, Math.round((avgHabitScore * 0.4) + (avgTaskScore * 0.3) + (journeyPct * 0.3)));

  return {
    habitScore: avgHabitScore,
    taskScore: avgTaskScore,
    productivityScore: prodToday,
    overallScore: Math.max(overallDisciplineScore, 80),
    evaluatedAt: new Date().toISOString()
  };
}

/* ==========================================================================
   CENTRALIZED PERSONALIZATION & MODULE VISIBILITY ARCHITECTURE
   ========================================================================== */
function isModuleEnabled(modId) {
  if (!modId) return true;
  // Core foundational system modules always enabled
  if (modId === 'dashboard' || modId === 'profile' || modId === 'settings' || modId === 'admin' || modId === 'analytics' || modId === 'badges') return true;
  if (!STORE || !STORE.settings) return true;

  // Primary check: activeModules array (personalization settings)
  if (Array.isArray(STORE.settings.activeModules)) {
    return STORE.settings.activeModules.includes(modId);
  }

  // Fallback checks: enabledModules object or disabledModules array
  if (STORE.user && STORE.user.profile && STORE.user.profile.enabledModules && typeof STORE.user.profile.enabledModules === 'object') {
    if (STORE.user.profile.enabledModules[modId] === false) return false;
  }
  if (STORE.settings.enabledModules && typeof STORE.settings.enabledModules === 'object') {
    if (STORE.settings.enabledModules[modId] === false) return false;
  }
  if (Array.isArray(STORE.settings.disabledModules)) {
    if (STORE.settings.disabledModules.includes(modId)) return false;
  }

  // Default: initialize activeModules with all standard modules
  STORE.settings.activeModules = ['planner', 'habits', 'journal', 'projects', 'goals', 'mistakes'];
  return STORE.settings.activeModules.includes(modId);
}

function updateSidebarNavVisibility() {
  const nav = document.getElementById('nav');
  if (!nav) return;

  // 1. Show / Hide individual navigation items based on module configuration
  nav.querySelectorAll('.nav-item[data-section]').forEach(btn => {
    const sec = btn.dataset.section;
    const enabled = isModuleEnabled(sec);
    btn.style.display = enabled ? '' : 'none';
  });

  // 2. Clean up section group labels if all items in that group are disabled
  const children = Array.from(nav.children || []);
  let currentGroupLabel = null;
  let currentGroupVisibleCount = 0;

  children.forEach(child => {
    if (child.classList.contains('nav-group-label')) {
      if (currentGroupLabel) {
        currentGroupLabel.style.display = currentGroupVisibleCount > 0 ? '' : 'none';
      }
      currentGroupLabel = child;
      currentGroupVisibleCount = 0;
    } else if (child.classList.contains('nav-item')) {
      if (child.style.display !== 'none') {
        currentGroupVisibleCount++;
      }
    }
  });
  if (currentGroupLabel) {
    currentGroupLabel.style.display = currentGroupVisibleCount > 0 ? '' : 'none';
  }
}

function computeCycleLockUntil(currentCycle = 1, startDate = null, endDate = null, durationDays = null){
  const start = startDate || todayStr();
  let dur = Number(durationDays);
  if(!dur || isNaN(dur) || dur <= 0){
    if(endDate){
      dur = Math.max(1, diffDays(start, endDate) + 1);
    } else {
      dur = 90;
    }
  }
  const end = endDate || addDays(start, Math.max(1, dur) - 1);
  const total = Math.max(1, diffDays(start, end) + 1);

  if (currentCycle === 1) {
    if (total <= 1) {
      return end; // 1-day target locks only for that single day
    } else if (total < 60) {
      // Under 2 months: 50% of the selected date range from start
      const lockOffset = Math.max(0, Math.round(total * 0.5) - 1);
      return addDays(start, lockOffset);
    } else {
      // 60+ days: first 30 days (0..29) from start date
      return addDays(start, Math.min(29, total - 1));
    }
  } else if (currentCycle === 2) {
    // 85% progression threshold
    const lockOffset = Math.max(0, Math.min(total - 1, Math.round(total * 0.85) - 1));
    return addDays(start, lockOffset);
  } else {
    // Cycle 3: full completion ending on End Date
    return end;
  }
}

function getSchedule(){
  const sched = (STORE && STORE.settings && STORE.settings.schedule) ? STORE.settings.schedule : {};
  
  // Single authoritative source of truth: user-selected sched.startDate
  const startDate = sched.startDate || (SERVER_CYCLE_STATE?.target_schedule_date?.startDate) || todayStr();
  const currentCycle = (typeof sched.currentCycle === 'number') ? sched.currentCycle : ((SERVER_CYCLE_STATE?.cycle_number) || 1);
  
  let durationDays = Number(sched.durationDays);
  if (!durationDays || isNaN(durationDays) || durationDays <= 0) {
    if (sched.endDate) {
      durationDays = Math.max(1, diffDays(startDate, sched.endDate) + 1);
    } else {
      durationDays = Number(SERVER_CYCLE_STATE?.duration_days) || 90;
    }
  }
  
  const endDate = sched.endDate || (SERVER_CYCLE_STATE?.target_schedule_date?.endDate) || addDays(startDate, Math.max(1, durationDays) - 1);
  const totalDays = Math.max(1, diffDays(startDate, endDate) + 1);
  const isLocked = (sched.locked === true) || (SERVER_CYCLE_STATE ? (SERVER_CYCLE_STATE.status === 'LOCKED' || SERVER_CYCLE_STATE.status === 'ACTIVE') : false);

  // Dynamically compute lock date strictly from user-selected start date and duration
  const finalLockUntil = computeCycleLockUntil(currentCycle, startDate, endDate, totalDays);

  return {
    startDate,
    endDate,
    durationDays: totalDays,
    editsRemaining: typeof sched.editsRemaining === 'number' ? sched.editsRemaining : 3,
    locked: isLocked,
    currentCycle,
    maxCycles: typeof sched.maxCycles === 'number' ? sched.maxCycles : 3,
    cycleGoal: sched.cycleGoal || (SERVER_CYCLE_STATE?.cycle_goal) || `Complete ${totalDays}-day Productivity Target Journey`,
    lockUntil: finalLockUntil,
    status: (SERVER_CYCLE_STATE?.status) || (isLocked ? 'LOCKED' : 'ACTIVE')
  };
}

function scheduleTotalDays(){
  const { startDate, endDate, durationDays } = getSchedule();
  if (startDate && endDate) {
    return Math.max(1, diffDays(startDate, endDate) + 1);
  }
  return Math.max(1, Number(durationDays) || 90);
}

function currentDayNumber(){
  const { startDate, endDate, durationDays } = getSchedule();
  const today = todayStr();
  const total = scheduleTotalDays();
  if (today < startDate) return 0; // Future target
  if (today > endDate) return total; // Completed target
  const diff = diffDays(startDate, today);
  return clamp(diff + 1, 1, total);
}

function overallCompletionPct(){
  const { startDate, endDate, durationDays } = getSchedule();
  const total = scheduleTotalDays();
  if (!total) return 0;
  const today = todayStr();
  if (today < startDate) return 0; // Future target
  if (today > endDate) return 100; // Completed target
  if (total === 1) {
    // 1-day target: check habit/task completion for today
    const log = STORE?.habitLogs?.[today] || {};
    const doneHabits = (STORE?.habits || []).filter(h => log[h.id] === 'done').length;
    const totalHabits = (STORE?.habits || []).length;
    return totalHabits > 0 ? clamp(Math.round((doneHabits / totalHabits) * 100), 0, 100) : 50;
  }
  const dayNum = currentDayNumber();
  const completedDays = Math.max(0, dayNum - 1);
  return clamp(Math.round((completedDays / total) * 100), 0, 100);
}

function daysRemaining(){
  const { startDate, endDate, durationDays } = getSchedule();
  const today = todayStr();
  if (today < startDate) {
    return scheduleTotalDays();
  }
  if (today > endDate) {
    return 0;
  }
  const diff = diffDays(today, endDate);
  return Math.max(0, diff);
}

function resetScheduleCycle(){
  if(!STORE.settings.schedule) STORE.settings.schedule = {};
  STORE.settings.schedule.editsRemaining = 3;
  STORE.settings.schedule.locked = false;
  save();
}

/* ---------------------------- FIRST-TIME TARGET BUTTON EXPERIENCE & CYCLE WORKFLOWS ---------------------------- */

function isTargetSetupCompleted(){
  if(STORE?.onboarding?.completed === true && STORE?.settings?.schedule?.startDate) return true;
  if(STORE?.settings?.schedule?.targetSetupCompleted === true && STORE?.settings?.schedule?.startDate) return true;
  if(STORE?.settings?.schedule?.locked === true && STORE?.settings?.schedule?.startDate) return true;
  if(STORE?.settings?.schedule?.startDate && STORE?.settings?.schedule?.endDate) return true;
  if(SERVER_CYCLE_STATE && (SERVER_CYCLE_STATE.status === 'LOCKED' || SERVER_CYCLE_STATE.status === 'ACTIVE') && SERVER_CYCLE_STATE.target_schedule_date?.startDate) return true;
  return false;
}

function updateTargetButtonUI(){
  const isDone = isTargetSetupCompleted();
  const targetBtns = document.querySelectorAll('#targetBtn, #mobileTargetBtn, .target-action-btn, [data-action="target"]');
  targetBtns.forEach(btn => {
    if(isDone){
      btn.classList.add('is-completed');
      btn.classList.remove('btn-accent');
      if(btn.id === 'targetBtn'){
        btn.classList.add('btn-ghost');
        btn.innerHTML = '🎯 Target <span class="pill pill-accent" style="font-size:10px; margin-left:4px; padding:2px 6px; font-weight:700;">Active</span>';
      }
      btn.setAttribute('title', '🎯 Target Schedule & Checkpoints (Click to view milestones & adjust focus targets)');
      btn.setAttribute('aria-label', 'Target Schedule & Checkpoints');
      btn.style.opacity = '1';
      btn.style.cursor = 'pointer';
    } else {
      btn.classList.remove('is-completed');
      if(btn.id === 'targetBtn'){
        btn.classList.remove('btn-ghost');
        btn.classList.add('btn-accent');
        btn.innerHTML = '🎯 Target <span class="pill pill-accent2" style="font-size:10px; margin-left:4px; padding:2px 6px; font-weight:700;">Set Target</span>';
      }
      btn.setAttribute('title', '🎯 Configure Target Schedule (First-Time Setup)');
      btn.setAttribute('aria-label', 'Configure Target Schedule');
      btn.style.opacity = '1';
      btn.style.cursor = 'pointer';
    }
  });
}

function handleTargetButtonClick(e){
  if(e) e.preventDefault();
  if(isTargetSetupCompleted()){
    openMilestoneCheckpointModal();
    return;
  }
  openScheduleTargetModal();
}

function openScheduleTargetModal(initialData = null){
  const sched = getSchedule();
  const today = todayStr();
  const isLocked = (isTargetSetupCompleted() || sched.locked) && !initialData?._allowSetup;
  if(isLocked){
    openMilestoneCheckpointModal();
    return;
  }

  const rawStart = initialData?.startDate || sched.startDate || today;
  const defaultStart = rawStart < today ? today : rawStart;
  const rawEnd = initialData?.endDate || sched.endDate || addDays(defaultStart, 89);
  const defaultEnd = rawEnd < defaultStart ? addDays(defaultStart, 89) : rawEnd;
  const defaultWake = initialData?.wakeTime || (STORE.settings?.schedule?.wakeTime) || '04:30';
  const defaultSleep = initialData?.sleepTime || (STORE.settings?.schedule?.sleepTime) || '22:00';
  const defaultFocus = initialData?.focusHours || (STORE.settings?.schedule?.dailyFocusTarget) || 8;
  const defaultGoal = initialData?.goal || sched.cycleGoal || 'Complete target journey with consistent habits and high focus execution';

  const initialDays = Math.max(1, diffDays(defaultStart, defaultEnd) + 1);

  const modalHtml = `
    <div style="font-size:14px; line-height:1.6; color:var(--text);">
      <div style="display:flex; align-items:center; gap:10px; margin-bottom:12px; padding:10px 12px; background:var(--accent-dim); border:1px solid var(--accent); border-radius:10px;">
        <span style="font-size:24px;">🎯</span>
        <div>
          <strong style="color:var(--text-bright); font-size:14px;">Schedule Target Setup</strong>
          <div class="dim" style="font-size:12px;">Configure your target journey dates, daily time routine, and cycle objective.</div>
        </div>
      </div>

      <!-- 1. DATE SELECTION -->
      <div class="card" style="background:var(--bg-2); padding:14px; margin-bottom:12px; border:1px solid var(--border-soft);">
        <div class="flex between align-center" style="margin-bottom:8px;">
          <strong style="color:var(--text-bright); font-size:13.5px;">📅 1. Target Journey Dates</strong>
          <span id="stDurationBadge" class="pill pill-accent" style="font-weight:700;">${initialDays} Days Duration</span>
        </div>
        <div class="form-grid" style="display:grid; grid-template-columns:1fr 1fr; gap:10px;">
          <div class="form-row">
            <label>Start Date * <span class="dim" style="font-size:11px;">(Today onwards)</span></label>
            <input type="date" id="stStartDate" value="${defaultStart}" min="${today}" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-3); color:var(--text);"/>
          </div>
          <div class="form-row">
            <label>End Date * <span class="dim" style="font-size:11px;">(Target finish)</span></label>
            <input type="date" id="stEndDate" value="${defaultEnd}" min="${defaultStart}" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-3); color:var(--text);"/>
          </div>
        </div>
        <div style="margin-top:8px;">
          <div class="dim" style="font-size:11px; margin-bottom:4px;">Quick Duration Presets:</div>
          <div class="flex gap-6 wrap">
            ${[1, 3, 7, 14, 30, 60, 90, 120, 180, 365].map(d => `
              <button type="button" class="btn btn-sm ${initialDays === d ? 'btn-accent' : 'btn-ghost'}" data-preset-days="${d}" style="border:1px solid ${initialDays === d ? 'var(--accent)' : 'var(--border-soft)'};">+${d} Day${d > 1 ? 's' : ''}</button>
            `).join('')}
          </div>
        </div>
      </div>

      <!-- 2. SCHEDULE & TIME SELECTION -->
      <div class="card" style="background:var(--bg-2); padding:14px; margin-bottom:12px; border:1px solid var(--border-soft);">
        <strong style="color:var(--text-bright); font-size:13.5px; display:block; margin-bottom:8px;">⏱️ 2. Required Schedule &amp; Daily Routine Times</strong>
        <div class="form-grid" style="display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px;">
          <div class="form-row">
            <label>Wake Up Time *</label>
            <input type="time" id="stWakeTime" value="${defaultWake}" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-3); color:var(--text);"/>
          </div>
          <div class="form-row">
            <label>Sleep / Rest Time *</label>
            <input type="time" id="stSleepTime" value="${defaultSleep}" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-3); color:var(--text);"/>
          </div>
          <div class="form-row">
            <label>Focus Hours (hrs/day)</label>
            <input type="number" id="stFocusHours" min="1" max="24" value="${defaultFocus}" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-3); color:var(--text);"/>
          </div>
        </div>
        <div style="margin-top:10px; padding:8px 10px; background:var(--bg-3); border-radius:8px; border:1px solid var(--border-soft); font-size:12px; line-height:1.5;">
          <div class="dim" style="font-weight:600; margin-bottom:4px;">Daily Routine Plan:</div>
          <div class="flex between wrap gap-6" style="color:var(--text-dim);">
            <span>🌅 Morning Routine</span>
            <span>⚔️ Deep Study &amp; Coding</span>
            <span>♥ Body &amp; Fitness</span>
            <span>🌙 Evening Review</span>
          </div>
        </div>
      </div>

      <!-- 3. CYCLE GOAL -->
      <div class="card" style="background:var(--bg-2); padding:14px; margin-bottom:14px; border:1px solid var(--border-soft);">
        <strong style="color:var(--text-bright); font-size:13.5px; display:block; margin-bottom:8px;">🎯 3. Cycle Goal &amp; Objective *</strong>
        <input id="stCycleGoal" value="${escapeHtml(defaultGoal)}" placeholder="e.g. Complete target journey with consistent habits and high focus" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-3); color:var(--text); font-size:13px;"/>
      </div>
    </div>

    <div class="form-actions" style="display:flex; justify-content:flex-end; gap:8px;">
      <button class="btn btn-ghost" id="stCancelBtn">Cancel</button>
      <button class="btn btn-accent" id="stSaveBtn">Save &amp; Review Schedule →</button>
    </div>
  `;

  openModal('Schedule Target Setup', modalHtml, modalEl => {
    const startInput = modalEl.querySelector('#stStartDate');
    const endInput = modalEl.querySelector('#stEndDate');
    const badge = modalEl.querySelector('#stDurationBadge');

    function updateDuration(){
      if(!startInput || !endInput || !badge) return;
      const curToday = todayStr();
      const s = startInput.value;
      const e = endInput.value;

      if(s && endInput){
        endInput.min = s < curToday ? curToday : s;
      }

      if(s && e){
        try{
          const days = diffDays(s, e) + 1;
          if(s < curToday){
            badge.textContent = 'Invalid (Past Start Date)';
            badge.className = 'pill pill-danger';
          } else if(days > 0){
            badge.textContent = `${days} Day${days > 1 ? 's' : ''} Duration`;
            badge.className = 'pill pill-accent';
          } else {
            badge.textContent = 'Invalid Range (End < Start)';
            badge.className = 'pill pill-danger';
          }
          modalEl.querySelectorAll('[data-preset-days]').forEach(btn => {
            const d = parseInt(btn.getAttribute('data-preset-days'), 10);
            const isActive = days === d && s >= curToday;
            btn.className = `btn btn-sm ${isActive ? 'btn-accent' : 'btn-ghost'}`;
            btn.style.border = `1px solid ${isActive ? 'var(--accent)' : 'var(--border-soft)'}`;
          });
        }catch(_){}
      }
    }

    startInput?.addEventListener('change', () => {
      const curToday = todayStr();
      if(startInput.value && startInput.value < curToday){
        startInput.value = curToday;
        toast(`Past dates are not allowed. Start Date reset to today (${curToday}).`);
      }
      if(endInput && endInput.value && endInput.value < startInput.value){
        endInput.value = startInput.value;
      }
      updateDuration();
    });

    endInput?.addEventListener('change', () => {
      const curToday = todayStr();
      const s = startInput?.value || curToday;
      if(endInput.value && endInput.value < s){
        endInput.value = s;
        toast(`End Date cannot be earlier than Start Date (${s}).`);
      }
      updateDuration();
    });

    modalEl.querySelectorAll('[data-preset-days]').forEach(btn => {
      btn.addEventListener('click', () => {
        const curToday = todayStr();
        const days = parseInt(btn.getAttribute('data-preset-days'), 10);
        let s = startInput?.value || curToday;
        if(s < curToday) s = curToday;
        if(startInput) startInput.value = s;
        if(endInput) endInput.value = addDays(s, Math.max(1, days) - 1);
        updateDuration();
      });
    });

    modalEl.querySelector('#stCancelBtn')?.addEventListener('click', closeModal);

    modalEl.querySelector('#stSaveBtn')?.addEventListener('click', () => {
      const curToday = todayStr();
      const startDate = startInput ? startInput.value.trim() : '';
      const endDate = endInput ? endInput.value.trim() : '';
      const wakeTime = modalEl.querySelector('#stWakeTime')?.value?.trim() || '04:30';
      const sleepTime = modalEl.querySelector('#stSleepTime')?.value?.trim() || '22:00';
      const focusHours = parseFloat(modalEl.querySelector('#stFocusHours')?.value) || 8;
      const goal = modalEl.querySelector('#stCycleGoal')?.value?.trim();

      // Apply strict validation & date rules
      if(!startDate || !endDate){
        return toast('Please select both Start Date and End Date.');
      }
      if(startDate < curToday){
        return toast(`Start Date cannot be before today (${curToday}). Past dates are not allowed.`);
      }
      try{
        if(parseDate(endDate) < parseDate(startDate)){
          return toast('End Date must be on or after Start Date.');
        }
      }catch(_){
        return toast('Please provide valid dates in YYYY-MM-DD format.');
      }
      const totalDays = diffDays(startDate, endDate) + 1;
      if(totalDays < 1){
        return toast('Schedule target duration must be at least 1 day.');
      }
      if(!goal){
        return toast('Please enter a goal for your target cycle.');
      }
      if(!wakeTime || !sleepTime){
        return toast('Please provide both Wake Up Time and Sleep Time.');
      }

      closeModal();
      openScheduleTargetReviewModal({
        startDate,
        endDate,
        totalDays,
        wakeTime,
        sleepTime,
        focusHours,
        goal
      });
    });
  });
}

function openScheduleTargetReviewModal(config){
  const curToday = todayStr();
  if(!config || !config.startDate || config.startDate < curToday){
    toast(`Start Date cannot be before today (${curToday}).`);
    openScheduleTargetModal(config);
    return;
  }
  if(!config.endDate || config.endDate < config.startDate){
    toast('End Date must be on or after Start Date.');
    openScheduleTargetModal(config);
    return;
  }

  const user = (STORE.settings && STORE.settings.name) || (STORE.user && (STORE.user.name || STORE.user.profile?.name)) || 'Student';
  const targetDateLabel = config.startDate === config.endDate ? `${config.startDate} (1 Day)` : `${config.startDate} → ${config.endDate}`;

  const reviewHtml = `
    <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:16px;">
      <p style="margin-bottom:12px;">
        Please review your configured target schedule parameters before confirming:
      </p>

      <div class="card" style="background:var(--bg-2); border:1px solid var(--border-soft); padding:14px; margin-bottom:14px;">
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-bottom:10px;">
          <div>
            <div class="dim" style="font-size:11px;">📅 Target Date Range</div>
            <strong style="color:var(--text-bright); font-size:13.5px;">${targetDateLabel}</strong>
            <div class="dim" style="font-size:11px;">${config.totalDays} Day${config.totalDays > 1 ? 's' : ''} Total Duration</div>
          </div>
          <div>
            <div class="dim" style="font-size:11px;">⏱️ Daily Routine &amp; Focus</div>
            <strong style="color:var(--text-bright); font-size:13.5px;">🌅 ${config.wakeTime} → 🌙 ${config.sleepTime}</strong>
            <div class="dim" style="font-size:11px;">${config.focusHours}h Focus / Day</div>
          </div>
        </div>
        <div style="border-top:1px solid var(--border-soft); padding-top:8px;">
          <div class="dim" style="font-size:11px;">🎯 Cycle 1 Objective</div>
          <div style="color:var(--text-bright); font-weight:600; font-size:13px;">"${escapeHtml(config.goal)}"</div>
        </div>
      </div>

      <div class="card" style="background:rgba(239, 68, 68, 0.08); border:1px solid rgba(239, 68, 68, 0.25); padding:12px; margin-bottom:14px;">
        <div style="font-weight:700; color:#ef4444; margin-bottom:4px; font-size:13.5px;">🔒 State-Controlled Cycle Lock Notice</div>
        <p style="font-size:13px; margin:0; line-height:1.5;">
          Once confirmed, this date range and cycle configuration will become your active target schedule. Dates and goal will be locked under cycle rules.
        </p>
      </div>

      <p style="font-weight:600; color:var(--text-bright); margin:0;">
        Are you ready to lock and confirm this target schedule?
      </p>
    </div>
    <div class="form-actions" style="display:flex; justify-content:flex-end; gap:8px;">
      <button class="btn btn-ghost" id="mBackTargetEdit">← Back &amp; Edit</button>
      <button class="btn btn-accent" id="mConfirmTargetSchedule">Confirm &amp; Lock Schedule ✓</button>
    </div>
  `;

  openModal('Review & Confirm Target Schedule', reviewHtml, modal => {
    modal.querySelector('#mBackTargetEdit')?.addEventListener('click', () => {
      closeModal();
      openScheduleTargetModal(config);
    });

    modal.querySelector('#mConfirmTargetSchedule')?.addEventListener('click', () => {
      closeModal();
      // Execute confirmation on server
      executeConfirmCycleOnServer(1, config.startDate, config.endDate, config.goal, user);

      // Save schedule metadata locally as immediate source of truth
      if(!STORE.settings) STORE.settings = {};
      if(!STORE.settings.schedule) STORE.settings.schedule = {};
      STORE.settings.schedule.startDate = config.startDate;
      STORE.settings.schedule.endDate = config.endDate;
      STORE.settings.schedule.durationDays = config.totalDays;
      STORE.settings.schedule.cycleGoal = config.goal;
      STORE.settings.schedule.wakeTime = config.wakeTime;
      STORE.settings.schedule.sleepTime = config.sleepTime;
      STORE.settings.schedule.dailyFocusTarget = config.focusHours;
      STORE.settings.schedule.targetSetupCompleted = true;
      STORE.settings.schedule.locked = true;
      STORE.settings.schedule.lockUntil = computeCycleLockUntil(1, config.startDate, config.endDate, config.totalDays);

      if(STORE.user && STORE.user.profile){
        STORE.user.profile.dailyFocusTarget = config.focusHours;
      }

      save();
      toast('🎯 Target Schedule confirmed and locked successfully! Setup complete.');
      playNotificationSound('post');
      updateTargetButtonUI();
      updateSidebarRing();
      render();
    });
  });
}

// 1. Starting a New Cycle (Cycle 1, 2, or 3)
function openStartCycleConfirmationModal(targetCycleNum, startDate, endDate, goal){
  const curToday = todayStr();
  if(!startDate || startDate < curToday){
    toast(`Start Date cannot be before today (${curToday}).`);
    return;
  }
  if(!endDate || endDate < startDate){
    toast('End Date must be on or after Start Date.');
    return;
  }

  const user = (STORE.settings && STORE.settings.name) || (STORE.user && (STORE.user.name || STORE.user.profile?.name)) || 'Student';
  const targetDateLabel = `${startDate} → ${endDate}`;

  if(targetCycleNum === 1){
    // Cycle 1 Confirmation Workflow
    openModal('Confirm Cycle Start', `
      <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:16px;">
        <p style="margin-bottom:12px;">
          You selected <strong>${targetDateLabel}</strong> as your target schedule date.
        </p>
        <div class="card" style="background:rgba(239, 68, 68, 0.08); border:1px solid rgba(239, 68, 68, 0.25); padding:12px; margin-bottom:14px;">
          <div style="font-weight:700; color:#ef4444; margin-bottom:4px; font-size:13.5px;">🔒 State-Controlled Cycle Lock Notice</div>
          <p style="font-size:13px; margin:0; line-height:1.5;">
            Once you confirm, this date and the cycle data will be locked according to the cycle rules.
            You will not be able to freely change the schedule or reset the cycle later.
          </p>
        </div>
        <p style="font-weight:600; color:var(--text-bright); margin:0;">
          Are you sure you want to continue?
        </p>
      </div>
      <div class="form-actions">
        <button class="btn btn-ghost" id="mCancelStartCycle">Cancel</button>
        <button class="btn btn-accent" id="mConfirmStartCycle">Confirm &amp; Lock Cycle</button>
      </div>
    `, modal => {
      modal.querySelector('#mCancelStartCycle')?.addEventListener('click', closeModal);
      modal.querySelector('#mConfirmStartCycle')?.addEventListener('click', () => {
        closeModal();
        executeConfirmCycleOnServer(1, startDate, endDate, goal, user);
      });
    });
  } else if(targetCycleNum === 2){
    // Cycle 2 Confirmation Workflow
    openModal('Confirm Cycle 2', `
      <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:16px;">
        <p style="margin-bottom:12px;">
          You are about to start <strong>Cycle 2</strong> (${targetDateLabel}).
        </p>
        <div class="card" style="background:rgba(234, 179, 8, 0.08); border:1px solid rgba(234, 179, 8, 0.25); padding:12px; margin-bottom:14px;">
          <div style="font-weight:700; color:#eab308; margin-bottom:4px; font-size:13.5px;">🔒 Strict Cycle 2 Locking Policy</div>
          <p style="font-size:13px; margin:0; line-height:1.5;">
            Once Cycle 2 begins, the schedule date and cycle configuration will be locked.
            Resetting or repeatedly restarting the cycle will not be available simply because you want to change the date.
          </p>
        </div>
        <p style="font-weight:600; color:var(--text-bright); margin:0;">
          Please make sure your information and target schedule are correct before continuing.
        </p>
      </div>
      <div class="form-actions">
        <button class="btn btn-ghost" id="mBackCycle2">Go Back</button>
        <button class="btn btn-accent" id="mStartCycle2">Start Cycle 2</button>
      </div>
    `, modal => {
      modal.querySelector('#mBackCycle2')?.addEventListener('click', closeModal);
      modal.querySelector('#mStartCycle2')?.addEventListener('click', () => {
        closeModal();
        executeConfirmCycleOnServer(2, startDate, endDate, goal, user);
      });
    });
  } else {
    // Cycle 3 Confirmation Workflow
    openModal('Confirm Cycle 3 (Final Locked Cycle)', `
      <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:16px;">
        <p style="margin-bottom:12px;">
          You are about to start <strong>Cycle 3</strong> (${targetDateLabel}).
        </p>
        <div class="card" style="background:rgba(239, 68, 68, 0.08); border:1px solid rgba(239, 68, 68, 0.25); padding:12px; margin-bottom:14px;">
          <div style="font-weight:700; color:#ef4444; margin-bottom:4px; font-size:13.5px;">🔒 Final Cycle Policy: Locked Until Completion</div>
          <p style="font-size:13px; margin:0; line-height:1.5;">
            Cycle 3 is strictly locked until full journey completion. No restarting or resetting Cycle 3 is permitted.
          </p>
        </div>
        <p style="font-weight:600; color:var(--text-bright); margin:0;">
          Are you ready to commit and complete Cycle 3?
        </p>
      </div>
      <div class="form-actions">
        <button class="btn btn-ghost" id="mBackCycle3">Go Back</button>
        <button class="btn btn-accent" id="mStartCycle3">Confirm &amp; Start Cycle 3</button>
      </div>
    `, modal => {
      modal.querySelector('#mBackCycle3')?.addEventListener('click', closeModal);
      modal.querySelector('#mStartCycle3')?.addEventListener('click', () => {
        closeModal();
        executeConfirmCycleOnServer(3, startDate, endDate, goal, user);
      });
    });
  }
}

function executeConfirmCycleOnServer(cycleNum, startDate, endDate, goal, user){
  const totalDays = Math.max(1, diffDays(startDate, endDate) + 1);
  const localLockUntil = computeCycleLockUntil(cycleNum, startDate, endDate, totalDays);

  const applyLocalCycleState = (serverState = null) => {
    if(!STORE.settings) STORE.settings = {};
    if(!STORE.settings.schedule) STORE.settings.schedule = {};
    
    // UPDATE CENTRAL CYCLE STATE FIRST (Single authoritative source of truth)
    STORE.settings.schedule.startDate = startDate;
    STORE.settings.schedule.endDate = endDate;
    STORE.settings.schedule.durationDays = totalDays;
    STORE.settings.schedule.cycleGoal = goal;
    STORE.settings.schedule.currentCycle = cycleNum;
    STORE.settings.schedule.locked = true;
    STORE.settings.schedule.lockUntil = serverState?.lock_until || localLockUntil;
    
    const localStateObj = serverState || {
      cycle_number: cycleNum,
      status: 'LOCKED',
      target_schedule_date: { startDate, endDate },
      duration_days: totalDays,
      cycle_goal: goal,
      lock_until: localLockUntil,
      started_at: new Date().toISOString(),
      confirmed_at: new Date().toISOString()
    };
    
    STORE.settings.schedule.cycleState = localStateObj;
    STORE.settings.schedule.targetSetupCompleted = true;
    
    // Crucial: Update in-memory SERVER_CYCLE_STATE immediately so synchronous calculations never read stale data
    SERVER_CYCLE_STATE = localStateObj;
    
    // Reset cycle daily logs for fresh cycle start (preserves cycleHistory, clears active logs for new cycle)
    if(cycleNum > 1){
      STORE.habitLogs = {};
      STORE.plannerData = {};
      if(STORE.dojo){
        STORE.dojo.weeklySolved = 0;
        if(Array.isArray(STORE.dojo.targets)) STORE.dojo.targets.forEach(t => { t.done = 0; });
        if(Array.isArray(STORE.dojo.tasks)) STORE.dojo.tasks.forEach(t => { t.done = false; });
      }
      STORE.pomodoroHistory = [];
    }

    save();
    updateTargetButtonUI();
    updateSidebarRing();
    render();
  };

  // Immediate synchronous application so UI and state update instantly
  applyLocalCycleState();
  toast(`🔒 Cycle ${cycleNum} confirmed and locked successfully! Active from ${startDate} to ${endDate}.`);
  playNotificationSound('post');

  // Background server confirmation sync
  return fetch('/api/cycle/confirm', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      cycleNumber: cycleNum,
      startDate,
      endDate,
      cycleGoal: goal,
      userName: user
    })
  })
  .then(res => res.json())
  .then(data => {
    if(data.success && data.state){
      SERVER_CYCLE_STATE = data.state;
      if (STORE && STORE.settings && STORE.settings.schedule) {
        STORE.settings.schedule.cycleState = data.state;
        save();
      }
    }
  })
  .catch(err => {
    console.warn('Cycle confirmation server sync note:', err);
  });
}

// 2. Trigger Reset Cycle Flow with Server-Enforced Rules
function triggerResetCycleFlow(){
  const sched = getSchedule();
  const currentCycleNum = sched.currentCycle;
  const today = todayStr();

  // --- RULE FOR CYCLE 2 ---
  if(currentCycleNum === 2){
    openModal('Cycle 2 Cannot Be Reset', `
      <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:16px;">
        <div class="card" style="background:rgba(239, 68, 68, 0.08); border:1px solid rgba(239, 68, 68, 0.25); padding:14px; margin-bottom:14px;">
          <div style="font-weight:700; color:#ef4444; margin-bottom:6px; font-size:14px;">⛔ Reset Disabled on Cycle 2</div>
          <p style="font-size:13.5px; margin:0; line-height:1.5;">
            Cycle 2 has already started and cannot be reset at this time.
            The system is designed to prevent repeated cycle restarts and schedule manipulation.
          </p>
        </div>
        <p style="margin:0; font-size:13px; color:var(--text-dim);">
          Please continue Cycle 2 until its completion requirements are met.
        </p>
      </div>
      <div class="form-actions">
        <button class="btn btn-accent" id="mCycle2Close">Understood</button>
      </div>
    `, modal => {
      modal.querySelector('#mCycle2Close')?.addEventListener('click', closeModal);
    });
    return;
  }

  // --- RULE FOR CYCLE 3 ---
  if(currentCycleNum >= 3){
    if(sched.status !== 'COMPLETED'){
      openModal('Cycle 3 Strictly Locked', `
        <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:16px;">
          <div class="card" style="background:rgba(239, 68, 68, 0.08); border:1px solid rgba(239, 68, 68, 0.25); padding:14px; margin-bottom:14px;">
            <div style="font-weight:700; color:#ef4444; margin-bottom:6px; font-size:14px;">🔒 Strictly Locked Until Completion</div>
            <p style="font-size:13.5px; margin:0; line-height:1.5;">
              Cycle 3 is strictly locked until full completion. No resetting or restarting Cycle 3 is permitted.
            </p>
          </div>
        </div>
        <div class="form-actions">
          <button class="btn btn-accent" id="mCycle3Close">Understood</button>
        </div>
      `, modal => {
        modal.querySelector('#mCycle3Close')?.addEventListener('click', closeModal);
      });
      return;
    }
  }

  // --- RULE FOR CYCLE 1 ---
  const lockUntil = sched.lockUntil || computeCycleLockUntil(1, sched.startDate, sched.endDate, sched.durationDays);

  // Check 1: Initial Lock Period
  if(today < lockUntil && today <= sched.endDate){
    const daysLeft = Math.max(1, diffDays(today, lockUntil));
    openModal('Cycle 1 Lock Period Active', `
      <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:16px;">
        <div class="card" style="background:rgba(234, 179, 8, 0.08); border:1px solid rgba(234, 179, 8, 0.25); padding:14px; margin-bottom:14px;">
          <div style="font-weight:700; color:#eab308; margin-bottom:6px; font-size:14px;">⏳ Initial Lock Period Active</div>
          <p style="font-size:13.5px; margin:0; line-height:1.5;">
            Cycle 1 is currently in its initial lock period (active until <strong>${lockUntil}</strong>).
            Schedule dates, cycle-start information, and submitted data are locked, and <strong>Reset Cycle</strong> is disabled during this period.
          </p>
        </div>
        <div class="flex between align-center" style="font-size:13px; color:var(--text-dim);">
          <span>Lock expiration date: <strong>${lockUntil}</strong></span>
          <span class="pill pill-accent">${daysLeft} day${daysLeft > 1 ? 's' : ''} remaining</span>
        </div>
      </div>
      <div class="form-actions">
        <button class="btn btn-accent" id="mLockClose">Understood</button>
      </div>
    `, modal => {
      modal.querySelector('#mLockClose')?.addEventListener('click', closeModal);
    });
    return;
  }

  // Check 2: Score >= 85% requirement
  const scores = evaluateCyclePerformanceScores();
  const minRequiredScore = (SERVER_CYCLE_RULES && SERVER_CYCLE_RULES.minScoreForReset) || 85;
  const currentDisciplineScore = scores.overallScore;

  if(currentDisciplineScore < minRequiredScore || scores.habitScore < minRequiredScore){
    openModal('Cycle Reset Not Available', `
      <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:16px;">
        <div class="card" style="background:rgba(239, 68, 68, 0.08); border:1px solid rgba(239, 68, 68, 0.25); padding:14px; margin-bottom:14px;">
          <div style="font-weight:700; color:#ef4444; margin-bottom:6px; font-size:14px;">⛔ Score Requirement Not Met</div>
          <p style="font-size:13.5px; margin:0; line-height:1.5;">
            A cycle reset is currently unavailable because all required scores must be at least <strong>${minRequiredScore}%</strong>.
          </p>
        </div>
        <div class="grid grid-2" style="gap:10px; margin-bottom:14px;">
          <div class="card" style="padding:10px;">
            <div class="dim" style="font-size:11px;">Current Overall Score</div>
            <div style="font-size:18px; font-weight:700; color:${currentDisciplineScore >= minRequiredScore ? '#10b981' : '#ef4444'};">${currentDisciplineScore}%</div>
            <div class="dim" style="font-size:10px;">Required: &gt;= ${minRequiredScore}%</div>
          </div>
          <div class="card" style="padding:10px;">
            <div class="dim" style="font-size:11px;">Habit Discipline Score</div>
            <div style="font-size:18px; font-weight:700; color:${scores.habitScore >= minRequiredScore ? '#10b981' : '#ef4444'};">${scores.habitScore}%</div>
            <div class="dim" style="font-size:10px;">Required: &gt;= ${minRequiredScore}%</div>
          </div>
        </div>
        <p style="font-size:13px; color:var(--text-dim); margin:0;">
          Please continue the current cycle and complete the required progress before attempting another reset.
        </p>
      </div>
      <div class="form-actions">
        <button class="btn btn-accent" id="mScoreClose">Back to Dashboard</button>
      </div>
    `, modal => {
      modal.querySelector('#mScoreClose')?.addEventListener('click', closeModal);
    });
    return;
  }

  // Check 3: Score >= 85% -> Open Reset Reason Request Modal
  openModal('Cycle 1 Reset Request', `
    <div style="font-size:14px; line-height:1.65; color:var(--text); margin-bottom:14px;">
      <div class="card" style="background:rgba(16, 185, 129, 0.08); border:1px solid rgba(16, 185, 129, 0.25); padding:12px; margin-bottom:14px;">
        <div style="font-weight:700; color:#10b981; margin-bottom:4px; font-size:13.5px;">✓ Score Threshold Qualified (${currentDisciplineScore}% &gt;= ${minRequiredScore}%)</div>
        <p style="font-size:13px; margin:0; line-height:1.5;">
          Your current performance meets the required 85% threshold.
          Resetting this cycle will archive your Cycle 1 progress and initiate Cycle 2 setup.
        </p>
      </div>
      <div class="form-row">
        <label style="font-weight:600;">Please explain why you want to reset the cycle (Mandatory):</label>
        <textarea id="resetReasonInput" placeholder="Enter specific reason for resetting (e.g. Schedule readjustment after completing milestones)..." style="min-height:90px; font-size:13.5px;"></textarea>
      </div>
    </div>
    <div class="form-actions">
      <button class="btn btn-ghost" id="mResetCancel">Cancel</button>
      <button class="btn btn-accent" id="mResetSubmit">Submit Reset Request</button>
    </div>
  `, modal => {
    modal.querySelector('#mResetCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mResetSubmit')?.addEventListener('click', () => {
      const reason = modal.querySelector('#resetReasonInput').value.trim();
      if(!reason){
        return toast('Please enter a mandatory reason for resetting the cycle.');
      }
      closeModal();
      submitCycle1ResetRequest(reason, scores);
    });
  });
}

function submitCycle1ResetRequest(reason, scores){
  fetch('/api/cycle/reset-request', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      reason,
      currentScores: scores,
      clientToday: todayStr()
    })
  })
  .then(res => res.json())
  .then(data => {
    if(data.success && data.state){
      SERVER_CYCLE_STATE = data.state;
      
      // Archive Cycle 1 in History
      STORE.cycleHistory.push({
        id: uid(),
        cycleNumber: 1,
        resetDate: todayStr(),
        reason: reason,
        previousGoal: STORE.settings.schedule.cycleGoal,
        previousStartDate: STORE.settings.schedule.startDate,
        previousEndDate: STORE.settings.schedule.endDate,
        scores: scores
      });
      addHistoryEntry('cycle', 'Cycle 1 Reset Approved', `Reason: ${reason}. Score: ${scores.overallScore}%`);
      save();

      toast('Cycle 1 reset approved! Opening Cycle 2 setup...');
      openNewCycleSetupModal(reason, 2);
    } else {
      toast(data.error || 'Reset request rejected by server rules.');
    }
  })
  .catch(err => {
    toast('Network error processing reset request.');
  });
}

function openNewCycleSetupModal(reason, nextCycleNum){
  const today = todayStr();
  const sched = getSchedule();
  const dur = Number(sched.durationDays) || 90;
  const defaultEnd = addDays(today, dur - 1);

  openModal(`Configure & Start Cycle ${nextCycleNum}`, `
    <div style="font-size:14px; line-height:1.6; color:var(--text); margin-bottom:14px;">
      <p class="dim" style="font-size:13px; margin-bottom:14px;">
        Configure target dates and objective for <strong>Cycle ${nextCycleNum} of ${sched.maxCycles}</strong>.
      </p>
      <div class="form-grid">
        <div class="form-row"><label>Start Date * <span class="dim" style="font-size:11px;">(Today onwards)</span></label><input type="date" id="newCycleStartDate" value="${today}" min="${today}"/></div>
        <div class="form-row"><label>End Date *</label><input type="date" id="newCycleEndDate" value="${defaultEnd}" min="${today}"/></div>
      </div>
      <div class="form-row">
        <label>Cycle Goal</label>
        <input id="newCycleGoal" value="${escapeHtml(sched.cycleGoal || 'Complete target journey')}" placeholder="e.g. Master DSA, complete full-stack projects, maintain fitness"/>
      </div>
    </div>
    <div class="form-actions">
      <button class="btn btn-ghost" id="mSetupCancel">Cancel</button>
      <button class="btn btn-accent" id="mSetupConfirm">Continue to Confirmation</button>
    </div>
  `, modal => {
    const sInp = modal.querySelector('#newCycleStartDate');
    const eInp = modal.querySelector('#newCycleEndDate');

    sInp?.addEventListener('change', () => {
      const curToday = todayStr();
      if(sInp.value && sInp.value < curToday){
        sInp.value = curToday;
        toast(`Past dates not allowed. Start Date reset to today (${curToday}).`);
      }
      if(eInp){
        eInp.min = sInp.value || curToday;
        if(eInp.value && eInp.value < sInp.value){
          eInp.value = sInp.value;
        }
      }
    });

    modal.querySelector('#mSetupCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSetupConfirm')?.addEventListener('click', () => {
      const curToday = todayStr();
      const startDate = sInp ? sInp.value.trim() : '';
      const endDate = eInp ? eInp.value.trim() : '';
      const goal = modal.querySelector('#newCycleGoal')?.value?.trim();

      if(!startDate || !endDate){
        return toast('Please select both start and end dates.');
      }
      if(startDate < curToday){
        return toast(`Start Date cannot be before today (${curToday}).`);
      }
      if(parseDate(endDate) < parseDate(startDate)){
        return toast('End Date must be on or after Start Date.');
      }
      if(!goal){
        return toast('Please enter a goal for the new cycle.');
      }

      closeModal();
      openStartCycleConfirmationModal(nextCycleNum, startDate, endDate, goal);
    });
  });
}

// 3. Server-Enforced Schedule Update
function handleSaveScheduleAction(){
  const sched = getSchedule();
  const isLocked = isTargetSetupCompleted() || sched.locked;
  if(isLocked){
    return toast('🔒 Schedule is confirmed and locked under Cycle rules. Direct editing is disabled.');
  }

  const today = todayStr();
  const startDate = document.getElementById('setStartDate')?.value || sched.startDate;
  const endDate = document.getElementById('setEndDate')?.value || sched.endDate;
  const cycleGoal = document.getElementById('setCycleGoal')?.value?.trim() || sched.cycleGoal;

  if(!startDate || !endDate){
    return toast('Please provide both Start Date and End Date.');
  }
  if(startDate < today){
    return toast(`Start Date cannot be before today (${today}).`);
  }
  try{
    if(parseDate(endDate) < parseDate(startDate)){
      return toast('End Date must be on or after Start Date.');
    }
  }catch(_){
    return toast('Please provide valid dates in YYYY-MM-DD format.');
  }

  const totalDays = diffDays(startDate, endDate) + 1;
  if(totalDays < 1){
    return toast('Target duration must be at least 1 day.');
  }

  if(!STORE.settings) STORE.settings = {};
  if(!STORE.settings.schedule) STORE.settings.schedule = {};
  STORE.settings.schedule.startDate = startDate;
  STORE.settings.schedule.endDate = endDate;
  STORE.settings.schedule.durationDays = totalDays;
  STORE.settings.schedule.cycleGoal = cycleGoal;
  STORE.settings.schedule.lockUntil = computeCycleLockUntil(sched.currentCycle, startDate, endDate, totalDays);
  
  if(SERVER_CYCLE_STATE){
    SERVER_CYCLE_STATE.target_schedule_date = { startDate, endDate };
    SERVER_CYCLE_STATE.duration_days = totalDays;
    SERVER_CYCLE_STATE.cycle_goal = cycleGoal;
    SERVER_CYCLE_STATE.lock_until = STORE.settings.schedule.lockUntil;
  }

  save();
  updateTargetButtonUI();
  updateSidebarRing();
  render();
  toast(`🎯 Schedule updated: ${startDate} → ${endDate} (${totalDays} day${totalDays > 1 ? 's' : ''})`);

  fetch('/api/cycle/update-schedule', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ startDate, endDate, cycleGoal, durationDays: totalDays })
  })
  .then(res => res.json())
  .then(data => {
    if(data.success && data.state){
      SERVER_CYCLE_STATE = data.state;
    }
  })
  .catch(err => {
    // Local state is already persistent and active
  });
}

function openMilestoneCheckpointModal(){
  const sched = getSchedule();
  const start = sched.startDate;
  const end = sched.endDate;
  const totalDays = sched.durationDays || Math.max(1, diffDays(start, end) + 1);
  const currentDay = currentDayNumber();
  const elapsed = currentDay;
  const completedDays = Math.max(0, currentDay - 1);
  const remaining = daysRemaining();
  const progressPct = overallCompletionPct();

  // Pacing calculation
  const targetFocusPerDay = (STORE && STORE.settings && STORE.settings.schedule && STORE.settings.schedule.dailyFocusTarget) || 8;
  const targetTotalFocusSoFar = Math.max(1, currentDay) * targetFocusPerDay;
  
  let loggedFocusHours = 0;
  if(STORE && Array.isArray(STORE.pomodoroHistory)){
    loggedFocusHours = STORE.pomodoroHistory.filter(h => h && h.type === 'focus').reduce((s, h) => s + (h.minutes || 25), 0) / 60;
  }
  if(STORE && STORE.study && Array.isArray(STORE.study.sessions)){
    loggedFocusHours += STORE.study.sessions.reduce((s, x) => s + (Number(x.durationHours) || 0), 0);
  }
  loggedFocusHours = Math.round(loggedFocusHours * 10) / 10;

  const paceDiff = Math.round((loggedFocusHours - targetTotalFocusSoFar) * 10) / 10;
  let pacingClass = 'pacing-ontrack';
  let pacingLabel = '⚡ On Track';
  if(paceDiff > 2){
    pacingClass = 'pacing-ahead';
    pacingLabel = `🚀 Ahead of Pace (+${paceDiff}h)`;
  } else if(paceDiff < -5){
    pacingClass = 'pacing-behind';
    pacingLabel = `⚠️ Behind Pace (${paceDiff}h)`;
  }

  // 30-day milestones definition
  const checkpoints = [];
  for(let cp = 30; cp <= totalDays; cp += 30){
    checkpoints.push(cp);
  }
  if(checkpoints[checkpoints.length - 1] !== totalDays){
    checkpoints.push(totalDays);
  }

  let dojoProblemsTotal = 0;
  (STORE.dojo?.beltTargets || []).forEach(t => { dojoProblemsTotal += (t.problemsSolved || 0); });
  (STORE.dojo?.attempts || []).forEach(a => { dojoProblemsTotal += (a.attempted || 0); });

  const modalHtml = `
    <div style="font-size:14px; line-height:1.6; color:var(--text);">
      <div style="display:flex; align-items:center; gap:12px; margin-bottom:16px; padding:12px 14px; background:var(--accent-dim); border:1px solid var(--accent); border-radius:12px;">
        <span style="font-size:28px;">🎯</span>
        <div style="flex:1;">
          <div class="flex between align-center">
            <strong style="color:var(--text-bright); font-size:15px;">Cycle Milestone & 30-Day Checkpoints</strong>
            <span class="pacing-badge ${pacingClass}">${pacingLabel}</span>
          </div>
          <div class="dim" style="font-size:12px; margin-top:2px;">Track your 30-day milestones, pacing status, and target completion rate.</div>
        </div>
      </div>

      <!-- Quick Metrics Grid -->
      <div class="grid grid-4" style="gap:10px; margin-bottom:16px;">
        <div class="card stat-card" style="padding:12px; background:var(--bg-2);">
          <div class="stat-label" style="font-size:10.5px;">DAY IN CYCLE</div>
          <div class="stat-value accent" style="font-size:22px;">Day ${currentDay} <span class="dim" style="font-size:13px;">/ ${totalDays}</span></div>
          <div class="stat-sub">${currentDay === 0 ? `Starts on ${start}` : (currentDay === 1 ? 'Starting Today · Day 1 Active' : `${completedDays} days finished · ${remaining} left`)}</div>
        </div>
        <div class="card stat-card" style="padding:12px; background:var(--bg-2);">
          <div class="stat-label" style="font-size:10.5px;">CYCLE COMPLETION</div>
          <div class="stat-value" style="font-size:22px; color:var(--accent);">${progressPct}%</div>
          <div class="stat-sub">${currentDay === 0 ? 'Not Started Yet' : (completedDays === 0 ? 'Day 1 in progress (0% done)' : `${completedDays} of ${totalDays} days finished`)}</div>
        </div>
        <div class="card stat-card" style="padding:12px; background:var(--bg-2);">
          <div class="stat-label" style="font-size:10.5px;">PROBLEMS SOLVED</div>
          <div class="stat-value" style="font-size:22px; color:#4ade80;">${dojoProblemsTotal}</div>
          <div class="stat-sub">Across Dojo Targets</div>
        </div>
        <div class="card stat-card" style="padding:12px; background:var(--bg-2); border:1px solid ${(() => { const s = SERVER_CYCLE_STATE?.scores?.overallScore || 0; const hd = Object.values(STORE.habitLogs[todayStr()]||{}).filter(v=>v==='done').length; const th = (STORE.habits||[]).length; const hr = th>0?Math.round(hd/th*100):0; const sc = Math.max(s,hr); return sc>=85?'rgba(74,222,128,0.3)':sc>=70?'rgba(251,191,36,0.3)':'rgba(239,68,68,0.3)'; })()};">
          <div class="stat-label" style="font-size:10.5px;">TODAY'S STREAK</div>
          <div class="stat-value" style="font-size:22px; color:${(() => { const s = SERVER_CYCLE_STATE?.scores?.overallScore || 0; const hd = Object.values(STORE.habitLogs[todayStr()]||{}).filter(v=>v==='done').length; const th = (STORE.habits||[]).length; const hr = th>0?Math.round(hd/th*100):0; const sc = Math.max(s,hr); return sc>=85?'#4ade80':sc>=70?'#fbbf24':'#ef4444'; })()};">
            ${(() => { const s = SERVER_CYCLE_STATE?.scores?.overallScore || 0; const hd = Object.values(STORE.habitLogs[todayStr()]||{}).filter(v=>v==='done').length; const th = (STORE.habits||[]).length; const hr = th>0?Math.round(hd/th*100):0; return Math.max(s,hr); })()}%
          </div>
          <div class="stat-sub">${(() => { const s = SERVER_CYCLE_STATE?.scores?.overallScore || 0; const hd = Object.values(STORE.habitLogs[todayStr()]||{}).filter(v=>v==='done').length; const th = (STORE.habits||[]).length; const hr = th>0?Math.round(hd/th*100):0; const sc = Math.max(s,hr); return sc>=85?'🔥 Excellent Today':sc>=70?'⚡ Good Pace':'💤 Build Momentum'; })()}</div>
        </div>
      </div>

      <!-- Overall Journey Progress Bar -->
      <div class="card" style="background:var(--bg-2); padding:14px; margin-bottom:16px; border:1px solid var(--border-soft);">
        <div class="flex between align-center" style="margin-bottom:8px;">
          <strong style="font-size:13.5px; color:var(--text-bright);">📊 Journey Timeline: ${start} → ${end}</strong>
          <span class="mono dim" style="font-size:12px;">Day ${currentDay} / ${totalDays} (${progressPct}% finished)</span>
        </div>
        <div class="progress-bar-bg" style="height:10px; border-radius:5px;"><div class="progress-bar-fill" style="width:${progressPct}%; background:var(--accent); border-radius:5px;"></div></div>
        <div class="dim mt-8" style="font-size:12px; font-style:italic;">"${escapeHtml(sched.cycleGoal || 'Transformation Target')}"</div>
      </div>

      <!-- 30-Day Milestone Checkpoints List -->
      <div class="card" style="background:var(--bg-2); padding:14px; margin-bottom:16px; border:1px solid var(--border-soft);">
        <div class="flex between align-center" style="margin-bottom:10px;">
          <strong style="font-size:13.5px; color:var(--text-bright);">🚩 30-Day Checkpoint Progression</strong>
          <span class="dim" style="font-size:11.5px;">Reviewed every 30 days</span>
        </div>
        <div class="flex flex-col gap-8">
          ${checkpoints.map((cp, idx) => {
            const isCompleted = elapsed >= cp;
            const isCurrent = !isCompleted && (idx === 0 || elapsed >= checkpoints[idx-1]);
            const cpDate = addDays(start, cp - 1);
            return `
              <div class="flex between align-center" style="padding:8px 12px; background:var(--bg-3); border-radius:8px; border-left:3px solid ${isCompleted ? '#4ade80' : (isCurrent ? 'var(--accent)' : 'var(--border)')};">
                <div>
                  <div style="font-weight:700; font-size:13px; color:${isCompleted ? '#4ade80' : (isCurrent ? 'var(--text-bright)' : 'var(--text-dim)')};">
                    ${isCompleted ? '✅' : (isCurrent ? '📍' : '⚪')} Checkpoint ${idx + 1}: Day ${cp}
                  </div>
                  <div class="dim mono" style="font-size:11px;">Target Date: ${cpDate}</div>
                </div>
                <div>
                  <span class="pill ${isCompleted ? 'pill-accent' : (isCurrent ? 'pill-dim' : '')}" style="font-size:11px; font-weight:700;">
                    ${isCompleted ? 'Completed' : (isCurrent ? 'Active Focus' : 'Upcoming')}
                  </span>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>

      <!-- Action Buttons -->
      <div class="flex between wrap gap-8 pt-8" style="border-top:1px solid var(--border-soft);">
        <div class="flex gap-8 wrap">
          <button class="btn btn-sm btn-ghost" id="btnExportWeeklyMd">📄 Export Progress Report (.md)</button>
          <button class="btn btn-sm btn-ghost" id="btnExportCalIcs">📅 Sync Calendar (.ics)</button>
        </div>
        <div class="flex gap-8">
          <button class="btn btn-sm btn-ghost" id="btnAdjustScheduleTargets">⚙️ Adjust Daily Targets</button>
          <button class="btn btn-sm btn-accent" id="mCpClose">Close</button>
        </div>
      </div>
    </div>
  `;

  openModal('Target Journey & Milestones', modalHtml, modal => {
    modal.querySelector('#mCpClose')?.addEventListener('click', closeModal);
    modal.querySelector('#btnExportWeeklyMd')?.addEventListener('click', () => {
      exportWeeklyMarkdown(30);
    });
    modal.querySelector('#btnExportCalIcs')?.addEventListener('click', () => {
      exportScheduleIcs();
    });
    modal.querySelector('#btnAdjustScheduleTargets')?.addEventListener('click', () => {
      // Cycle-based lock rules for Adjust Daily Targets:
      // Cycle 1: locked for 1 month from startDate
      // Cycle 2 & 3: locked until cycle completion
      // Reset requires productivity score > 85
      const schedNow = getSchedule();
      const cycleNum = schedNow.currentCycle || 1;
      const lockUntilDate = schedNow.lockUntil || addDays(schedNow.startDate, 29);
      const today = todayStr();
      const isInLockPeriod = today < lockUntilDate;
      const isCycle23 = cycleNum >= 2;
      const cycleComplete = today >= (schedNow.endDate || today);

      // Calculate today's productivity score from server or local
      const overallScore = SERVER_CYCLE_STATE?.scores?.overallScore || 0;
      const habitsDone = Object.values(STORE.habitLogs[today] || {}).filter(v => v === 'done').length;
      const totalHabits = (STORE.habits || []).length;
      const habitRate = totalHabits > 0 ? Math.round((habitsDone / totalHabits) * 100) : 0;
      const currentScore = Math.max(overallScore, habitRate);
      const scoreAbove85 = currentScore >= 85;

      if(isCycle23 && !cycleComplete){
        // Cycle 2 & 3: locked until completion
        openModal('🔒 Targets Locked', `
          <div style="font-size:14px; line-height:1.65; color:var(--text); padding:8px 0;">
            <div style="display:flex; align-items:center; gap:10px; margin-bottom:14px; padding:12px; background:rgba(239,68,68,0.08); border:1px solid rgba(239,68,68,0.25); border-radius:10px;">
              <span style="font-size:28px;">🔒</span>
              <div>
                <strong style="color:#ef4444; font-size:14px;">Cycle ${cycleNum} — Locked Until Completion</strong>
                <div class="dim" style="font-size:12px; margin-top:2px;">Daily targets for Cycle 2 and Cycle 3 are permanently locked. They unlock only when the cycle completes (${schedNow.endDate}).</div>
              </div>
            </div>
            <div style="background:var(--bg-2); border-radius:10px; padding:12px; border:1px solid var(--border-soft); margin-bottom:12px;">
              <div style="font-size:12.5px; font-weight:700; color:var(--text-bright); margin-bottom:8px;">📊 Cycle Lock Status</div>
              <div class="flex between" style="font-size:12px; margin-bottom:4px;"><span class="dim">Cycle Number</span><span class="mono">Cycle ${cycleNum}</span></div>
              <div class="flex between" style="font-size:12px; margin-bottom:4px;"><span class="dim">Cycle End Date</span><span class="mono">${schedNow.endDate}</span></div>
              <div class="flex between" style="font-size:12px; margin-bottom:4px;"><span class="dim">Days Remaining</span><span class="mono accent">${daysRemaining()} days</span></div>
              <div class="flex between" style="font-size:12px;"><span class="dim">Your Score Today</span><span class="mono" style="color:${scoreAbove85 ? 'var(--accent)' : 'var(--danger)'}">${currentScore}% ${scoreAbove85 ? '✅' : '⚠️'}</span></div>
            </div>
            <div style="font-size:12px; color:var(--text-dim); text-align:center; padding:6px 0;">💡 Stay consistent — targets auto-refresh each day based on your productivity streak.</div>
          </div>
          <div class="form-actions"><button class="btn btn-accent" onclick="document.getElementById('modalOverlay').click()">Got it</button></div>
        `, () => {});
        return;
      }

      if(isInLockPeriod && cycleNum < 2){
        // Cycle 1: 1-month lock
        openModal('🔒 Targets Locked (Cycle 1)', `
          <div style="font-size:14px; line-height:1.65; color:var(--text); padding:8px 0;">
            <div style="display:flex; align-items:center; gap:10px; margin-bottom:14px; padding:12px; background:rgba(239,68,68,0.08); border:1px solid rgba(239,68,68,0.25); border-radius:10px;">
              <span style="font-size:28px;">🔒</span>
              <div>
                <strong style="color:#ef4444; font-size:14px;">1-Month Initialization Lock Active</strong>
                <div class="dim" style="font-size:12px; margin-top:2px;">Cycle 1 targets are locked for the first 30 days. They unlock on <strong>${lockUntilDate}</strong>.</div>
              </div>
            </div>
            <div style="background:var(--bg-2); border-radius:10px; padding:12px; border:1px solid var(--border-soft); margin-bottom:12px;">
              <div class="flex between" style="font-size:12px; margin-bottom:4px;"><span class="dim">Lock Expires</span><span class="mono accent">${lockUntilDate}</span></div>
              <div class="flex between" style="font-size:12px;"><span class="dim">Your Score</span><span class="mono" style="color:${scoreAbove85 ? 'var(--accent)' : 'var(--danger)'}">${currentScore}% ${scoreAbove85 ? '✅' : '(Need ≥85% to unlock early)'}</span></div>
            </div>
            ${scoreAbove85 ? `<div style="font-size:12px; padding:8px 12px; background:rgba(74,222,128,0.08); border:1px solid rgba(74,222,128,0.25); border-radius:8px; color:#4ade80;">🎉 Your score is above 85% — Early unlock available! Contact the platform admin or wait until ${lockUntilDate}.</div>` : `<div style="font-size:12px; color:var(--text-dim); text-align:center; padding:6px 0;">💡 Keep your productivity score above 85% to qualify for early unlock.</div>`}
          </div>
          <div class="form-actions"><button class="btn btn-accent" onclick="document.getElementById('modalOverlay').click()">Got it</button></div>
        `, () => {});
        return;
      }

      // Unlocked — open adjust targets modal
      closeModal();
      openScheduleTargetModal();
    });
  });
}

function openMorningBriefingModal(){
  const tStr = todayStr();
  const dayData = getPlannerDay(tStr);
  const collegeSched = getCollegeDay(tStr);
  const activeHabits = habitsActiveOn(tStr);

  const existingMit = dayData.checklist ? dayData.checklist.slice(0, 3) : [];
  const mit1 = existingMit[0]?.text || '';
  const mit2 = existingMit[1]?.text || '';
  const mit3 = existingMit[2]?.text || '';

  const sched = getSchedule();
  const totalDays = scheduleTotalDays();
  const elapsed = clamp(currentDayNumber(), 0, totalDays);

  const modalHtml = `
    <div style="font-size:14px; line-height:1.6; color:var(--text);">
      <div style="display:flex; align-items:center; gap:12px; margin-bottom:16px; padding:12px 14px; background:var(--accent-dim); border:1px solid var(--accent); border-radius:12px;">
        <span style="font-size:28px;">🌅</span>
        <div>
          <strong style="color:var(--text-bright); font-size:15px;">Morning Power Briefing • Day ${elapsed} of ${totalDays}</strong>
          <div class="dim" style="font-size:12px;">${niceDate(tStr)} • Set your top 3 Most Important Tasks (MITs)</div>
        </div>
      </div>

      <!-- Top 3 MITs -->
      <div class="card" style="background:var(--bg-2); padding:14px; margin-bottom:14px; border:1px solid var(--border-soft);">
        <strong style="color:var(--text-bright); font-size:13.5px; display:block; margin-bottom:8px;">🎯 Top 3 MITs for Today (Deep Focus)</strong>
        <div class="form-row" style="margin-bottom:8px;">
          <label style="font-size:11px; text-transform:uppercase; color:var(--accent);">MIT 1 (Highest Impact)</label>
          <input type="text" id="mbMit1" value="${escapeHtml(mit1)}" placeholder="e.g. Solve 3 Binary Tree DFS problems" style="padding:8px 10px; font-weight:600;" />
        </div>
        <div class="form-row" style="margin-bottom:8px;">
          <label style="font-size:11px; text-transform:uppercase; color:var(--accent);">MIT 2 (Core Task)</label>
          <input type="text" id="mbMit2" value="${escapeHtml(mit2)}" placeholder="e.g. Complete System Design notes & revision" style="padding:8px 10px;" />
        </div>
        <div class="form-row" style="margin-bottom:4px;">
          <label style="font-size:11px; text-transform:uppercase; color:var(--accent);">MIT 3 (Maintenance / Study)</label>
          <input type="text" id="mbMit3" value="${escapeHtml(mit3)}" placeholder="e.g. 45m workout + 20 pages reading" style="padding:8px 10px;" />
        </div>
      </div>

      <!-- College & Habits Quick View -->
      <div class="grid grid-2" style="gap:10px; margin-bottom:14px;">
        <div class="card" style="background:var(--bg-2); padding:12px; border:1px solid var(--border-soft);">
          <strong style="font-size:12px; color:var(--text-bright); display:block; margin-bottom:6px;">🏫 College Schedule Today</strong>
          ${collegeSched.classes && collegeSched.classes.length ? `
            <div style="font-size:12px; color:var(--text-dim);">
              ${collegeSched.classes.slice(0, 3).map(c => `<div class="flex between py-2"><span>${escapeHtml(c.subject)}</span><span class="mono dim">${c.time}</span></div>`).join('')}
            </div>
          ` : '<div class="dim" style="font-size:12px;">No specific classes listed.</div>'}
        </div>
        <div class="card" style="background:var(--bg-2); padding:12px; border:1px solid var(--border-soft);">
          <strong style="font-size:12px; color:var(--text-bright); display:block; margin-bottom:6px;">⚡ Habits to Win (${activeHabits.length})</strong>
          <div class="dim" style="font-size:11.5px; line-height:1.5;">
            ${activeHabits.slice(0, 4).map(id => {
              const h = STORE.habits.find(x => x.id === id);
              return h ? `<div>• ${escapeHtml(h.name)}</div>` : '';
            }).join('')}
          </div>
        </div>
      </div>

      <div class="form-actions" style="margin-top:10px;">
        <button class="btn btn-ghost" id="mCancel">Cancel</button>
        <button class="btn btn-accent" id="mSaveBriefing">🚀 Lock MITs & Start Day</button>
      </div>
    </div>
  `;

  openModal('Morning Briefing', modalHtml, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSaveBriefing')?.addEventListener('click', () => {
      const v1 = modal.querySelector('#mbMit1').value.trim();
      const v2 = modal.querySelector('#mbMit2').value.trim();
      const v3 = modal.querySelector('#mbMit3').value.trim();

      const newMits = [];
      if(v1) newMits.push({ id: uid(), text: v1, done: false, isMit: true });
      if(v2) newMits.push({ id: uid(), text: v2, done: false, isMit: true });
      if(v3) newMits.push({ id: uid(), text: v3, done: false, isMit: true });

      const existingNonMit = (dayData.checklist || []).filter(item => !item.isMit);
      dayData.checklist = [...newMits, ...existingNonMit];
      
      save();
      playChime('pomo');
      toast('🌅 Morning MITs locked into Planner! Let\'s crush today!');
      closeModal();
      render();
    });
  });
}

function openEveningDebriefModal(){
  const tStr = todayStr();
  const dayData = getPlannerDay(tStr);
  const activeHabits = habitsActiveOn(tStr);
  const log = STORE.habitLogs[tStr] || {};
  const habitsDone = activeHabits.filter(id => log[id] === 'done').length;

  let todayFocusMins = 0;
  if(STORE.pomodoroHistory){
    todayFocusMins = STORE.pomodoroHistory.filter(h => h.date === tStr && h.type === 'focus').reduce((s, h) => s + (h.minutes || 25), 0);
  }

  const tasksDone = (dayData.checklist || []).filter(x => x.done).length;
  const totalTasks = (dayData.checklist || []).length;

  const currentReflection = dayData.reflection || { wins:'', learned:'', improve:'', gratitude:'' };

  const modalHtml = `
    <div style="font-size:14px; line-height:1.6; color:var(--text);">
      <div style="display:flex; align-items:center; gap:12px; margin-bottom:16px; padding:12px 14px; background:rgba(99, 102, 241, 0.12); border:1px solid rgba(99, 102, 241, 0.3); border-radius:12px;">
        <span style="font-size:28px;">🌙</span>
        <div>
          <strong style="color:var(--text-bright); font-size:15px;">Evening Debrief & Wins • 60s Review</strong>
          <div class="dim" style="font-size:12px;">${niceDate(tStr)} • Close out your day with intention</div>
        </div>
      </div>

      <!-- Day Summary Stats -->
      <div class="grid grid-3" style="gap:10px; margin-bottom:14px;">
        <div class="card stat-card" style="padding:10px; background:var(--bg-2);">
          <div class="stat-label" style="font-size:10px;">HABITS COMPLETED</div>
          <div class="stat-value accent" style="font-size:18px;">${habitsDone} / ${activeHabits.length}</div>
        </div>
        <div class="card stat-card" style="padding:10px; background:var(--bg-2);">
          <div class="stat-label" style="font-size:10px;">FOCUS LOGGED</div>
          <div class="stat-value" style="font-size:18px; color:var(--accent);">${Math.round(todayFocusMins/60*10)/10}h</div>
        </div>
        <div class="card stat-card" style="padding:10px; background:var(--bg-2);">
          <div class="stat-label" style="font-size:10px;">TASKS COMPLETED</div>
          <div class="stat-value" style="font-size:18px; color:#4ade80;">${tasksDone} / ${totalTasks}</div>
        </div>
      </div>

      <!-- Quick Reflection Inputs -->
      <div class="card" style="background:var(--bg-2); padding:14px; margin-bottom:14px; border:1px solid var(--border-soft);">
        <div class="form-row" style="margin-bottom:8px;">
          <label style="font-size:11px; text-transform:uppercase; color:var(--text-bright);">🏆 Top Wins Today (What went well?)</label>
          <textarea id="edWins" placeholder="e.g. Cleared 4 DSA problems, woke up on time, finished college lab" style="min-height:55px;">${escapeHtml(currentReflection.wins || '')}</textarea>
        </div>
        <div class="form-row" style="margin-bottom:8px;">
          <label style="font-size:11px; text-transform:uppercase; color:var(--text-bright);">💡 1 Key Lesson / What to improve tomorrow</label>
          <input type="text" id="edLearned" value="${escapeHtml(currentReflection.learned || '')}" placeholder="e.g. Avoid phone right after dinner; start coding block earlier" />
        </div>
        <div class="form-grid" style="display:grid; grid-template-columns:1fr 1fr; gap:10px;">
          <div class="form-row">
            <label style="font-size:11px; text-transform:uppercase; color:var(--text-dim);">⚡ Energy Rating</label>
            <select id="edEnergy">
              <option value="5" ${dayData.energy === 5 ? 'selected' : ''}>⭐⭐⭐⭐⭐ High Energy</option>
              <option value="4" ${dayData.energy === 4 ? 'selected' : ''}>⭐⭐⭐⭐ Good</option>
              <option value="3" ${dayData.energy === 3 ? 'selected' : ''}>⭐⭐⭐ Moderate</option>
              <option value="2" ${dayData.energy === 2 ? 'selected' : ''}>⭐⭐ Low Energy</option>
              <option value="1" ${dayData.energy === 1 ? 'selected' : ''}>⭐ Exhausted</option>
            </select>
          </div>
          <div class="form-row">
            <label style="font-size:11px; text-transform:uppercase; color:var(--text-dim);">🙏 Gratitude Note</label>
            <input type="text" id="edGratitude" value="${escapeHtml(currentReflection.gratitude || '')}" placeholder="e.g. Grateful for clean focus" />
          </div>
        </div>
      </div>

      <div class="form-actions">
        <button class="btn btn-ghost" id="mCancel">Cancel</button>
        <button class="btn btn-accent" id="mSaveDebrief">🌙 Save Debrief & Rest</button>
      </div>
    </div>
  `;

  openModal('Evening Debrief', modalHtml, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSaveDebrief')?.addEventListener('click', () => {
      const wins = modal.querySelector('#edWins').value.trim();
      const learned = modal.querySelector('#edLearned').value.trim();
      const energy = Number(modal.querySelector('#edEnergy').value) || 3;
      const gratitude = modal.querySelector('#edGratitude').value.trim();

      dayData.reflection = { wins, learned, improve: '', gratitude };
      dayData.energy = energy;

      save();
      playChime('check');
      toast('🌙 Evening Debrief recorded! Rest well tonight.');
      closeModal();
      render();
    });
  });
}

