function exportWeeklyMarkdown(days = 7){
  const tStr = todayStr();
  const sched = getSchedule();
  const totalDays = scheduleTotalDays();
  const elapsed = clamp(currentDayNumber(), 0, totalDays);

  // Focus hours sum
  let focusMins = 0;
  if(STORE.pomodoroHistory){
    focusMins = STORE.pomodoroHistory.reduce((s, h) => s + (h.minutes || 25), 0);
  }
  const focusHrs = Math.round(focusMins / 60 * 10) / 10;

  // Dojo stats
  let dojoTotal = 0;
  (STORE.dojo?.beltTargets || []).forEach(t => { dojoTotal += (t.problemsSolved || 0); });
  (STORE.dojo?.attempts || []).forEach(a => { dojoTotal += (a.attempted || 0); });

  const md = `# 🏆 DAYSTACK Progress Report • Day ${elapsed} of ${totalDays}
Generated on: ${niceDate(tStr)}

## 🎯 Target & Cycle Status
- **Start Date:** ${sched.startDate}
- **End Date:** ${sched.endDate}
- **Days Elapsed:** ${elapsed} days
- **Cycle Goal:** ${sched.cycleGoal || 'N/A'}
- **Focus Time Logged:** ${focusHrs} hours
- **Coding Problems Solved:** ${dojoTotal} problems

## ⚡ Habits & Consistency
- **Active Streak:** ${currentStreak()} days
- **Active Habits:**
${STORE.habits.map(h => `  - [x] **${h.name}**: ${habitStreak(h.id)} day streak (${habitSuccessPct(h.id)}% success)`).join('\n')}

## 🥋 Dojo Progression
${(STORE.dojo?.beltTargets || []).map(t => `- **${t.language}**: ${t.currentBelt} → ${t.targetBelt} (${t.problemsSolved || 0}/${t.targetProblems || 0} solved)`).join('\n') || '- No belt targets configured'}

## 🛡️ Recent Lessons Learned (Mistakes Log)
${STORE.mistakes.slice(0, 5).map(m => `- **[${m.category}]** ${m.description} → *Lesson:* ${m.lesson}`).join('\n') || '- No mistakes logged'}

---
*Built with DAYSTACK • Stay Disciplined, Stay Focused.*
`;

  // Copy to clipboard
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(md).then(() => {
      toast('📄 Report copied to clipboard & downloaded!');
    }).catch(() => {});
  }

  // Trigger download
  const blob = new Blob([md], { type: 'text/markdown' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `daystack-progress-report-${tStr}.md`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

function exportScheduleIcs(){
  const sched = getSchedule();
  const wake = STORE.settings?.schedule?.wakeTime || '04:30';
  const sleep = STORE.settings?.schedule?.sleepTime || '22:00';

  const [wakeH, wakeM] = wake.split(':').map(Number);
  const [sleepH, sleepM] = sleep.split(':').map(Number);

  const icsLines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//DAYSTACK//Schedule Sync//EN',
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH'
  ];

  // Daily Wake Up Routine
  icsLines.push(
    'BEGIN:VEVENT',
    `UID:daystack-wake-${Date.now()}@lifeos.local`,
    `DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').slice(0,15)}Z`,
    `DTSTART;TZID=Asia/Kolkata:20260815T${String(wakeH).padStart(2,'0')}${String(wakeM).padStart(2,'0')}00`,
    `DTEND;TZID=Asia/Kolkata:20260815T${String((wakeH+1)%24).padStart(2,'0')}${String(wakeM).padStart(2,'0')}00`,
    'RRULE:FREQ=DAILY',
    'SUMMARY:🌅 DAYSTACK Wake Up & Morning Routine',
    'DESCRIPTION:Hydration, stretch, MIT prioritization, and deep focus priming.',
    'END:VEVENT'
  );

  // Daily Deep Focus & Study Block
  icsLines.push(
    'BEGIN:VEVENT',
    `UID:daystack-focus-${Date.now()}@lifeos.local`,
    `DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').slice(0,15)}Z`,
    `DTSTART;TZID=Asia/Kolkata:20260815T060000`,
    `DTEND;TZID=Asia/Kolkata:20260815T083000`,
    'RRULE:FREQ=DAILY',
    'SUMMARY:⚔️ DAYSTACK Deep Coding & DSA Block',
    'DESCRIPTION:LeetCode problem solving, system design, and competitive coding.',
    'END:VEVENT'
  );

  // College Exams if any
  (STORE.exams || []).forEach((ex, idx) => {
    if(ex.date){
      const dClean = ex.date.replace(/-/g,'');
      icsLines.push(
        'BEGIN:VEVENT',
        `UID:daystack-exam-${idx}-${Date.now()}@lifeos.local`,
        `DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').slice(0,15)}Z`,
        `DTSTART;VALUE=DATE:${dClean}`,
        `SUMMARY:🎓 Exam: ${escapeHtml(ex.name || ex.subject || 'Exam')}`,
        `DESCRIPTION:College Examination. Syllabus: ${escapeHtml(ex.syllabus || '')}`,
        'END:VEVENT'
      );
    }
  });

  icsLines.push('END:VCALENDAR');
  const icsContent = icsLines.join('\r\n');

  const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'daystack-schedule.ics';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  toast('📅 Calendar .ics file downloaded! Import it into Google or Apple Calendar.');
}

/* ---------------------------- UTILS ---------------------------- */
if(typeof window !== 'undefined') window.showToast = toast;
function fmtHrs(h){ return (Math.round(h*10)/10) + 'h'; }
function fmtTime(iso){
  if(!iso) return '';
  try{ return new Date(iso).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit', hour12: false }); }catch(e){ return ''; }
}
function formatTo24HourTime(timeStr){
  if(!timeStr) return '';
  const str = String(timeStr).trim();
  if(!str) return '';
  
  // Handle range format "09:30 AM – 05:00 PM" or "09:30 - 17:00"
  if(str.includes('–') || str.includes(' - ') || (str.includes('-') && !str.startsWith('-'))){
    const parts = str.split(/[–\-]/);
    if(parts.length === 2){
      return `${formatTo24HourTime(parts[0].trim())} - ${formatTo24HourTime(parts[1].trim())}`;
    }
  }
  
  // 12-hour AM/PM format "04:30 AM" or "4:30 PM"
  const m12 = str.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if(m12){
    let h = parseInt(m12[1], 10);
    const m = m12[2];
    const meridiem = m12[3].toUpperCase();
    if(meridiem === 'PM' && h < 12) h += 12;
    if(meridiem === 'AM' && h === 12) h = 0;
    return `${String(h).padStart(2, '0')}:${m}`;
  }

  // Single hour with AM/PM like "9 AM"
  const mHour = str.match(/^(\d{1,2})\s*(AM|PM)$/i);
  if(mHour){
    let h = parseInt(mHour[1], 10);
    const meridiem = mHour[2].toUpperCase();
    if(meridiem === 'PM' && h < 12) h += 12;
    if(meridiem === 'AM' && h === 12) h = 0;
    return `${String(h).padStart(2, '0')}:00`;
  }

  // Already 24-hour HH:MM or H:MM
  const m24 = str.match(/^([01]?[0-9]|2[0-3]):([0-5][0-9])$/);
  if(m24){
    const h = String(parseInt(m24[1], 10)).padStart(2, '0');
    return `${h}:${m24[2]}`;
  }

  return str;
}
let _cachedAccentHex = null;
function getAccentHex(){
  try {
    if (STORE && STORE.settings && STORE.settings.accentColor) {
      const c = (typeof POPULAR_COLORS !== 'undefined' ? POPULAR_COLORS : []).find(x => x.id === STORE.settings.accentColor);
      if(c && c.hex) return c.hex;
    }
    if (_cachedAccentHex) return _cachedAccentHex;
    if (typeof window !== 'undefined' && typeof window.getComputedStyle === 'function' && document && document.documentElement) {
      const val = window.getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();
      if(val) {
        _cachedAccentHex = val;
        return val;
      }
    }
  } catch(e) {}
  return '#2d8eff';
}
function getAccentRgb(alpha = 1){
  try {
    if (STORE && STORE.settings && STORE.settings.accentColor) {
      const c = (typeof POPULAR_COLORS !== 'undefined' ? POPULAR_COLORS : []).find(x => x.id === STORE.settings.accentColor);
      if(c && c.rgb) return `rgba(${c.rgb}, ${alpha})`;
    }
  } catch(e) {}
  const hex = getAccentHex();
  if(hex.startsWith('#')){
    let h = hex.slice(1);
    if(h.length === 3) h = h.split('').map(c => c + c).join('');
    const num = parseInt(h, 16);
    const r = (num >> 16) & 255;
    const g = (num >> 8) & 255;
    const b = num & 255;
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  }
  return hex;
}

/* GAMIFICATION ENGINE (XP, Levels, Ranks) */
function getLevelFromXP(xp){
  return Math.floor(Math.sqrt((xp || 0) / 50)) + 1;
}
function getRankTitle(level){
  if(level >= 35) return 'DAYSTACK Grandmaster';
  if(level >= 25) return 'Dojo Legend';
  if(level >= 18) return 'Flow State Master';
  if(level >= 12) return 'Focus Scholar';
  if(level >= 6) return 'Discipline Apprentice';
  return 'Focus Novice';
}
function getXPForNextLevel(level){
  return Math.pow(level, 2) * 50;
}
function addXP(amount, reason = ''){
  if(!STORE.gamification) STORE.gamification = { xp: 0, level: 1, badges: [] };
  const oldLevel = getLevelFromXP(STORE.gamification.xp);
  STORE.gamification.xp += amount;
  const newLevel = getLevelFromXP(STORE.gamification.xp);
  STORE.gamification.level = newLevel;
  save();
  updateSidebarFooter();
  if(newLevel > oldLevel){
    toast(`🎉 LEVEL UP! Level ${newLevel} (${getRankTitle(newLevel)}) unlocked!`);
  } else if(reason){
    toast(`+${amount} XP — ${reason}`);
  }
}

