function getSleepHoursForDate(d){
  const plan = STORE.plannerData[d];
  if(plan){
    if(plan.sleepHours !== undefined && plan.sleepHours !== null && !isNaN(Number(plan.sleepHours))){
      return Number(plan.sleepHours);
    }
    if(plan.sleepTime && plan.wakeTime){
      const [sh, sm] = plan.sleepTime.split(':').map(Number);
      const [wh, wm] = plan.wakeTime.split(':').map(Number);
      if(!isNaN(sh) && !isNaN(wh)){
        let mins = (wh * 60 + (wm || 0)) - (sh * 60 + (sm || 0));
        if(mins < 0) mins += 1440;
        return Math.round((mins / 60) * 10) / 10;
      }
    }
  }
  const fit = STORE.fitnessLogs && STORE.fitnessLogs[d];
  if(fit && fit.sleep) return Number(fit.sleep) || 0;
  return 0;
}

function getProductivityForDate(d){
  const r = dayCompletionRatio(d);
  const habitPct = r !== null ? Math.round(r * 100) : 0;
  const plan = STORE.plannerData[d];
  if(plan && plan.tasks && plan.tasks.length){
    const doneTasks = plan.tasks.filter(t => t.done).length;
    const taskPct = Math.round((doneTasks / plan.tasks.length) * 100);
    return Math.round((habitPct + taskPct) / 2);
  }
  return habitPct;
}

function getCategoryRadarData(){
  const categories = ['morning', 'body', 'mind', 'growth', 'health', 'life'];
  const logDates = Object.keys(STORE.habitLogs);
  const totalLoggedDays = Math.max(1, logDates.length);

  return categories.map(cat => {
    const catHabits = STORE.habits.filter(h => h.category === cat);
    if(catHabits.length === 0) return 0;

    let doneCount = 0;
    let possibleCount = catHabits.length * totalLoggedDays;

    logDates.forEach(d => {
      const dayLog = STORE.habitLogs[d] || {};
      catHabits.forEach(h => {
        if(dayLog[h.id] === 'done') doneCount++;
      });
    });

    if(possibleCount === 0) return 0;
    return Math.min(100, Math.round((doneCount / possibleCount) * 100));
  });
}

function mdLite(escaped){
  if(!escaped) return '';
  return escaped
    .replace(/^### (.*$)/gim, '<h3 style="font-size:14.5px; font-weight:700; margin:10px 0 4px; color:var(--text);">$1</h3>')
    .replace(/^## (.*$)/gim, '<h2 style="font-size:15.5px; font-weight:700; margin:12px 0 4px; color:var(--accent);">$1</h2>')
    .replace(/`([^`]+)`/g, '<code style="background:var(--glass-strong); padding:1px 5px; border-radius:5px; font-family:var(--font-mono); font-size:.92em;">$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g, '<em>$1</em>')
    .replace(/^- \[ \] (.*$)/gim, '<div style="display:flex; align-items:center; gap:6px; margin:3px 0;"><span style="color:var(--text-dim); font-size:13px;">☐</span> <span>$1</span></div>')
    .replace(/^- \[x\] (.*$)/gim, '<div style="display:flex; align-items:center; gap:6px; margin:3px 0;"><span style="color:var(--accent); font-size:13px;">☑</span> <span style="text-decoration:line-through; color:var(--text-dim);">$1</span></div>')
    .replace(/^- (.*$)/gim, '<li style="margin-left:16px;">$1</li>')
    .replace(/\n/g, '<br/>');
}

/* Habit day completion ratio for a given date */
function habitsActiveOn(dateStr){
  const ids = new Set();
  STORE.habits.forEach(h => {
    if(h.createdAt && h.createdAt <= dateStr) ids.add(h.id);
  });
  const log = STORE.habitLogs[dateStr] || {};
  Object.keys(log).forEach(id => ids.add(id));
  return Array.from(ids);
}

function dayCompletionRatio(dateStr){
  const log = STORE.habitLogs[dateStr] || {};
  const activeHabits = habitsActiveOn(dateStr);
  if(activeHabits.length === 0) return null;
  const done = activeHabits.reduce((sum,id) => sum + (log[id] === 'done' ? 1 : 0), 0);
  return done / activeHabits.length;
}

function currentStreak(){
  let streak = 0;
  let d = todayStr();
  let cursor = d;
  const todayRatio = dayCompletionRatio(d);
  if(todayRatio === null) cursor = addDays(d, -1);
  while(true){
    const r = dayCompletionRatio(cursor);
    if(r !== null && r >= 0.6){ streak++; cursor = addDays(cursor, -1); }
    else break;
    if(streak > 400) break;
  }
  return streak;
}

function habitStreak(habitId){
  let streak = 0; let cursor = todayStr();
  let log = STORE.habitLogs[cursor];
  if(!log || log[habitId] !== 'done') cursor = addDays(cursor, -1);
  while(true){
    const l = STORE.habitLogs[cursor];
    if(l && l[habitId] === 'done'){ streak++; cursor = addDays(cursor, -1); } else break;
    if(streak > 400) break;
  }
  return streak;
}
function habitSuccessPct(habitId){
  let done=0, logged=0;
  Object.values(STORE.habitLogs).forEach(day => {
    if(day[habitId]){ logged++; if(day[habitId]==='done') done++; }
  });
  return logged ? Math.round((done/logged)*100) : 0;
}

function getPlannerDay(dateStr){
  if(!STORE.plannerData[dateStr]){
    STORE.plannerData[dateStr] = { checklist: [], notes:'', mood:3, energy:3, water:0, wakeTime:'', sleepTime:'', tasks: [], reflection: { wins:'', learned:'', improve:'', gratitude:'' } };
  }
  const day = STORE.plannerData[dateStr];
  if(!day.reflection) day.reflection = { wins:'', learned:'', improve:'', gratitude:'' };
  return day;
}

function getCollegeDay(dateStr){
  if(!STORE.college) STORE.college = defaultCollege();
  if(!STORE.college.schedules) STORE.college.schedules = {};
  if(!STORE.college.schedules[dateStr]){
    STORE.college.schedules[dateStr] = {
      classes: JSON.parse(JSON.stringify(STORE.college.defaultClasses || [])),
      dayNotes: '',
      collegeHours: { start: '09:00', end: '16:00' }
    };
  }
  const sched = STORE.college.schedules[dateStr];
  if(!sched.classes) sched.classes = JSON.parse(JSON.stringify(STORE.college.defaultClasses || []));
  return sched;
}

