function mountFitness(){
  const today = todayStr();

  // Sub tab listeners
  const tTrackers = document.getElementById('ftTabTrackers');
  if(tTrackers) tTrackers.addEventListener('click', () => { fitnessSubTab = 'trackers'; render(); });
  const tGoals = document.getElementById('ftTabGoals');
  if(tGoals) tGoals.addEventListener('click', () => { fitnessSubTab = 'goals'; render(); });
  const tDaily = document.getElementById('ftTabDaily');
  if(tDaily) tDaily.addEventListener('click', () => { fitnessSubTab = 'daily'; render(); });
  const tHistory = document.getElementById('ftTabHistory');
  if(tHistory) tHistory.addEventListener('click', () => { fitnessSubTab = 'history'; render(); });

  // Top buttons & custom exercise triggers
  const addTrackerBtn = document.getElementById('addTrackerBtn');
  if(addTrackerBtn) addTrackerBtn.addEventListener('click', () => openFitnessTrackerModal());
  const addCustomExBtn = document.getElementById('addCustomExerciseBtn');
  if(addCustomExBtn) addCustomExBtn.addEventListener('click', () => openFitnessTrackerModal());
  const addCustomExEmptyBtn = document.getElementById('addCustomExerciseEmptyBtn');
  if(addCustomExEmptyBtn) addCustomExEmptyBtn.addEventListener('click', () => openFitnessTrackerModal());
  const addGoalBtn = document.getElementById('addGoalBtn');
  if(addGoalBtn) addGoalBtn.addEventListener('click', () => openFitnessGoalModal());

  // Quick preset buttons
  document.querySelectorAll('[data-quick-exercise]').forEach(btn => {
    btn.addEventListener('click', () => {
      const name = btn.dataset.quickExercise;
      const unit = btn.dataset.unit || 'reps';
      const target = Number(btn.dataset.target) || 50;
      const category = btn.dataset.cat || 'strength';
      if(!Array.isArray(STORE.fitnessTrackers)) STORE.fitnessTrackers = [];
      STORE.fitnessTrackers.push({
        id: uid(),
        name,
        target,
        achieved: 0,
        unit,
        category,
        sets: 3,
        reps: Math.round(target / 3) || target,
        notes: `Quick preset: ${name}`,
        completed: false,
        date: todayStr()
      });
      checkAchievements();
      save();
      render();
      toast(`💪 Added "${name}" tracker!`);
    });
  });

  // Tracker steppers and actions
  document.querySelectorAll('[data-step-ft]').forEach(b => b.addEventListener('click', () => {
    const tracker = (STORE.fitnessTrackers || []).find(x => x.id === b.dataset.stepFt);
    if(tracker){
      const delta = Number(b.dataset.val || 1);
      tracker.achieved = Math.max(0, Number(tracker.achieved || 0) + delta);
      if(tracker.achieved >= tracker.target) tracker.completed = true;
      addHistoryEntry('fitness', 'Exercise Progress', `Logged ${delta > 0 ? '+' + delta : delta} ${tracker.unit} for ${tracker.name}`);
      checkAchievements();
      save(); render();
    }
  }));

  document.querySelectorAll('[data-toggle-ft]').forEach(b => b.addEventListener('click', () => {
    const tracker = (STORE.fitnessTrackers || []).find(x => x.id === b.dataset.toggleFt);
    if(tracker){
      tracker.completed = !tracker.completed;
      if(tracker.completed && tracker.achieved < tracker.target) tracker.achieved = tracker.target;
      checkAchievements();
      save(); render();
    }
  }));

  document.querySelectorAll('[data-edit-ft]').forEach(b => b.addEventListener('click', () => {
    openFitnessTrackerModal((STORE.fitnessTrackers || []).find(x => x.id === b.dataset.editFt));
  }));

  document.querySelectorAll('[data-del-ft]').forEach(b => b.addEventListener('click', () => {
    if(confirm('Delete this exercise tracker?')){
      STORE.fitnessTrackers = (STORE.fitnessTrackers || []).filter(x => x.id !== b.dataset.delFt);
      save(); render();
    }
  }));

  // Goal actions
  document.querySelectorAll('[data-update-goal-val]').forEach(b => b.addEventListener('click', () => {
    const goal = (STORE.fitnessGoals || []).find(x => x.id === b.dataset.updateGoalVal);
    if(goal){
      const input = prompt(`Enter progress amount to add to "${goal.name}" (${goal.unit}):`, '5');
      if(input !== null){
        const val = Number(input) || 0;
        goal.currentValue = Number(goal.currentValue || 0) + val;
        if(goal.currentValue >= goal.targetValue) goal.status = 'Achieved';
        addHistoryEntry('fitness', 'Goal Progress', `Added ${val} ${goal.unit} towards ${goal.name}`);
        checkAchievements();
        save(); render();
      }
    }
  }));

  document.querySelectorAll('[data-edit-fg]').forEach(b => b.addEventListener('click', () => {
    openFitnessGoalModal((STORE.fitnessGoals || []).find(x => x.id === b.dataset.editFg));
  }));

  document.querySelectorAll('[data-del-fg]').forEach(b => b.addEventListener('click', () => {
    if(confirm('Delete this fitness goal?')){
      STORE.fitnessGoals = (STORE.fitnessGoals || []).filter(x => x.id !== b.dataset.delFg);
      save(); render();
    }
  }));

  // Save Daily log
  const saveFitnessBtn = document.getElementById('saveFitnessBtn');
  if(saveFitnessBtn){
    saveFitnessBtn.addEventListener('click', () => {
      STORE.fitnessLogs[today] = {
        weight: Number(document.getElementById('fWeight')?.value)||null,
        steps: Number(document.getElementById('fSteps')?.value)||null,
        calories: Number(document.getElementById('fCalories')?.value)||null,
        sleepHours: Number(document.getElementById('fSleep')?.value)||null,
        workoutDone: Boolean(document.getElementById('fWorkout')?.checked),
        stretchDone: Boolean(document.getElementById('fStretch')?.checked)
      };
      save(); toast('Fitness log saved'); render();
    });
  }

  // Save Health log
  const saveHealthBtn = document.getElementById('saveHealthBtn');
  if(saveHealthBtn){
    saveHealthBtn.addEventListener('click', () => {
      STORE.healthLogs[today] = {
        tablet: Boolean(document.getElementById('hTablet')?.checked),
        vitD: Boolean(document.getElementById('hVitD')?.checked),
        vitB12: Boolean(document.getElementById('hVitB12')?.checked),
        notes: document.getElementById('hNotes')?.value?.trim() || ''
      };
      save(); toast('Health log saved'); render();
    });
  }

  // Weight chart
  const chartEl = document.getElementById('chartWeight');
  if(chartEl && typeof Chart !== 'undefined'){
    const weights = Object.entries(STORE.fitnessLogs).filter(([,v])=>v.weight).sort((a,b)=>a[0].localeCompare(b[0])).slice(-30);
    charts.chartWeight = new Chart(chartEl, {
      type:'line',
      data:{ labels: weights.map(w=>w[0].slice(5)), datasets:[{ data: weights.map(w=>w[1].weight), borderColor:'#8c93ff', backgroundColor:'#8c93ff22', fill:true, tension:.3, pointRadius:3 }] },
      options: chartOpts()
    });
  }
}

function openFitnessTrackerModal(tracker){
  const isEdit = !!tracker;
  openModal(isEdit ? 'Edit Exercise Tracker' : 'Add Custom Exercise Tracker', `
    <div class="form-row"><label>Exercise Name</label><input id="ftName" value="${tracker ? escapeHtml(tracker.name) : ''}" placeholder="e.g. Push-ups, Squats, Bench Press, Running"/></div>
    <div class="form-grid">
      <div class="form-row"><label>Target Amount</label><input type="number" id="ftTarget" value="${tracker ? tracker.target : 50}"/></div>
      <div class="form-row"><label>Achieved So Far</label><input type="number" id="ftAchieved" value="${tracker ? tracker.achieved : 0}"/></div>
    </div>
    <div class="form-grid">
      <div class="form-row"><label>Unit</label>
        <select id="ftUnit">
          ${['reps','sets','mins','km','steps','kg'].map(u=>`<option ${tracker && tracker.unit===u ? 'selected':''}>${u}</option>`).join('')}
        </select>
      </div>
      <div class="form-row"><label>Category</label>
        <select id="ftCategory">
          ${['strength','cardio','core','gym','custom'].map(c=>`<option ${tracker && tracker.category===c ? 'selected':''}>${c}</option>`).join('')}
        </select>
      </div>
    </div>
    <div class="form-grid">
      <div class="form-row"><label>Default Sets</label><input type="number" id="ftSets" value="${tracker ? tracker.sets || 3 : 3}"/></div>
      <div class="form-row"><label>Reps per Set</label><input type="number" id="ftReps" value="${tracker ? tracker.reps || 15 : 15}"/></div>
    </div>
    <div class="form-row"><label>Notes / Routine Details</label><textarea id="ftNotes">${tracker ? escapeHtml(tracker.notes||'') : ''}</textarea></div>
    <div class="form-actions"><button class="btn btn-ghost" id="mCancel">Cancel</button><button class="btn btn-accent" id="mSave">${isEdit ? 'Save Changes' : 'Add Exercise'}</button></div>
  `, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSave')?.addEventListener('click', () => {
      const name = modal.querySelector('#ftName').value.trim();
      if(!name) return toast('Enter exercise name');
      const data = {
        name,
        target: Number(modal.querySelector('#ftTarget').value || 1),
        achieved: Number(modal.querySelector('#ftAchieved').value || 0),
        unit: modal.querySelector('#ftUnit').value,
        category: modal.querySelector('#ftCategory').value,
        sets: Number(modal.querySelector('#ftSets').value || 1),
        reps: Number(modal.querySelector('#ftReps').value || 1),
        notes: modal.querySelector('#ftNotes').value.trim(),
        completed: Number(modal.querySelector('#ftAchieved').value || 0) >= Number(modal.querySelector('#ftTarget').value || 1)
      };
      if(!Array.isArray(STORE.fitnessTrackers)) STORE.fitnessTrackers = [];
      if(isEdit) Object.assign(tracker, data);
      else STORE.fitnessTrackers.push({ id: uid(), ...data, date: todayStr() });
      checkAchievements();
      save(); closeModal(); render();
      toast(isEdit ? 'Exercise updated' : 'Custom exercise added');
    });
  });
}

function openFitnessGoalModal(goal){
  const isEdit = !!goal;
  openModal(isEdit ? 'Edit Fitness Goal' : 'Create Custom Fitness Goal', `
    <div class="form-row"><label>Goal Name / Challenge</label><input id="fgName" value="${goal ? escapeHtml(goal.name) : ''}" placeholder="e.g. 1000 Push-ups Challenge"/></div>
    <div class="form-grid">
      <div class="form-row"><label>Start Date</label><input type="date" id="fgStart" value="${goal ? goal.startDate : todayStr()}"/></div>
      <div class="form-row"><label>Target Date</label><input type="date" id="fgTargetDate" value="${goal ? goal.targetDate : addDays(todayStr(), 30)}"/></div>
    </div>
    <div class="form-grid">
      <div class="form-row"><label>Target Value</label><input type="number" id="fgTargetVal" value="${goal ? goal.targetValue : 1000}"/></div>
      <div class="form-row"><label>Current Progress</label><input type="number" id="fgCurrentVal" value="${goal ? goal.currentValue : 0}"/></div>
    </div>
    <div class="form-grid">
      <div class="form-row"><label>Unit</label><input id="fgUnit" value="${goal ? escapeHtml(goal.unit) : 'reps'}" placeholder="reps, km, mins, kg"/></div>
      <div class="form-row"><label>Frequency</label>
        <select id="fgFreq">${['daily','weekly','monthly','custom'].map(f=>`<option ${goal && goal.frequency===f?'selected':''}>${f}</option>`).join('')}</select>
      </div>
    </div>
    <div class="form-row"><label>Strategy / Notes</label><textarea id="fgNotes">${goal ? escapeHtml(goal.notes||'') : ''}</textarea></div>
    <div class="form-actions"><button class="btn btn-ghost" id="mCancel">Cancel</button><button class="btn btn-accent" id="mSave">${isEdit ? 'Save Changes' : 'Create Goal'}</button></div>
  `, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSave')?.addEventListener('click', () => {
      const name = modal.querySelector('#fgName').value.trim();
      if(!name) return toast('Enter goal name');
      const data = {
        name,
        startDate: modal.querySelector('#fgStart').value || todayStr(),
        targetDate: modal.querySelector('#fgTargetDate').value || addDays(todayStr(), 30),
        targetValue: Number(modal.querySelector('#fgTargetVal').value || 100),
        currentValue: Number(modal.querySelector('#fgCurrentVal').value || 0),
        unit: modal.querySelector('#fgUnit').value.trim() || 'reps',
        frequency: modal.querySelector('#fgFreq').value,
        notes: modal.querySelector('#fgNotes').value.trim(),
        status: Number(modal.querySelector('#fgCurrentVal').value || 0) >= Number(modal.querySelector('#fgTargetVal').value || 100) ? 'Achieved' : 'In Progress'
      };
      if(isEdit) Object.assign(goal, data);
      else STORE.fitnessGoals.push({ id: uid(), ...data });
      checkAchievements();
      save(); closeModal(); render();
    });
  });
}

/* ==========================================================================
   FINANCE & EXPENSE TRACKING
   ========================================================================== */
const EXPENSE_CATEGORIES = ['Food','Transport','Education','Subscriptions','Entertainment','Health','Shopping','Savings','Other'];

function renderFinance(){
  const monthEntries = (STORE.finance || []).filter(f => f.date.startsWith(financeMonth));
  const income = monthEntries.filter(f=>f.type==='income').reduce((s,f)=>s+Number(f.amount),0);
  const expense = monthEntries.filter(f=>f.type==='expense').reduce((s,f)=>s+Number(f.amount),0);
  const byCat = {};
  monthEntries.filter(f=>f.type==='expense').forEach(f => byCat[f.category] = (byCat[f.category]||0)+Number(f.amount));
  const sorted = [...monthEntries].sort((a,b)=>b.date.localeCompare(a.date));

  return `
    <div class="section-hero">
      <div>
        <div class="section-badge">Finance &amp; Budget Command</div>
        <div class="section-hero-title">Stay aware of where your money goes</div>
        <div class="section-pill-row">
          <span class="section-pill">💸 ${monthEntries.filter(f=>f.type==='expense').length} expenses</span>
          <span class="section-pill">📈 ${monthEntries.filter(f=>f.type==='income').length} incomes</span>
          <span class="section-pill" style="color:${income-expense>=0?'var(--accent)':'var(--danger)'}; font-weight:700;">⚖️ Net: ₹${(income-expense).toLocaleString()}</span>
        </div>
      </div>
      <div class="flex gap-8" style="align-items:center; flex-wrap:wrap;">
        <button class="btn btn-ghost" id="manageRecurringBtn">🔄 Recurring Expenses</button>
        <input type="month" id="financeMonthInput" value="${financeMonth}" style="background:var(--bg-2); border:1px solid var(--border); color:var(--text); padding:8px 10px; border-radius:9px; font-family:inherit;"/>
        <button class="btn btn-accent" id="addFinanceBtn">+ Add Entry</button>
      </div>
    </div>

    <!-- Top Stats -->
    <div class="grid grid-3" style="gap:16px;">
      <div class="card stat-card"><div class="stat-label">Income (${financeMonth})</div><div class="stat-value accent">₹${income.toLocaleString()}</div></div>
      <div class="card stat-card"><div class="stat-label">Expenses (${financeMonth})</div><div class="stat-value" style="color:var(--danger);">₹${expense.toLocaleString()}</div></div>
      <div class="card stat-card"><div class="stat-label">Net Savings</div><div class="stat-value ${income-expense>=0?'accent':''}">₹${(income-expense).toLocaleString()}</div></div>
    </div>

    <!-- Charts and Transactions Grid -->
    <div class="grid grid-2" style="margin-top:16px; align-items:start; gap:16px;">
      ${renderCollapsibleSection({
        key: `finance_chart_${financeMonth}`,
        title: 'Spend by Category & Breakdown',
        icon: '📊',
        countLabel: `${Object.keys(byCat).length} categories`,
        defaultExpanded: true,
        contentHtml: `
          <div style="display:flex; flex-direction:column; gap:16px;">
            ${Object.keys(byCat).length ? `<div class="chart-box" style="height:260px;"><canvas id="chartFinance"></canvas></div>` : `<div class="empty-state" style="padding:24px;"><div class="msg">No expenses logged for this month.</div></div>`}
          </div>
        `
      })}

      ${renderCollapsibleSection({
        key: `finance_entries_${financeMonth}`,
        title: 'Transactions & Entries',
        icon: '💳',
        countLabel: `${sorted.length} entries`,
        defaultExpanded: true,
        contentHtml: `
          <div class="table-wrap" style="max-height:360px; overflow-y:auto;">
            <table>
              <thead><tr><th>Date</th><th>Category</th><th>Note</th><th>Amount</th><th></th></tr></thead>
              <tbody>
              ${sorted.length ? sorted.map(f => `
                <tr><td class="mono">${f.date}</td><td><span class="pill pill-dim">${f.category}</span></td><td>${escapeHtml(f.note||'—')}</td>
                  <td class="mono" style="color:${f.type==='income'?'var(--accent)':'var(--danger)'}">${f.type==='income'?'+':'−'}₹${Number(f.amount).toLocaleString()}</td>
                  <td><button class="btn btn-sm btn-ghost" data-del-fin="${f.id}">✕</button></td></tr>`).join('') :
                `<tr><td colspan="5"><div class="empty-state" style="padding:20px;"><div class="msg">No entries for this month.</div></div></td></tr>`}
              </tbody>
            </table>
          </div>
        `,
        actionBtnHtml: `<button class="btn btn-sm btn-accent" id="addFinanceBtnCard">+ Add Entry</button>`
      })}
    </div>
  `;
}

function mountFinance(){
  document.getElementById('financeMonthInput')?.addEventListener('change', e => { financeMonth = e.target.value; render(); });

  const recBtn = document.getElementById('manageRecurringBtn');
  if(recBtn) recBtn.addEventListener('click', openRecurringExpensesModal);
  
  if(typeof RecurringFinance !== 'undefined' && RecurringFinance.processDueExpenses){
    const processed = RecurringFinance.processDueExpenses(STORE);
    if(processed > 0){
      save();
      toast(`🔄 Processed ${processed} recurring expenses for this month`);
    }
  }

  const addFinanceBtn = document.getElementById('addFinanceBtn');
  if(addFinanceBtn) addFinanceBtn.addEventListener('click', () => openFinanceModal());
  const addFinanceBtnCard = document.getElementById('addFinanceBtnCard');
  if(addFinanceBtnCard) addFinanceBtnCard.addEventListener('click', () => openFinanceModal());
  
  document.querySelectorAll('[data-del-fin]').forEach(b => b.addEventListener('click', () => {
    STORE.finance = STORE.finance.filter(f => f.id !== b.dataset.delFin); save(); render();
  }));

  const monthEntries = (STORE.finance || []).filter(f => f.date.startsWith(financeMonth) && f.type==='expense');
  const chartEl = document.getElementById('chartFinance');
  if(chartEl && monthEntries.length && typeof Chart !== 'undefined'){
    safeDestroyChart('chartFinance');
    const byCat = {};
    monthEntries.forEach(f => byCat[f.category] = (byCat[f.category]||0)+Number(f.amount));
    charts.chartFinance = new Chart(chartEl, {
      type:'doughnut',
      data:{ labels:Object.keys(byCat), datasets:[{ data:Object.values(byCat), backgroundColor:['#4f8cff','#c084fc','#38bdf8','#4ade80','#fbbf24','#f87171','#f472b6','#a78bfa','#94a3b8'] }] },
      options:{ responsive:true, maintainAspectRatio:false, plugins:{ legend:{ position:'bottom', labels:{ color:'#8a93a3', boxWidth:10, font:{size:11} } } } }
    });
  }
}

function openFinanceModal(){
  openModal('Add Finance Entry', `
    <div class="form-grid">
      <div class="form-row"><label>Type</label><select id="finType"><option value="expense">Expense</option><option value="income">Income</option></select></div>
      <div class="form-row"><label>Date</label><input type="date" id="finDate" value="${todayStr()}"/></div>
    </div>
    <div class="form-grid">
      <div class="form-row"><label>Category</label><select id="finCat">${EXPENSE_CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></div>
      <div class="form-row"><label>Amount (₹) *</label><input type="number" id="finAmount" placeholder="Enter amount" autofocus/></div>
    </div>
    <div class="form-row"><label>Note</label><input id="finNote" placeholder="Enter description or note"/></div>
    <div class="form-actions"><button type="button" class="btn btn-ghost" id="mCancel">Cancel</button><button type="button" class="btn btn-accent" id="mSave">Add Entry</button></div>
  `, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSave')?.addEventListener('click', () => {
      const amount = Number(modal.querySelector('#finAmount').value);
      if(!amount) return toast('Enter an amount');
      STORE.finance.push({ id: uid(), type: modal.querySelector('#finType').value, date: modal.querySelector('#finDate').value||todayStr(),
        category: modal.querySelector('#finCat').value, amount, note: modal.querySelector('#finNote').value.trim() });
      save(); closeModal(); render();
    });
  });
}

/* ==========================================================================
   JOURNAL (SEARCH, MOOD FILTERS & SLEEP QUALITY STARS)
   ========================================================================== */
let journalSearchQuery = '';
let journalMoodFilter = 'all';

function renderJournal(){
  let list = [...STORE.journal];
  if(journalSearchQuery.trim()){
    const q = journalSearchQuery.toLowerCase();
    list = list.filter(j => (j.content||'').toLowerCase().includes(q) || (j.wins||'').toLowerCase().includes(q) || (j.lessons||'').toLowerCase().includes(q));
  }
  if(journalMoodFilter !== 'all'){
    list = list.filter(j => String(j.mood) === String(journalMoodFilter));
  }
  const sorted = list.sort((a,b)=>b.date.localeCompare(a.date));

  const journalContent = `
    <div class="grid grid-2" style="align-items:start; gap:16px;">
      ${sorted.length ? sorted.map(j => `
        <div class="card" style="border-left:4px solid var(--accent); padding:18px;">
          <div class="flex between align-center mb-12">
            <div class="flex items-center gap-10">
              <span class="mono accent" style="font-weight:700; font-size:15px;">📅 ${j.date}</span>
              ${j.sleepQuality ? `<span title="Sleep Quality: ${j.sleepQuality}/5 stars" style="font-size:13px; color:#fbbf24;">${'★'.repeat(j.sleepQuality)}${'☆'.repeat(5-j.sleepQuality)}</span>` : ''}
            </div>
            <div class="flex gap-8" style="align-items:center;">
              <span class="pill pill-dim">${j.type || 'Reflection'}</span>
              ${j.mood ? `<span style="font-size:20px;" title="Mood">${MOOD_EMOJI[(j.mood||3)-1] || '🙂'}</span>` : ''}
              <button class="btn btn-sm btn-ghost" data-edit-journal="${j.id}" title="Edit reflection">✎</button>
              <button class="btn btn-sm btn-ghost" data-del-journal="${j.id}" title="Delete reflection">🗑</button>
            </div>
          </div>

          ${j.wins ? `
            <div class="mb-10" style="background:var(--bg-2); padding:10px 12px; border-radius:8px; border:1px solid var(--border-soft);">
              <div style="font-weight:700; font-size:12.5px; color:var(--accent); margin-bottom:4px;">🏆 Victories &amp; Wins</div>
              <div style="font-size:13px; line-height:1.5; color:var(--text-bright);">${mdLite(escapeHtml(j.wins))}</div>
            </div>
          ` : ''}

          ${j.lessons ? `
            <div class="mb-10" style="background:var(--bg-2); padding:10px 12px; border-radius:8px; border:1px solid var(--border-soft);">
              <div style="font-weight:700; font-size:12.5px; color:var(--accent2); margin-bottom:4px;">💡 Lessons &amp; Reflections</div>
              <div style="font-size:13px; line-height:1.5; color:var(--text-bright);">${mdLite(escapeHtml(j.lessons))}</div>
            </div>
          ` : ''}

          ${j.content ? `
            <div class="mt-8" style="background:var(--bg-2); padding:10px 12px; border-radius:8px; border:1px solid var(--border-soft);">
              <div style="font-weight:700; font-size:12.5px; color:var(--text-dim); margin-bottom:4px;">💭 General Thoughts</div>
              <div style="font-size:13px; line-height:1.5; color:var(--text-bright);">${mdLite(escapeHtml(j.content))}</div>
            </div>
          ` : ''}
        </div>`).join('') : `
          <div class="card" style="grid-column:span 2;">
            <div class="empty-state" style="padding:36px; text-align:center;">
              <div style="font-size:36px; margin-bottom:10px;">✍️</div>
              <div class="msg" style="font-size:16px; font-weight:700; color:var(--text-bright); margin-bottom:6px;">No Journal Entries Yet</div>
              <div class="dim" style="font-size:13px; margin-bottom:18px;">Start a 4-step guided evening reflection to capture wins, lessons, and thoughts.</div>
              <button class="btn btn-accent btn-sm" onclick="openJournalModal()">+ Write First Reflection</button>
            </div>
          </div>
        `}
    </div>
  `;

  return `
    <div class="section-hero">
      <div>
        <div class="section-badge">Journal &amp; Mind</div>
        <div class="section-hero-title">Reflect on your days and build clarity</div>
        <div class="section-pill-row">
          <span class="section-pill">📖 ${STORE.journal.length} reflections</span>
        </div>
      </div>
      <div class="flex gap-8 wrap">
        <button class="btn btn-ghost" id="journalWeeklySummaryBtn">📧 Weekly Summary (.md)</button>
        <button class="btn btn-ghost" id="eveningReflectionBtn">🌅 Evening Reflection</button>
        <button class="btn btn-accent" id="addJournalBtn">+ New Entry</button>
      </div>
    </div>

    <!-- Search & Mood Filter Bar -->
    <div class="card mb-16" style="padding:12px 16px;">
      <div class="flex between items-center wrap gap-10">
        <div class="flex gap-6 items-center wrap">
          <span class="dim" style="font-size:12px; font-weight:700;">Mood:</span>
          <button class="btn btn-xs ${journalMoodFilter==='all'?'btn-accent':'btn-ghost'}" data-jfilter="all">All</button>
          <button class="btn btn-xs ${journalMoodFilter==='5'?'btn-accent':'btn-ghost'}" data-jfilter="5">😄 Great</button>
          <button class="btn btn-xs ${journalMoodFilter==='4'?'btn-accent':'btn-ghost'}" data-jfilter="4">🙂 Good</button>
          <button class="btn btn-xs ${journalMoodFilter==='3'?'btn-accent':'btn-ghost'}" data-jfilter="3">😐 Neutral</button>
          <button class="btn btn-xs ${journalMoodFilter==='1'?'btn-accent':'btn-ghost'}" data-jfilter="1">😫 Stressed</button>
        </div>
        <input id="journalSearchInput" placeholder="🔍 Search reflections, wins, lessons…" value="${escapeHtml(journalSearchQuery)}" style="padding:6px 12px; font-size:13px; min-width:240px; border-radius:8px; border:1px solid var(--border); background:var(--bg-3); color:var(--text);" />
      </div>
    </div>

    ${renderCollapsibleSection({
      key: 'journal_entries',
      title: 'Journal & Reflections Log',
      icon: '📖',
      countLabel: `${sorted.length} entries`,
      defaultExpanded: true,
      contentHtml: journalContent
    })}
  `;
}

function openJournalModal(entry){
  const isEdit = !!entry;
  let currentStep = 1;

  const draft = {
    date: entry ? entry.date : todayStr(),
    mood: entry ? Number(entry.mood) || 4 : 4,
    sleepQuality: entry ? Number(entry.sleepQuality) || 4 : 4,
    wins: entry ? (entry.wins || '') : '',
    lessons: entry ? (entry.lessons || '') : '',
    content: entry ? (entry.content || '') : '',
    type: (entry && entry.type) || 'daily'
  };

  const renderStep = (step) => {
    let bodyHtml = '';
    const stepIndicators = [
      { num: 1, title: 'Basics & Mood' },
      { num: 2, title: 'Victories & Wins' },
      { num: 3, title: 'Lessons' },
      { num: 4, title: 'Thoughts' }
    ].map(s => `
      <div class="flex items-center gap-4" style="flex:1; cursor:pointer;" onclick="window.goToJournalStep(${s.num})">
        <div style="width:24px; height:24px; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:700; background:${s.num === step ? 'var(--accent)' : s.num < step ? 'var(--bg-3)' : 'var(--bg-2)'}; color:${s.num === step ? '#fff' : s.num < step ? 'var(--accent)' : 'var(--text-dim)'}; border:1px solid ${s.num === step ? 'var(--accent)' : 'var(--border-soft)'};">
          ${s.num < step ? '✓' : s.num}
        </div>
        <span style="font-size:12px; font-weight:${s.num === step ? '700' : '500'}; color:${s.num === step ? 'var(--text-bright)' : 'var(--text-dim)'}; display:none; @media(min-width:480px){display:inline;}">
          ${s.title}
        </span>
      </div>
    `).join('<div style="width:16px; height:1px; background:var(--border-soft); margin:0 4px;"></div>');

    if(step === 1){
      bodyHtml = `
        <div style="margin-bottom:16px;">
          <div style="font-size:16px; font-weight:700; color:var(--text-bright); margin-bottom:4px;">Step 1: Entry Basics &amp; Mindset</div>
          <div class="dim" style="font-size:12.5px;">Record the date, how you felt, and your rest quality.</div>
        </div>

        <div class="form-row" style="margin-bottom:14px;">
          <label style="font-size:12.5px; font-weight:600; color:var(--text-bright);">Entry Date</label>
          <input type="date" id="jStepDate" value="${draft.date}" style="width:100%; padding:8px 10px; border-radius:8px; border:1px solid var(--border); background:var(--bg-2); color:var(--text);"/>
        </div>

        <div class="form-row" style="margin-bottom:14px;">
          <label style="font-size:12.5px; font-weight:600; color:var(--text-bright);">How was your mood today?</label>
          <div class="grid grid-3" style="gap:8px; margin-top:6px;">
            ${[
              { val: 5, emoji: '😄', label: 'Great / Flow' },
              { val: 4, emoji: '🙂', label: 'Good / Steady' },
              { val: 3, emoji: '😐', label: 'Neutral / Okay' },
              { val: 2, emoji: '🙁', label: 'Low / Tired' },
              { val: 1, emoji: '😫', label: 'Stressed / Off' }
            ].map(m => `
              <button type="button" class="btn btn-sm ${draft.mood === m.val ? 'btn-accent' : 'btn-ghost'}" style="padding:10px 8px; display:flex; flex-direction:column; align-items:center; gap:4px; border:1px solid ${draft.mood === m.val ? 'var(--accent)' : 'var(--border-soft)'};" onclick="window.selectJournalMood(${m.val})">
                <span style="font-size:22px;">${m.emoji}</span>
                <span style="font-size:11px; font-weight:600;">${m.label}</span>
              </button>
            `).join('')}
          </div>
        </div>

        <div class="form-row" style="margin-bottom:14px;">
          <label style="font-size:12.5px; font-weight:600; color:var(--text-bright);">Sleep Quality / Day Rating (1-5 Stars)</label>
          <div class="flex gap-8 items-center mt-6" style="background:var(--bg-2); padding:10px 14px; border-radius:8px; border:1px solid var(--border-soft);">
            ${[1, 2, 3, 4, 5].map(star => `
              <button type="button" class="btn btn-ghost" style="font-size:22px; padding:2px 4px; color:${star <= draft.sleepQuality ? '#fbbf24' : 'var(--text-dim)'}; border:none; background:transparent;" onclick="window.selectJournalSleep(${star})">
                ${star <= draft.sleepQuality ? '★' : '☆'}
              </button>
            `).join('')}
            <span class="dim" style="font-size:12.5px; margin-left:8px; font-weight:600;">(${draft.sleepQuality} of 5 Stars)</span>
          </div>
        </div>

        <div class="form-actions" style="margin-top:20px; display:flex; justify-content:flex-end; gap:8px;">
          <button class="btn btn-ghost" onclick="closeModal()">Cancel</button>
          <button class="btn btn-accent" onclick="window.saveAndNextJournal(1)">Save &amp; Next: Victories &amp; Wins →</button>
        </div>
      `;
    } else if(step === 2){
      bodyHtml = `
        <div style="margin-bottom:16px;">
          <div style="font-size:16px; font-weight:700; color:var(--text-bright); margin-bottom:4px;">Step 2: Victories &amp; Wins 🏆</div>
          <div class="dim" style="font-size:12.5px;">What went well today? What accomplishments or small steps are you proud of?</div>
        </div>

        <div class="form-row">
          <textarea id="jStepWins" class="journal-textarea form-input" placeholder="Write about your accomplishments, wins, or positive moments today..." autofocus>${escapeHtml(draft.wins)}</textarea>
        </div>

        <div class="form-actions" style="margin-top:20px; display:flex; justify-content:space-between; gap:8px;">
          <button type="button" class="btn btn-ghost" onclick="window.goToJournalStep(1)">← Back to Basics</button>
          <button type="button" class="btn btn-accent" onclick="window.saveAndNextJournal(2)">Save &amp; Next: Lessons &amp; Reflections →</button>
        </div>
      `;
    } else if(step === 3){
      bodyHtml = `
        <div style="margin-bottom:16px;">
          <div style="font-size:16px; font-weight:700; color:var(--text-bright); margin-bottom:4px;">Step 3: Lessons &amp; Reflections 💡</div>
          <div class="dim" style="font-size:12.5px;">What did you learn today? What would you do differently next time to improve?</div>
        </div>

        <div class="form-row">
          <textarea id="jStepLessons" class="journal-textarea form-input" placeholder="Write about lessons learned and areas for continuous improvement..." autofocus>${escapeHtml(draft.lessons)}</textarea>
        </div>

        <div class="form-actions" style="margin-top:20px; display:flex; justify-content:space-between; gap:8px;">
          <button type="button" class="btn btn-ghost" onclick="window.goToJournalStep(2)">← Back to Wins</button>
          <button type="button" class="btn btn-accent" onclick="window.saveAndNextJournal(3)">Save &amp; Next: General Thoughts →</button>
        </div>
      `;
    } else if(step === 4){
      bodyHtml = `
        <div style="margin-bottom:16px;">
          <div style="font-size:16px; font-weight:700; color:var(--text-bright); margin-bottom:4px;">Step 4: General Thoughts &amp; Notes 💭</div>
          <div class="dim" style="font-size:12.5px;">Anything else on your mind? Ideas, gratitude, or focus points for tomorrow.</div>
        </div>

        <div class="form-row">
          <textarea id="jStepContent" class="journal-textarea form-input" placeholder="Write your general thoughts, reflections, or ideas..." autofocus>${escapeHtml(draft.content)}</textarea>
        </div>

        <div class="form-actions" style="margin-top:20px; display:flex; justify-content:space-between; gap:8px;">
          <button type="button" class="btn btn-ghost" onclick="window.goToJournalStep(3)">← Back to Lessons</button>
          <button type="button" class="btn btn-accent" onclick="window.finishJournalEntry()">💾 Save Reflection &amp; Finish ✨</button>
        </div>
      `;
    }

    return `
      <div class="modal-header">
        <h2>${isEdit ? '✏️ Edit Journal Entry' : '✨ Daily Journal Reflection'}</h2>
        <button class="close-modal">✕</button>
      </div>

      <div class="flex items-center gap-8 mb-16" style="background:var(--bg-2); padding:10px 14px; border-radius:8px; border:1px solid var(--border-soft);">
        ${stepIndicators}
      </div>

      <div id="journalStepBody">
        ${bodyHtml}
      </div>
    `;
  };

  const updateModalContent = (modalEl) => {
    modalEl.innerHTML = renderStep(currentStep);
    modalEl.querySelector('.close-modal')?.addEventListener('click', closeModal);
  };

  openModal(isEdit ? 'Edit Reflection' : 'Daily Journal Reflection', renderStep(1), modalEl => {
    modalEl.querySelector('.close-modal')?.addEventListener('click', closeModal);

    window.selectJournalMood = (m) => {
      draft.mood = m;
      updateModalContent(modalEl);
    };

    window.selectJournalSleep = (s) => {
      draft.sleepQuality = s;
      updateModalContent(modalEl);
    };

    window.goToJournalStep = (s) => {
      // Sync current step inputs before switching
      if(currentStep === 1){
        const dEl = modalEl.querySelector('#jStepDate');
        if(dEl) draft.date = dEl.value || todayStr();
      } else if(currentStep === 2){
        const wEl = modalEl.querySelector('#jStepWins');
        if(wEl) draft.wins = wEl.value;
      } else if(currentStep === 3){
        const lEl = modalEl.querySelector('#jStepLessons');
        if(lEl) draft.lessons = lEl.value;
      } else if(currentStep === 4){
        const cEl = modalEl.querySelector('#jStepContent');
        if(cEl) draft.content = cEl.value;
      }
      currentStep = s;
      updateModalContent(modalEl);
    };

    window.saveAndNextJournal = (fromStep) => {
      window.goToJournalStep(fromStep + 1);
    };

    window.finishJournalEntry = () => {
      const cEl = modalEl.querySelector('#jStepContent');
      if(cEl) draft.content = cEl.value;

      if(!draft.wins.trim() && !draft.lessons.trim() && !draft.content.trim()){
        return toast('Please write at least one thought, victory, or lesson before saving');
      }

      if(!STORE.journal) STORE.journal = [];
      if(isEdit){
        Object.assign(entry, draft);
      } else {
        STORE.journal.push({
          id: uid(),
          ...draft,
          createdAt: new Date().toISOString()
        });
      }
      save(); closeModal(); render();
      toast(isEdit ? 'Reflection updated!' : '✨ Daily reflection saved successfully!');
    };
  });
}

function mountJournal(){
  const searchInput = document.getElementById('journalSearchInput');
  if(searchInput){
    searchInput.addEventListener('input', e => { journalSearchQuery = e.target.value; render(); });
  }

  document.querySelectorAll('[data-jfilter]').forEach(btn => {
    btn.addEventListener('click', () => { journalMoodFilter = btn.dataset.jfilter; render(); });
  });

  const wkJournBtn = document.getElementById('journalWeeklySummaryBtn');
  if(wkJournBtn) wkJournBtn.addEventListener('click', openWeeklySummaryModal);
  const eveBtn = document.getElementById('eveningReflectionBtn');
  if(eveBtn) eveBtn.addEventListener('click', () => openJournalModal());
  document.getElementById('addJournalBtn')?.addEventListener('click', () => openJournalModal());
  document.querySelectorAll('[data-edit-journal]').forEach(b => b.addEventListener('click', () => openJournalModal(STORE.journal.find(j=>j.id===b.dataset.editJournal))));
  document.querySelectorAll('[data-del-journal]').forEach(b => b.addEventListener('click', () => {
    if(confirm('Delete entry?')){ STORE.journal = STORE.journal.filter(j=>j.id!==b.dataset.delJournal); save(); render(); }
  }));
}

/* ==========================================================================
   MISTAKE TRACKER (WITH SPACED REPETITION SRS)
   ========================================================================== */
const MISTAKE_CATEGORIES = ['Technical','Procrastination','Focus','Health','Communication','Other'];
const SRS_INTERVALS = [1, 3, 7, 14, 30, 90];
const SRS_STAGE_NAMES = ['Stage 1 (1d)', 'Stage 2 (3d)', 'Stage 3 (7d)', 'Stage 4 (14d)', 'Stage 5 (30d)', 'Mastered 🎓'];

function renderMistakes(){
  let list = STORE.mistakes;
  const tStr = todayStr();

  // Initialize SRS fields if missing
  list.forEach(m => {
    if(m.srsStage === undefined) m.srsStage = 0;
    if(!m.nextReviewDate) m.nextReviewDate = m.date || tStr;
    if(m.reviewCount === undefined) m.reviewCount = 0;
  });

  const dueCount = list.filter(m => (m.srsStage || 0) < 5 && (m.nextReviewDate || '') <= tStr).length;

  if(mistakesFilter === 'due'){
    list = list.filter(m => (m.srsStage || 0) < 5 && (m.nextReviewDate || '') <= tStr);
  } else if(mistakesFilter !== 'all'){
    list = list.filter(m => m.category === mistakesFilter);
  }
  const sorted = [...list].sort((a,b)=> (b.nextReviewDate || b.date).localeCompare(a.nextReviewDate || a.date));

  const mistakesContent = `
    <div class="grid grid-2" style="align-items:start; gap:16px;">
      ${sorted.length ? sorted.map(m => {
        const stage = m.srsStage || 0;
        const isMastered = stage >= 5;
        const isDue = !isMastered && (m.nextReviewDate || '') <= tStr;
        let srsBadgeClass = 'srs-learning';
        let srsBadgeText = `🟡 Next: ${m.nextReviewDate || 'Today'}`;
        if(isMastered){
          srsBadgeClass = 'srs-mastered';
          srsBadgeText = '🎓 Mastered & Retained';
        } else if(isDue){
          srsBadgeClass = 'srs-due';
          srsBadgeText = '⚠️ Due for Review Today';
        }

        return `
          <div class="card" style="border:1px solid ${isDue ? 'rgba(239, 68, 68, 0.4)' : 'var(--border-soft)'};">
            <div class="flex between align-center">
              <div class="item-title" style="font-weight:700;">${escapeHtml(m.description)}</div>
              <span class="pill pill-danger">${m.category}</span>
            </div>
            
            <div class="flex between align-center mt-6">
              <div class="dim mono" style="font-size:11px;">Logged: ${m.date}</div>
              <span class="srs-badge ${srsBadgeClass}">${srsBadgeText}</span>
            </div>

            <div class="mt-8" style="background:var(--bg-3); padding:10px 12px; border-radius:8px; border-left:3px solid var(--accent); font-size:13px;">
              <strong>Lesson learned:</strong>
              <div style="margin-top:2px; color:var(--text-bright);">${mdLite(escapeHtml(m.lesson))}</div>
            </div>
            
            ${m.prevention ? `<div class="mt-8" style="font-size:12.5px; color:var(--text-dim);"><strong>Action to prevent:</strong> ${escapeHtml(m.prevention)}</div>` : ''}
            
            <!-- SRS Review Progress Indicator -->
            <div class="flex between align-center mt-12 pt-8" style="border-top:1px solid var(--border-soft); font-size:12px;">
              <span class="dim">SRS Stage: <strong>${SRS_STAGE_NAMES[stage] || 'Stage 1'}</strong> (${m.reviewCount || 0} reviews)</span>
              <div class="flex gap-6">
                ${!isMastered ? `<button class="btn btn-sm btn-accent" data-srs-review="${m.id}" title="Review lesson and advance Spaced Repetition interval">🔁 Mark Reviewed (+SRS)</button>` : ''}
                <button class="btn btn-sm btn-ghost" data-edit-mistake="${m.id}" title="Edit">✎</button>
                <button class="btn btn-sm btn-ghost" data-del-mistake="${m.id}" title="Delete">🗑</button>
              </div>
            </div>
          </div>
        `;
      }).join('') : `<div class="card" style="grid-column:span 2;"><div class="empty-state"><div class="glyph">🛡</div><div class="msg">No mistakes logged in this view. Great streak!</div></div></div>`}
    </div>
  `;

  return `
    <div class="section-hero">
      <div>
        <div class="section-badge">Mistakes &amp; Spaced Repetition (SRS)</div>
        <div class="section-hero-title">Log errors once so you never repeat them</div>
        <div class="section-pill-row">
          <span class="section-pill">⚠️ ${STORE.mistakes.length} mistakes logged</span>
          <span class="section-pill" style="${dueCount > 0 ? 'background:rgba(239,68,68,0.2); color:#f87171;' : ''}">🔔 ${dueCount} due for review</span>
        </div>
      </div>
      <div class="flex gap-8 wrap">
        <button class="btn btn-ghost" id="mistakesFlashcardsBtn">🎴 Study with Flashcards</button>
        <button class="btn btn-accent" id="addMistakeBtn">+ Log Mistake</button>
      </div>
    </div>
    <div class="card" style="margin-bottom:16px;">
      <div class="tabs">
        <button class="tab ${mistakesFilter==='all'?'active':''}" data-mfilter="all">All (${STORE.mistakes.length})</button>
        <button class="tab ${mistakesFilter==='due'?'active':''}" data-mfilter="due" style="${dueCount > 0 ? 'color:#f87171; font-weight:700;' : ''}">🔔 Due for Review (${dueCount})</button>
        ${MISTAKE_CATEGORIES.map(c => {
          const count = STORE.mistakes.filter(m=>m.category===c).length;
          return `<button class="tab ${mistakesFilter===c?'active':''}" data-mfilter="${c}">${c} (${count})</button>`;
        }).join('')}
      </div>
    </div>

    ${renderCollapsibleSection({
      key: `mistakes_list_${mistakesFilter}`,
      title: 'Logged Mistakes & Action Plans',
      icon: '🛡️',
      countLabel: `${sorted.length} records`,
      defaultExpanded: false,
      contentHtml: mistakesContent
    })}
  `;
}

function mountMistakes(){
  document.querySelectorAll('[data-mfilter]').forEach(b => b.addEventListener('click', () => { mistakesFilter = b.dataset.mfilter; render(); }));
  document.getElementById('mistakesFlashcardsBtn')?.addEventListener('click', () => openFlashcardsStudyModal('mistakes'));
  document.getElementById('addMistakeBtn')?.addEventListener('click', () => openMistakeModal());
  document.querySelectorAll('[data-edit-mistake]').forEach(b => b.addEventListener('click', () => openMistakeModal(STORE.mistakes.find(m=>m.id===b.dataset.editMistake))));
  document.querySelectorAll('[data-del-mistake]').forEach(b => b.addEventListener('click', () => {
    if(confirm('Delete mistake?')){ STORE.mistakes = STORE.mistakes.filter(m=>m.id!==b.dataset.delMistake); save(); render(); }
  }));
  document.querySelectorAll('[data-srs-review]').forEach(b => b.addEventListener('click', () => {
    const id = b.dataset.srsReview;
    const m = STORE.mistakes.find(x => x.id === id);
    if(m){
      const currentStage = m.srsStage || 0;
      const nextStage = Math.min(5, currentStage + 1);
      const intervalDays = SRS_INTERVALS[currentStage] || 7;
      m.srsStage = nextStage;
      m.reviewCount = (m.reviewCount || 0) + 1;
      m.lastReviewed = todayStr();
      m.nextReviewDate = addDays(todayStr(), intervalDays);

      playChime('check');
      toast(nextStage >= 5 ? '🎓 Mistake Mastered! Lesson successfully ingrained.' : `🔁 Lesson reviewed! Next SRS review in ${intervalDays} days.`);
      save();
      render();
    }
  }));
}

function openMistakeModal(m){
  const isEdit = !!m;
  openModal(isEdit?'Edit Mistake':'Log Mistake', `
    <div class="form-grid">
      <div class="form-row"><label>Category</label><select id="mCat">${MISTAKE_CATEGORIES.map(c=>`<option ${m&&m.category===c?'selected':''}>${c}</option>`).join('')}</select></div>
      <div class="form-row"><label>Date</label><input type="date" id="mDate" value="${m?m.date:todayStr()}"/></div>
    </div>
    <div class="form-row"><label>What happened?</label><textarea id="mDesc" placeholder="Describe the mistake concisely...">${m?escapeHtml(m.description):''}</textarea></div>
    <div class="form-row"><label>What is the key lesson?</label><textarea id="mLesson" placeholder="Describe what this taught you...">${m?escapeHtml(m.lesson):''}</textarea></div>
    <div class="form-row"><label>Action plan to prevent recurrence</label><input id="mPrev" value="${m?escapeHtml(m.prevention||''):''}" placeholder="Enter action plan to prevent recurrence..."/></div>
    <div class="form-actions"><button type="button" class="btn btn-ghost" id="mCancel">Cancel</button><button type="button" class="btn btn-accent" id="mSave">${isEdit?'Save':'Log Mistake'}</button></div>
  `, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSave')?.addEventListener('click', () => {
      const desc = modal.querySelector('#mDesc').value.trim();
      const lesson = modal.querySelector('#mLesson').value.trim();
      if(!desc || !lesson) return toast('Enter description and lesson');
      const data = {
        category: modal.querySelector('#mCat').value,
        date: modal.querySelector('#mDate').value||todayStr(),
        description: desc,
        lesson,
        prevention: modal.querySelector('#mPrev').value.trim(),
        srsStage: isEdit ? (m.srsStage || 0) : 0,
        nextReviewDate: isEdit ? (m.nextReviewDate || todayStr()) : addDays(todayStr(), 1),
        reviewCount: isEdit ? (m.reviewCount || 0) : 0
      };
      if(isEdit) Object.assign(m, data); else STORE.mistakes.push({ id: uid(), ...data });
      save(); closeModal(); render();
    });
  });
}

/* ==========================================================================
   GOAL MANAGER (WITH SUBTASKS, PROGRESS % & TASK LINKING)
   ========================================================================== */
function renderGoals(){
  const list = STORE.goals.filter(g => g.timeframe === goalsTab);

  const goalsContent = `
    <div class="grid grid-2" style="align-items:start; gap:16px;">
      ${list.length ? list.map(g => {
        const subtasks = g.subtasks || [];
        const hasSubtasks = subtasks.length > 0;
        const doneCount = subtasks.filter(s => s.done).length;
        const pct = hasSubtasks ? Math.round((doneCount / subtasks.length) * 100) : (g.done ? 100 : 0);
        const isCompleted = g.done || (hasSubtasks && doneCount === subtasks.length);

        return `
        <div class="card ${isCompleted ? 'completed' : ''}" style="border-left: 4px solid ${isCompleted ? 'var(--accent)' : 'var(--accent2)'};">
          <div class="flex between align-start">
            <div class="flex items-center gap-8">
              <input type="checkbox" data-toggle-goal="${g.id}" ${isCompleted ? 'checked' : ''} style="accent-color:var(--accent); width:18px; height:18px; cursor:pointer;" />
              <div>
                <div class="item-title" style="font-size:15px; font-weight:700; ${isCompleted ? 'text-decoration:line-through; opacity:0.6;' : ''}">${escapeHtml(g.title)}</div>
                <div class="dim" style="font-size:11.5px; text-transform:capitalize;">${g.timeframe} Goal ${g.deadline ? `· ⏰ Due: ${g.deadline}` : ''}</div>
              </div>
            </div>
            <span class="pill ${isCompleted ? 'pill-accent' : 'pill-dim'}" style="font-weight:700;">${pct}%</span>
          </div>

          <div class="progress-track mt-8" style="height:6px;">
            <div class="progress-fill" style="width:${pct}%; background:${isCompleted ? 'var(--accent)' : 'var(--accent2)'};"></div>
          </div>

          ${g.description ? `<div class="item-body mt-8" style="font-size:13px;">${escapeHtml(g.description)}</div>` : ''}

          <!-- Milestones & Subtasks -->
          ${hasSubtasks ? `
            <div class="mt-10 pt-8" style="border-top:1px solid var(--border-soft);">
              <div class="dim" style="font-size:11.5px; font-weight:600; margin-bottom:6px;">Milestones (${doneCount}/${subtasks.length}):</div>
              <ul class="goal-subtask-list">
                ${subtasks.map(s => `
                  <li class="goal-subtask-item ${s.done ? 'completed' : ''}">
                    <input type="checkbox" data-sub-goal="${g.id}" data-sub-id="${s.id}" ${s.done ? 'checked' : ''} style="accent-color:var(--accent); cursor:pointer;" />
                    <span style="flex:1;">${escapeHtml(s.text)}</span>
                  </li>
                `).join('')}
              </ul>
            </div>
          ` : ''}

          <div class="flex between align-center mt-12 pt-8" style="border-top:1px solid var(--border-soft);">
            <button class="btn btn-xs btn-ghost" data-add-goal-subtask="${g.id}">+ Add Milestone</button>
            <div class="flex gap-6">
              <button class="btn btn-sm btn-ghost" data-edit-goal="${g.id}">✎</button>
              <button class="btn btn-sm btn-ghost" data-del-goal="${g.id}">🗑</button>
            </div>
          </div>
        </div>`;
      }).join('') : `<div class="card" style="grid-column:span 2;"><div class="empty-state"><div class="glyph">🎯</div><div class="msg">No ${goalsTab} goals set yet. Click "+ New Goal" to add one.</div></div></div>`}
    </div>
  `;

  return `
    <div class="section-hero">
      <div>
        <div class="section-badge">Goals &amp; Milestones</div>
        <div class="section-hero-title">Keep short and long range goals in sync with Daily Planner</div>
        <div class="section-pill-row">
          <span class="section-pill">🎯 ${STORE.goals.length} total goals</span>
          <span class="section-pill">✅ ${STORE.goals.filter(g=>g.done).length} completed</span>
        </div>
      </div>
      <button class="btn btn-accent" id="addGoalBtn">+ New Goal</button>
    </div>
    <div class="card" style="margin-bottom:16px;">
      <div class="tabs">
        ${['daily','weekly','monthly','quarterly','journey'].map(t=>`
          <button class="tab ${goalsTab===t?'active':''}" data-gtab="${t}">${t.charAt(0).toUpperCase()+t.slice(1)} (${STORE.goals.filter(g=>g.timeframe===t).length})</button>`).join('')}
      </div>
    </div>

    ${renderCollapsibleSection({
      key: `goals_list_${goalsTab}`,
      title: `${goalsTab.charAt(0).toUpperCase() + goalsTab.slice(1)} Goals &amp; Milestones`,
      icon: '🎯',
      countLabel: `${list.length} goals`,
      defaultExpanded: false,
      contentHtml: goalsContent
    })}
  `;
}

function mountGoals(){
  document.querySelectorAll('[data-gtab]').forEach(b => b.addEventListener('click', () => { goalsTab = b.dataset.gtab; render(); }));
  document.getElementById('addGoalBtn')?.addEventListener('click', () => openGoalModal());
  
  document.querySelectorAll('[data-toggle-goal]').forEach(cb => cb.addEventListener('change', () => {
    const g = STORE.goals.find(x=>x.id===cb.dataset.toggleGoal);
    if(g){
      g.done = cb.checked;
      if(g.subtasks && g.subtasks.length){
        g.subtasks.forEach(s => s.done = cb.checked);
      }
      save(); render();
    }
  }));

  document.querySelectorAll('[data-sub-goal]').forEach(cb => cb.addEventListener('change', () => {
    const gid = cb.dataset.subGoal;
    const sid = cb.dataset.subId;
    const g = STORE.goals.find(x => x.id === gid);
    if(g && g.subtasks){
      const s = g.subtasks.find(x => x.id === sid);
      if(s){
        s.done = cb.checked;
        const allDone = g.subtasks.every(x => x.done);
        g.done = allDone;
        save(); render();
      }
    }
  }));

  document.querySelectorAll('[data-add-goal-subtask]').forEach(btn => {
    btn.addEventListener('click', () => {
      const gid = btn.dataset.addGoalSubtask;
      const g = STORE.goals.find(x => x.id === gid);
      if(!g) return;
      const text = prompt(`Add a milestone/subtask for "${g.title}":`);
      if(text && text.trim()){
        if(!Array.isArray(g.subtasks)) g.subtasks = [];
        g.subtasks.push({ id: uid(), text: text.trim(), done: false });
        g.done = false;
        save(); render();
        toast('🎯 Milestone added to goal!');
      }
    });
  });

  document.querySelectorAll('[data-edit-goal]').forEach(b => b.addEventListener('click', () => openGoalModal(STORE.goals.find(g=>g.id===b.dataset.editGoal))));
  document.querySelectorAll('[data-del-goal]').forEach(b => b.addEventListener('click', () => {
    if(confirm('Delete goal?')){ STORE.goals = STORE.goals.filter(g=>g.id!==b.dataset.delGoal); save(); render(); }
  }));
}

function openGoalModal(g){
  const isEdit = !!g;
  openModal(isEdit?'Edit Goal':'New Goal', `
    <div class="form-row"><label>Goal Title *</label><input id="gTitle" value="${g?escapeHtml(g.title):''}" placeholder="Enter your goal" autofocus/></div>
    <div class="form-grid">
      <div class="form-row"><label>Timeframe</label>
        <select id="gTimeframe">${['daily','weekly','monthly','quarterly','journey'].map(t=>`<option value="${t}" ${((g?g.timeframe:goalsTab)===t)?'selected':''}>${t.toUpperCase()}</option>`).join('')}</select>
      </div>
      <div class="form-row"><label>Target Deadline</label><input type="date" id="gDeadline" value="${g?g.deadline||'':''}"/></div>
    </div>
    <div class="form-row"><label>Description &amp; Why It Matters</label><textarea id="gDesc" placeholder="Describe why this goal is important for your cycle...">${g?escapeHtml(g.description||''):''}</textarea></div>
    <div class="form-actions"><button type="button" class="btn btn-ghost" id="mCancel">Cancel</button><button type="button" class="btn btn-accent" id="mSave">${isEdit?'Save':'Add Goal'}</button></div>
  `, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSave')?.addEventListener('click', () => {
      const title = modal.querySelector('#gTitle').value.trim();
      if(!title) return toast('Enter a goal title');
      const data = { title, timeframe: modal.querySelector('#gTimeframe').value, deadline: modal.querySelector('#gDeadline').value, description: modal.querySelector('#gDesc').value.trim() };
      if(isEdit) Object.assign(g, data);
      else STORE.goals.push({ id: uid(), done:false, subtasks: [], ...data });
      save(); closeModal(); render();
    });
  });
}

/* ==========================================================================
   NOTES (TAG FILTER CHIPS, SEARCH & FLASHCARD GENERATOR)
   ========================================================================== */
let notesTagFilter = 'all';

function renderNotes(){
  let list = STORE.notes;

  // Extract all unique tags
  const allTags = new Set();
  (STORE.notes || []).forEach(n => {
    if(n.tags){
      n.tags.split(',').forEach(t => {
        const clean = t.trim().toLowerCase();
        if(clean) allTags.add(clean);
      });
    }
  });

  if(notesSearch.trim()){
    const q = notesSearch.toLowerCase();
    list = list.filter(n => n.title.toLowerCase().includes(q) || n.content.toLowerCase().includes(q) || (n.tags||'').toLowerCase().includes(q));
  }

  if(notesTagFilter !== 'all'){
    list = list.filter(n => (n.tags||'').toLowerCase().includes(notesTagFilter));
  }

  const sorted = [...list].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));

  const notesContent = `
    <div class="grid grid-3" style="gap:16px;">
      ${sorted.length ? sorted.map(n => `
        <div class="card" style="display:flex; flex-direction:column; justify-content:space-between;">
          <div>
            <div class="item-title" style="font-weight:700; font-size:15px;">${escapeHtml(n.title)}</div>
            <div class="dim mono" style="font-size:11px; margin-top:2px;">Updated ${n.updatedAt.slice(0,10)}</div>
            <div class="item-body mt-8" style="font-size:13px; line-height:1.5;">${mdLite(escapeHtml(n.content.length > 220 ? n.content.slice(0,220)+'…' : n.content))}</div>
            ${n.tags ? `<div class="item-tags mt-8 flex gap-4 wrap">${n.tags.split(',').map(t=>`<span class="pill pill-dim" style="font-size:10.5px;">#${escapeHtml(t.trim())}</span>`).join('')}</div>` : ''}
          </div>
          <div class="flex gap-8 mt-12 pt-8" style="border-top:1px solid var(--border-soft);">
            <button class="btn btn-sm btn-ghost" data-edit-note="${n.id}" style="margin-left:auto;">✎ Edit</button>
            <button class="btn btn-sm btn-ghost" data-del-note="${n.id}">🗑</button>
          </div>
        </div>`).join('') : `<div class="card" style="grid-column:span 3;"><div class="empty-state"><div class="glyph">💡</div><div class="msg">No notes found for this filter. Create one to capture ideas.</div></div></div>`}
    </div>
  `;

  return `
    <div class="section-hero">
      <div>
        <div class="section-badge">Knowledge Base &amp; Notes</div>
        <div class="section-hero-title">Your lightweight second brain &amp; study cards</div>
        <div class="section-pill-row">
          <span class="section-pill">📝 ${STORE.notes.length} notes</span>
        </div>
      </div>
      <div class="flex gap-8 wrap">
        <button class="btn btn-ghost" id="notesStudyModeBtn">🎴 Study with Flashcards</button>
        <button class="btn btn-accent" id="addNoteBtn">+ New Note</button>
      </div>
    </div>

    <!-- Tag Filter Bar & Search -->
    <div class="card mb-16" style="padding:12px 16px;">
      <div class="flex between items-center wrap gap-10">
        <div class="flex gap-6 items-center wrap">
          <span class="dim" style="font-size:12px; font-weight:700;">Tag:</span>
          <button class="btn btn-xs ${notesTagFilter==='all'?'btn-accent':'btn-ghost'}" data-nfilter="all">All Notes</button>
          ${Array.from(allTags).slice(0, 8).map(tag => `
            <button class="btn btn-xs ${notesTagFilter===tag?'btn-accent':'btn-ghost'}" data-nfilter="${escapeHtml(tag)}">#${escapeHtml(tag)}</button>
          `).join('')}
        </div>
        <input class="tasklog-search" id="notesSearchInput" placeholder="🔍 Search title, content, tags…" value="${escapeHtml(notesSearch)}" style="padding:6px 12px; font-size:13px; min-width:240px; border-radius:8px; border:1px solid var(--border); background:var(--bg-3); color:var(--text);"/>
      </div>
    </div>

    ${renderCollapsibleSection({
      key: 'notes_list',
      title: 'Knowledge Base &amp; Saved Notes',
      icon: '📝',
      countLabel: `${sorted.length} notes`,
      defaultExpanded: false,
      contentHtml: notesContent
    })}
  `;
}

function mountNotes(){
  const searchEl = document.getElementById('notesSearchInput');
  if(searchEl){
    searchEl.addEventListener('input', e => { notesSearch = e.target.value; render(); });
  }

  document.querySelectorAll('[data-nfilter]').forEach(btn => {
    btn.addEventListener('click', () => { notesTagFilter = btn.dataset.nfilter; render(); });
  });

  document.getElementById('notesStudyModeBtn')?.addEventListener('click', () => openFlashcardsStudyModal('notes'));
  document.getElementById('addNoteBtn')?.addEventListener('click', () => openNoteModal());
  document.querySelectorAll('[data-edit-note]').forEach(b => b.addEventListener('click', () => openNoteModal(STORE.notes.find(n=>n.id===b.dataset.editNote))));
  document.querySelectorAll('[data-del-note]').forEach(b => b.addEventListener('click', () => {
    if(confirm('Delete note?')){ STORE.notes = STORE.notes.filter(n=>n.id!==b.dataset.delNote); save(); render(); }
  }));
}

function openNoteModal(n){
  const isEdit = !!n;
  openModal(isEdit?'Edit Note':'New Note', `
    <div class="form-row"><label>Note Title *</label><input id="nTitle" value="${n?escapeHtml(n.title):''}" placeholder="Enter note title" autofocus/></div>
    <div class="form-row"><label>Tags (comma separated)</label><input id="nTags" value="${n?escapeHtml(n.tags||''):''}" placeholder="Enter tags (comma separated)"/></div>
    <div class="form-row"><label>Content (supports **bold**, *italic*, \`code\`)</label><textarea id="nContent" class="notes-textarea form-input" placeholder="Write your notes, formulas, code patterns or key takeaways...">${n?escapeHtml(n.content):''}</textarea></div>
    <div class="form-actions"><button type="button" class="btn btn-ghost" id="mCancel">Cancel</button><button type="button" class="btn btn-accent" id="mSave">${isEdit?'Save':'Create Note'}</button></div>
  `, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSave')?.addEventListener('click', () => {
      const title = modal.querySelector('#nTitle').value.trim();
      const content = modal.querySelector('#nContent').value.trim();
      if(!title) return toast('Enter a note title');
      const data = { title, content, tags: modal.querySelector('#nTags').value.trim(), updatedAt: todayStr() };
      if(isEdit) Object.assign(n, data); else STORE.notes.push({ id: uid(), ...data });
      save(); closeModal(); render();
    });
  });
}

function addHistoryEntry(category, action, description, metadata = {}){
  if(!Array.isArray(STORE.history)) STORE.history = [];
  STORE.history.unshift({
    id: uid(),
    category,
    action,
    description,
    timestamp: new Date().toISOString(),
    metadata
  });
  save();
}

let dojoTab = 'targets';
let dojoFilter = 'all';
let dojoSearch = '';

/* ==========================================================================
   DOJO TRACKER
   ========================================================================== */
// --- CONTEST TRACKER --- //
let contestFilter = 'All';
let contestPlatformFilter = 'All';

function getContestStats() {
  const contests = STORE.contests?.entries || [];
  const completed = contests.filter(c => c.status === 'Completed');
  return {
    total: contests.length,
    completed: completed.length,
    upcoming: contests.filter(c => c.status === 'Upcoming').length,
    problemsSolved: completed.reduce((sum, c) => sum + (Number(c.problemsSolved) || 0), 0),
    problemsAttempted: completed.reduce((sum, c) => sum + (Number(c.problemsAttempted) || 0), 0),
    bestRank: completed.reduce((best, c) => {
      const r = Number(c.rank);
      if(!r) return best;
      return (best === null || r < best) ? r : best;
    }, null)
  };
}

function renderContests() {
  if(!STORE.settings) STORE.settings = {};
  const isKalvium = Boolean(STORE.settings.isKalviumStudent);

  const toggleBarHtml = `
    <div class="card" style="margin-bottom:16px; background:linear-gradient(135deg, rgba(79,140,255,0.06), rgba(192,132,252,0.06)); border:1px solid var(--border-soft); padding:12px 16px;">
      <div class="flex flex-between items-center wrap gap-12">
        <div class="flex items-center gap-10">
          <input type="checkbox" id="chkKalviumStudent" ${isKalvium ? 'checked' : ''} style="cursor:pointer; width:18px; height:18px; accent-color:var(--accent);" />
          <label for="chkKalviumStudent" style="cursor:pointer; font-weight:700; font-size:14px; color:var(--text-bright); display:flex; align-items:center; gap:6px;">
            🎓 I am a Kalvium student <span class="pill pill-accent" style="font-size:10.5px; padding:2px 6px;">${isKalvium ? 'Dojo Mode Active' : 'Enable Dojo Tracker'}</span>
          </label>
        </div>
        <div class="dim" style="font-size:12px;">
          ${isKalvium ? 'Switch to normal multi-platform contests by unchecking' : 'Check to view 10-Belt progression, active targets & problem solving tasks'}
        </div>
      </div>
    </div>
  `;

  if(isKalvium) {
    return toggleBarHtml + renderDojo();
  }

  const stats = getContestStats();
  const contests = STORE.contests?.entries || [];
  
  return `
    ${toggleBarHtml}
    <div class="section-hero">
      <div>
        <div class="section-badge">Contest Tracker</div>
        <div class="section-hero-title">Track your competitive programming journey across all platforms</div>
        <div class="section-pill-row">
          <span class="section-pill">🏆 ${stats.total} Total Contests</span>
          <span class="section-pill">🔥 ${stats.problemsSolved} Problems Solved</span>
          <span class="section-pill">⭐ Best Rank: ${stats.bestRank || 'N/A'}</span>
        </div>
      </div>
      <button class="btn btn-accent" id="btnNewContest" style="padding:12px 24px; font-size:15px; box-shadow:0 4px 15px var(--accent-glow);">+ Log Contest</button>
    </div>

    <div class="card" style="margin-bottom:16px;">
      <div class="flex flex-between items-center wrap gap-12">
        <div class="flex gap-8 wrap items-center">
          <button class="btn btn-sm ${contestFilter==='All'?'btn-accent':'btn-ghost'}" id="filterContAll">All</button>
          <button class="btn btn-sm ${contestFilter==='Upcoming'?'btn-accent':'btn-ghost'}" id="filterContUp">Upcoming</button>
          <button class="btn btn-sm ${contestFilter==='Completed'?'btn-accent':'btn-ghost'}" id="filterContDone">Completed</button>
        </div>
        <div class="flex gap-8 items-center">
          <select id="contestPlatformSelect" class="form-input" style="padding:4px 8px; width:140px;">
            <option value="All" ${contestPlatformFilter==='All'?'selected':''}>All Platforms</option>
            <option value="LeetCode" ${contestPlatformFilter==='LeetCode'?'selected':''}>LeetCode</option>
            <option value="Codeforces" ${contestPlatformFilter==='Codeforces'?'selected':''}>Codeforces</option>
            <option value="CodeChef" ${contestPlatformFilter==='CodeChef'?'selected':''}>CodeChef</option>
            <option value="AtCoder" ${contestPlatformFilter==='AtCoder'?'selected':''}>AtCoder</option>
            <option value="HackerRank" ${contestPlatformFilter==='HackerRank'?'selected':''}>HackerRank</option>
            <option value="GFG" ${contestPlatformFilter==='GFG'?'selected':''}>GeeksforGeeks</option>
            <option value="Other" ${contestPlatformFilter==='Other'?'selected':''}>Other</option>
          </select>
        </div>
      </div>
    </div>

    <div class="grid grid-2" style="gap:16px;">
      ${renderContestList(contests)}
    </div>
  `;
}

function renderContestList(contests) {
  let filtered = [...contests];
  if(contestFilter !== 'All') {
    filtered = filtered.filter(c => c.status === contestFilter);
  }
  if(contestPlatformFilter !== 'All') {
    filtered = filtered.filter(c => (c.platform || '').toLowerCase() === contestPlatformFilter.toLowerCase());
  }

  if(filtered.length === 0) {
    return `
      <div class="empty-state card" style="grid-column:1/-1; padding:32px; text-align:center;">
        <div style="font-size:36px; margin-bottom:8px;">⚔️</div>
        <div class="msg" style="font-size:15px; font-weight:600; color:var(--text-bright); margin-bottom:4px;">No Contests Found</div>
        <div class="dim" style="font-size:13px; margin-bottom:16px;">${contests.length === 0 ? 'Start tracking your competitive programming ratings and problem counts.' : 'No contests match the selected filter criteria.'}</div>
        <button class="btn btn-accent btn-sm" onclick="openContestModal()">+ Log First Contest</button>
      </div>
    `;
  }

  return filtered.map(c => renderContestCard(c)).join('');
}

function renderContestCard(contest) {
  const isDone = contest.status === 'Completed';
  const isLive = contest.status === 'Live' || contest.status === 'Ongoing / Live';
  const solved = Number(contest.problemsSolved) || 0;
  const attempted = Number(contest.problemsAttempted) || 0;
  const target = Number(contest.targetProblems) || 0;
  const rank = contest.rank ? `#${Number(contest.rank).toLocaleString()}` : '—';
  const ratingDelta = contest.ratingDelta !== undefined && contest.ratingDelta !== null && contest.ratingDelta !== '' ? Number(contest.ratingDelta) : null;
  const borderCol = isLive ? 'var(--danger)' : isDone ? 'var(--accent)' : 'var(--accent2)';

  return `
    <div class="card" style="border-left:4px solid ${borderCol}; display:flex; flex-direction:column; justify-content:space-between;">
      <div>
        <div class="flex flex-between items-center mb-10">
          <div class="flex items-center gap-8 wrap">
            <span class="pill ${isLive ? 'pill-danger' : isDone ? 'pill-accent' : 'pill-accent2'}" style="font-weight:700;">${escapeHtml(contest.platform || 'Contest')}</span>
            ${contest.difficulty && contest.difficulty !== 'Mixed' ? `<span class="pill pill-dim" style="font-size:10px;">${escapeHtml(contest.difficulty)}</span>` : ''}
            <strong style="color:var(--text-bright); font-size:15px;">${escapeHtml(contest.name || 'Untitled Contest')}</strong>
          </div>
          <div class="flex gap-4">
            ${contest.url ? `<a href="${escapeHtml(contest.url)}" target="_blank" class="btn btn-sm btn-ghost" title="Open Contest URL" style="text-decoration:none;">🔗</a>` : ''}
            <button class="btn btn-sm btn-ghost" data-edit-contest="${contest.id}" title="Edit Contest">✏️</button>
            <button class="btn btn-sm btn-ghost" data-del-contest="${contest.id}" title="Delete Contest">🗑️</button>
          </div>
        </div>

        <div class="grid grid-3" style="gap:8px; margin-bottom:12px; font-size:12px;">
          <div class="dim">Date: <strong class="text-bright">${contest.date || 'TBD'} ${contest.startTime ? `<span class="notif-time-badge" style="font-size:10px; padding:1px 4px;">${contest.startTime}</span>` : ''}</strong></div>
          <div class="dim">Status: <span class="badge ${isLive ? 'badge-danger' : isDone ? 'badge-accent' : 'badge-dim'}" style="font-size:10.5px; font-weight:700;">${escapeHtml(contest.status || 'Upcoming')}</span></div>
          <div class="dim">Rank: <strong class="accent" style="font-family:var(--font-mono);">${rank}</strong></div>
        </div>

        <div class="flex flex-between items-center wrap gap-8 mb-10" style="background:var(--bg-2); padding:8px 12px; border-radius:8px; border:1px solid var(--border-soft); font-size:12px;">
          <div>
            <span class="dim">Solved:</span>
            <strong style="color:var(--accent); font-family:var(--font-mono); margin-left:4px;">
              ${solved}${attempted ? ` (att: ${attempted})` : ''}${target ? ` / tgt: ${target}` : ''}
            </strong>
          </div>
          ${contest.ratingAfter ? `
            <div>
              <span class="dim">Rating:</span>
              <strong style="font-family:var(--font-mono); margin-left:4px; color:var(--text-bright);">${contest.ratingAfter}</strong>
              ${ratingDelta !== null ? `
                <span style="font-size:11px; font-weight:700; color:${ratingDelta >= 0 ? '#4ade80' : '#ef4444'}; margin-left:2px;">
                  (${ratingDelta >= 0 ? '+' : ''}${ratingDelta})
                </span>
              ` : ''}
            </div>
          ` : ''}
          ${contest.score ? `
            <div>
              <span class="dim">Score:</span>
              <strong style="font-family:var(--font-mono); color:var(--accent2); margin-left:4px;">${contest.score} pts</strong>
            </div>
          ` : ''}
        </div>
      </div>

      ${contest.lessons ? `
        <div class="dim mt-8" style="font-size:11.5px; line-height:1.4; background:var(--glass); padding:6px 10px; border-radius:6px; border-left:2px solid var(--border);">
          💡 <em>${escapeHtml(contest.lessons)}</em>
        </div>
      ` : ''}
    </div>
  `;
}

function renderDojo(){
  if(!STORE.dojo) {
    STORE.dojo = {
      belts: [
        { number: 1, name: 'White Belt', badge: 'White Ninja', topics: 'Basics, Variables, Conditionals, Loops', problemsRequired: 10, completed: true },
        { number: 2, name: 'Yellow Belt', badge: 'Yellow Ninja', topics: 'Arrays, Strings, Simple Math', problemsRequired: 20, completed: false },
        { number: 3, name: 'Orange Belt', badge: 'Orange Ninja', topics: 'Functions, Recursion Basics', problemsRequired: 30, completed: false },
        { number: 4, name: 'Green Belt', badge: 'Green Ninja', topics: 'Searching, Sorting, Hash Maps', problemsRequired: 40, completed: false },
        { number: 5, name: 'Blue Belt', badge: 'Blue Ninja', topics: 'Stack, Queue, Two Pointers', problemsRequired: 50, completed: false },
        { number: 6, name: 'Purple Belt', badge: 'Purple Ninja', topics: 'Linked Lists, Bit Manipulation', problemsRequired: 60, completed: false },
        { number: 7, name: 'Brown Belt', badge: 'Brown Ninja', topics: 'Binary Trees, BST, Heaps', problemsRequired: 70, completed: false },
        { number: 8, name: 'Red Belt', badge: 'Red Ninja', topics: 'Graphs (BFS, DFS), Greedy', problemsRequired: 80, completed: false },
        { number: 9, name: 'Black Belt', badge: 'Black Master', topics: 'Dynamic Programming, Tries', problemsRequired: 100, completed: false },
        { number: 10, name: 'Grandmaster Belt', badge: 'Dojo Legend', topics: 'Advanced DP, Segment Trees, Hard Graphs', problemsRequired: 150, completed: false }
      ],
      beltTargets: [],
      attempts: [],
      codingTasks: []
    };
    save();
  }

  const dojo = STORE.dojo;
  const belts = dojo.belts || [];
  const beltTargets = dojo.beltTargets || [];
  const attempts = dojo.attempts || [];
  const tasks = dojo.codingTasks || [];
  const historyEntries = (STORE.history || []).filter(h => h.category === 'dojo');

  const totalTargets = beltTargets.length + attempts.length;
  const completedBelts = belts.filter(b => b.completed).length;
  const completedTasks = tasks.filter(t => t.status === 'Completed').length;

  return `
    <div class="section-hero">
      <div>
        <div class="section-badge">Dojo Command Center</div>
        <div class="section-hero-title">Level up problem solving, targets, and belt progression</div>
        <div class="section-pill-row">
          <span class="section-pill">🎯 ${totalTargets} Active Targets</span>
          <span class="section-pill">🥋 ${completedBelts}/${belts.length} Belts Unlocked</span>
          <span class="section-pill">📋 ${completedTasks}/${tasks.length} Tasks Done</span>
        </div>
      </div>
    </div>

    <div class="tabs flex gap-8 mb-16 wrap" style="border-bottom:1px solid var(--border-soft); padding-bottom:8px;">
      <button class="btn btn-sm ${dojoTab === 'targets' ? 'btn-accent' : 'btn-ghost'}" id="tabDojoTargets">🎯 Targets Dashboard</button>
      <button class="btn btn-sm ${dojoTab === 'belts' ? 'btn-accent' : 'btn-ghost'}" id="tabDojoBelts">🥋 Belt Progression (10 Belts)</button>
      <button class="btn btn-sm ${dojoTab === 'tasks' ? 'btn-accent' : 'btn-ghost'}" id="tabDojoTasks">📋 Coding Tasks (${tasks.length})</button>
      <button class="btn btn-sm ${dojoTab === 'history' ? 'btn-accent' : 'btn-ghost'}" id="tabDojoHistory">📜 Dojo History (${historyEntries.length})</button>
    </div>

    <div class="dojo-tab-container">
      ${dojoTab === 'targets' ? renderDojoTargetsTab(beltTargets, attempts, tasks)
        : dojoTab === 'belts' ? renderDojoBeltsTab(belts)
        : dojoTab === 'tasks' ? renderDojoTasksTab(tasks, beltTargets, attempts)
        : renderDojoHistoryTab(historyEntries)}
    </div>
  `;
}

function renderDojoTargetsTab(beltTargets, attempts, tasks){
  return `
    <div class="flex flex-between items-center wrap gap-8 mb-16">
      <div style="font-size: 16px; font-weight: 700; color: var(--text-bright);">Active Learning Targets</div>
      <div class="flex gap-8">
        <button class="btn btn-accent btn-sm" id="btnNewBeltTarget">+ New Belt Target</button>
        <button class="btn btn-accent2 btn-sm" id="btnNewAttemptTarget">+ New Attempt Target</button>
      </div>
    </div>

    <!-- Belt Targets Section -->
    <div class="card mb-16">
      <div class="card-title">Belt Level Targets</div>
      ${beltTargets.length === 0 ? `
        <div class="empty-state" style="padding:20px;">
          <div class="msg">No Belt Targets created yet. Click "+ New Belt Target" to set one.</div>
        </div>
      ` : `
        <div class="grid grid-2" style="gap:16px;">
          ${beltTargets.map(t => {
            const probPct = Math.round(clamp(((t.problemsSolved || 0) / (t.targetProblems || 1)) * 100, 0, 100));
            const beltsPct = Math.round(clamp(((t.beltsAchieved || 0) / (t.beltsTarget || 1)) * 100, 0, 100));
            const remProblems = Math.max(0, (t.targetProblems || 0) - (t.problemsSolved || 0));
            const remBelts = Math.max(0, (t.beltsTarget || 0) - (t.beltsAchieved || 0));
            return `
              <div class="card" style="background:var(--bg-2); border:1px solid var(--border-soft); padding:16px;">
                <div class="flex flex-between items-center mb-8">
                  <span class="pill pill-accent">${escapeHtml(t.language || 'General')}</span>
                  <span class="dim mono" style="font-size:12px;">Target: ${t.targetDate || 'No date'}</span>
                </div>
                <div style="font-size:16px; font-weight:700; color:var(--text-bright); margin-bottom:4px;">
                  ${t.currentBelt || 'White'} → ${t.targetBelt || 'Black'}
                </div>
                <div class="dim" style="font-size:12px; margin-bottom:12px;">
                  Topics: ${escapeHtml(t.topics || 'N/A')}
                </div>

                <div style="margin-bottom:10px;">
                  <div class="flex flex-between" style="font-size:12px; margin-bottom:4px;">
                    <span>Problems Solved</span>
                    <span class="mono font-bold">${t.problemsSolved || 0} / ${t.targetProblems || 0} (${probPct}%)</span>
                  </div>
                  <div class="progress-track" style="height:6px;"><div class="progress-fill" style="width:${probPct}%;"></div></div>
                  <div class="dim" style="font-size:11px; margin-top:3px;">Remaining: ${remProblems} problems</div>
                </div>

                <div style="margin-bottom:12px;">
                  <div class="flex flex-between" style="font-size:12px; margin-bottom:4px;">
                    <span>Belts Achieved</span>
                    <span class="mono font-bold">${t.beltsAchieved || 0} / ${t.beltsTarget || 0} (${beltsPct}%)</span>
                  </div>
                  <div class="progress-track" style="height:6px;"><div class="progress-fill" style="width:${beltsPct}%; background:var(--accent2);"></div></div>
                  <div class="dim" style="font-size:11px; margin-top:3px;">Remaining: ${remBelts} belts</div>
                </div>

                ${t.notes ? `<div class="dim" style="font-size:12px; font-style:italic; margin-bottom:12px;">"${escapeHtml(t.notes)}"</div>` : ''}

                <div class="flex gap-6 wrap" style="margin-top:12px; border-top:1px solid var(--border-soft); padding-top:10px;">
                  <button class="btn btn-sm btn-accent" data-progress-target="${t.id}">+ Log Progress</button>
                  <button class="btn btn-sm btn-ghost" data-add-task-target="${t.id}">+ Add Task</button>
                  <button class="btn btn-sm btn-ghost" data-edit-target="${t.id}">✏️ Edit</button>
                  <button class="btn btn-sm btn-ghost" data-delete-target="${t.id}">🗑️</button>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      `}
    </div>

    <!-- Attempt Targets Section -->
    <div class="card">
      <div class="card-title">Coding Attempt & Problem Targets</div>
      ${attempts.length === 0 ? `
        <div class="empty-state" style="padding:20px;">
          <div class="msg">No Attempt Targets created yet. Click "+ New Attempt Target" to set one.</div>
        </div>
      ` : `
        <div class="grid grid-2" style="gap:16px;">
          ${attempts.map(a => {
            const pct = Math.round(clamp(((a.attempted || 0) / (a.targetProblems || 1)) * 100, 0, 100));
            const rem = Math.max(0, (a.targetProblems || 0) - (a.attempted || 0));
            return `
              <div class="card" style="background:var(--bg-2); border:1px solid var(--border-soft); padding:16px;">
                <div class="flex flex-between items-center mb-8">
                  <span class="pill pill-accent2">${escapeHtml(a.platform || 'Platform')}</span>
                  <span class="dim mono" style="font-size:12px;">Target: ${a.targetDate || 'No date'}</span>
                </div>
                <div style="font-size:16px; font-weight:700; color:var(--text-bright); margin-bottom:4px;">
                  ${escapeHtml(a.language || 'Any')} • ${escapeHtml(a.difficulty || 'All Levels')}
                </div>
                <div class="dim" style="font-size:12px; margin-bottom:12px;">
                  Topics: ${escapeHtml(a.topics || 'N/A')}
                </div>

                <div style="margin-bottom:12px;">
                  <div class="flex flex-between" style="font-size:12px; margin-bottom:4px;">
                    <span>Attempts & Solved Count</span>
                    <span class="mono font-bold">${a.attempted || 0} / ${a.targetProblems || 0} (${pct}%)</span>
                  </div>
                  <div class="progress-track" style="height:6px;"><div class="progress-fill" style="width:${pct}%; background:var(--accent3);"></div></div>
                  <div class="dim" style="font-size:11px; margin-top:3px;">Remaining: ${rem} problems</div>
                </div>

                ${a.notes ? `<div class="dim" style="font-size:12px; font-style:italic; margin-bottom:12px;">"${escapeHtml(a.notes)}"</div>` : ''}

                <div class="flex gap-6 wrap" style="margin-top:12px; border-top:1px solid var(--border-soft); padding-top:10px;">
                  <button class="btn btn-sm btn-accent2" data-progress-attempt="${a.id}">+ Increment</button>
                  <button class="btn btn-sm btn-ghost" data-add-task-attempt="${a.id}">+ Add Task</button>
                  <button class="btn btn-sm btn-ghost" data-edit-attempt="${a.id}">✏️ Edit</button>
                  <button class="btn btn-sm btn-ghost" data-delete-attempt="${a.id}">🗑️</button>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      `}
    </div>
  `;
}

function renderDojoBeltsTab(belts){
  return `
    <div class="card">
      <div class="flex flex-between items-center mb-16">
        <div class="card-title" style="margin:0;">🥋 10-Belt System Progression</div>
        <div class="dim" style="font-size:13px;">Unlocked: <strong class="text-bright">${belts.filter(b=>b.completed).length} / ${belts.length}</strong></div>
      </div>
      <div class="grid grid-2" style="gap:16px;">
        ${belts.map(b => `
          <div class="card ${b.completed?'completed':''}" style="background:${b.completed?'var(--bg-2)':'var(--glass)'}; border:1px solid ${b.completed?'var(--accent)':'var(--border-soft)'}; padding:16px;">
            <div class="flex flex-between items-center mb-8">
              <div class="flex items-center gap-8">
                <span style="width:26px; height:26px; border-radius:50%; display:inline-flex; align-items:center; justify-content:center; background:${b.completed?'var(--accent)':'var(--bg-3)'}; color:${b.completed?'#fff':'var(--text-dim)'}; font-weight:800; font-size:12px;">${b.number || '1'}</span>
                <span style="font-weight:700; font-size:15px; color:var(--text-bright);">${escapeHtml(b.name)}</span>
              </div>
              <span class="pill ${b.completed?'pill-accent':'pill-dim'}">${b.completed?'Unlocked':'Locked'}</span>
            </div>
            <div class="dim" style="font-size:12px; margin-bottom:4px;">Badge: <strong class="text-bright">${escapeHtml(b.badge || 'N/A')}</strong></div>
            <div class="dim" style="font-size:12px; margin-bottom:4px;">Topics: ${escapeHtml(b.topics || 'N/A')}</div>
            <div class="dim" style="font-size:12px; margin-bottom:12px;">Required Problems: <strong class="mono text-bright">${b.problemsRequired || 10}</strong></div>
            
            <div class="flex gap-8" style="border-top:1px solid var(--border-soft); padding-top:10px;">
              <button class="btn btn-sm ${b.completed?'btn-ghost':'btn-accent'}" data-toggle-belt-id="${b.number}">${b.completed?'Mark Locked':'Mark Completed'}</button>
              <button class="btn btn-sm btn-ghost" data-edit-belt-id="${b.number}">✎ Configure</button>
            </div>
          </div>
        `).join('')}
      </div>
    </div>
  `;
}

function renderDojoTasksTab(tasks, beltTargets, attempts){
  let filtered = tasks;
  if(dojoFilter !== 'all'){
    filtered = filtered.filter(t => t.status === dojoFilter);
  }
  if(dojoSearch.trim()){
    const q = dojoSearch.toLowerCase();
    filtered = filtered.filter(t => (t.title && t.title.toLowerCase().includes(q)) || (t.topic && t.topic.toLowerCase().includes(q)) || (t.language && t.language.toLowerCase().includes(q)));
  }

  return `
    <div class="card">
      <div class="flex flex-between items-center wrap gap-12 mb-16">
        <div class="flex gap-8 wrap items-center">
          <button class="btn btn-sm ${dojoFilter==='all'?'btn-accent':'btn-ghost'}" id="filterTaskAll">All (${tasks.length})</button>
          <button class="btn btn-sm ${dojoFilter==='In Progress'?'btn-accent':'btn-ghost'}" id="filterTaskProg">In Progress (${tasks.filter(t=>t.status==='In Progress').length})</button>
          <button class="btn btn-sm ${dojoFilter==='Completed'?'btn-accent':'btn-ghost'}" id="filterTaskDone">Completed (${tasks.filter(t=>t.status==='Completed').length})</button>
          <button class="btn btn-sm ${dojoFilter==='Not Started'?'btn-accent':'btn-ghost'}" id="filterTaskNot">Not Started (${tasks.filter(t=>t.status==='Not Started').length})</button>
        </div>
        <div class="flex gap-8 items-center">
          <input type="text" id="dojoTaskSearchInput" placeholder="Search tasks..." value="${escapeHtml(dojoSearch)}" style="width:180px; padding:6px 10px; font-size:12px;" />
          <button class="btn btn-accent btn-sm" id="btnNewCodingTask">+ Add Task</button>
        </div>
      </div>

      ${filtered.length === 0 ? `
        <div class="empty-state" style="padding:24px;">
          <div class="msg">No coding tasks found.</div>
        </div>
      ` : `
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Status</th>
                <th>Task Title</th>
                <th>Language / Platform</th>
                <th>Topic & Difficulty</th>
                <th>Target Date</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              ${filtered.map(t => `
                <tr>
                  <td>
                    <select class="task-status-select" data-task-id="${t.id}" style="padding:4px 8px; font-size:12px; border-radius:4px; background:var(--bg-input); color:var(--text-bright);">
                      <option value="Not Started" ${t.status==='Not Started'?'selected':''}>Not Started</option>
                      <option value="In Progress" ${t.status==='In Progress'?'selected':''}>In Progress</option>
                      <option value="Completed" ${t.status==='Completed'?'selected':''}>Completed</option>
                    </select>
                  </td>
                  <td>
                    <div style="font-weight:600; color:var(--text-bright); ${t.status==='Completed'?'text-decoration:line-through; opacity:0.7;':''}">${escapeHtml(t.title)}</div>
                    ${t.notes ? `<div class="dim" style="font-size:11px;">${escapeHtml(t.notes)}</div>` : ''}
                  </td>
                  <td>
                    <span class="pill pill-accent" style="font-size:11px;">${escapeHtml(t.language || 'Any')}</span>
                    ${t.platform ? `<span class="pill pill-accent2" style="font-size:11px;">${escapeHtml(t.platform)}</span>` : ''}
                  </td>
                  <td>
                    <div style="font-size:12px;">${escapeHtml(t.topic || 'General')}</div>
                    <div class="dim" style="font-size:11px;">${escapeHtml(t.difficulty || 'Medium')}</div>
                  </td>
                  <td class="mono" style="font-size:12px;">${t.targetDate || '-'}</td>
                  <td>
                    <div class="flex gap-4">
                      <button class="btn btn-xs btn-ghost" data-edit-task="${t.id}">✏️</button>
                      <button class="btn btn-xs btn-ghost" data-delete-task="${t.id}">🗑️</button>
                    </div>
                  </td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `}
    </div>
  `;
}

function renderDojoHistoryTab(historyEntries){
  return `
    <div class="card">
      <div class="card-title">📜 Dojo Activity & History Log</div>
      ${historyEntries.length === 0 ? `
        <div class="empty-state" style="padding:24px;">
          <div class="msg">No Dojo history entries logged yet. Complete tasks or update targets to populate history!</div>
        </div>
      ` : `
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Date & Time</th>
                <th>Action</th>
                <th>Description</th>
              </tr>
            </thead>
            <tbody>
              ${historyEntries.map(h => `
                <tr>
                  <td class="mono" style="font-size:12px;">${fmtTime(h.timestamp)}</td>
                  <td><span class="pill pill-accent" style="font-size:11px;">${escapeHtml(h.action || 'Dojo')}</span></td>
                  <td style="font-size:13px; color:var(--text-bright);">${escapeHtml(h.description)}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `}
    </div>
  `;
}

function mountContests() {
  const cEl = document.getElementById('content');
  if(!cEl) return;
  
  if(!STORE.settings) STORE.settings = {};
  
  // Handle Kalvium student toggle
  cEl.querySelector('#chkKalviumStudent')?.addEventListener('change', (e) => {
    STORE.settings.isKalviumStudent = e.target.checked;
    save();
    render();
  });

  if(STORE.settings.isKalviumStudent) {
    mountDojo();
    return;
  }
  
  if(!STORE.contests) {
    STORE.contests = { entries: [], goals: [] };
    save();
  }
  
  cEl.querySelector('#btnNewContest')?.addEventListener('click', () => openContestModal());
  
  cEl.querySelector('#filterContAll')?.addEventListener('click', () => { contestFilter = 'All'; render(); });
  cEl.querySelector('#filterContUp')?.addEventListener('click', () => { contestFilter = 'Upcoming'; render(); });
  cEl.querySelector('#filterContDone')?.addEventListener('click', () => { contestFilter = 'Completed'; render(); });
  
  cEl.querySelector('#contestPlatformSelect')?.addEventListener('change', (e) => {
    contestPlatformFilter = e.target.value;
    render();
  });
  
  cEl.querySelectorAll('[data-edit-contest]').forEach(b => {
    b.addEventListener('click', (e) => {
      const id = e.currentTarget.dataset.editContest;
      const c = STORE.contests.entries.find(x => x.id === id);
      if(c) openContestModal(c);
    });
  });
  
  cEl.querySelectorAll('[data-del-contest]').forEach(b => {
    b.addEventListener('click', (e) => {
      const id = e.currentTarget.dataset.delContest;
      if(confirm('Delete this contest entry?')) {
        STORE.contests.entries = STORE.contests.entries.filter(x => x.id !== id);
        save(); render();
      }
    });
  });
}

function mountDojo(){
  document.getElementById('tabDojoTargets')?.addEventListener('click', () => { dojoTab = 'targets'; render(); });
  document.getElementById('tabDojoBelts')?.addEventListener('click', () => { dojoTab = 'belts'; render(); });
  document.getElementById('tabDojoTasks')?.addEventListener('click', () => { dojoTab = 'tasks'; render(); });
  document.getElementById('tabDojoHistory')?.addEventListener('click', () => { dojoTab = 'history'; render(); });

  document.getElementById('btnNewBeltTarget')?.addEventListener('click', () => openBeltTargetModal());
  document.getElementById('btnNewAttemptTarget')?.addEventListener('click', () => openAttemptTargetModal());
  document.getElementById('btnNewCodingTask')?.addEventListener('click', () => openCodingTaskModal());

  document.querySelectorAll('[data-progress-target]').forEach(b => b.addEventListener('click', e => {
    const id = e.currentTarget.dataset.progressTarget;
    const t = STORE.dojo.beltTargets.find(x => x.id === id);
    if(t) openUpdateProgressModal(t, 'belt');
  }));
  document.querySelectorAll('[data-progress-attempt]').forEach(b => b.addEventListener('click', e => {
    const id = e.currentTarget.dataset.progressAttempt;
    const a = STORE.dojo.attempts.find(x => x.id === id);
    if(a) openUpdateProgressModal(a, 'attempt');
  }));
  document.querySelectorAll('[data-add-task-target]').forEach(b => b.addEventListener('click', e => {
    openCodingTaskModal(null, e.currentTarget.dataset.addTaskTarget);
  }));
  document.querySelectorAll('[data-add-task-attempt]').forEach(b => b.addEventListener('click', e => {
    openCodingTaskModal(null, e.currentTarget.dataset.addTaskAttempt);
  }));
  document.querySelectorAll('[data-edit-target]').forEach(b => b.addEventListener('click', e => {
    const t = STORE.dojo.beltTargets.find(x => x.id === e.currentTarget.dataset.editTarget);
    if(t) openBeltTargetModal(t);
  }));
  document.querySelectorAll('[data-delete-target]').forEach(b => b.addEventListener('click', e => {
    const id = e.currentTarget.dataset.deleteTarget;
    if(confirm('Delete this Belt Target?')){
      STORE.dojo.beltTargets = STORE.dojo.beltTargets.filter(x => x.id !== id);
      addHistoryEntry('dojo', 'Delete Target', 'Deleted a Belt Target');
      save(); render();
    }
  }));
  document.querySelectorAll('[data-edit-attempt]').forEach(b => b.addEventListener('click', e => {
    const a = STORE.dojo.attempts.find(x => x.id === e.currentTarget.dataset.editAttempt);
    if(a) openAttemptTargetModal(a);
  }));
  document.querySelectorAll('[data-delete-attempt]').forEach(b => b.addEventListener('click', e => {
    const id = e.currentTarget.dataset.deleteAttempt;
    if(confirm('Delete this Attempt Target?')){
      STORE.dojo.attempts = STORE.dojo.attempts.filter(x => x.id !== id);
      addHistoryEntry('dojo', 'Delete Attempt', 'Deleted an Attempt Target');
      save(); render();
    }
  }));

  document.querySelectorAll('[data-toggle-belt-id]').forEach(b => b.addEventListener('click', e => {
    const num = Number(e.currentTarget.dataset.toggleBeltId);
    const item = STORE.dojo.belts.find(x => x.number === num);
    if(item){
      item.completed = !item.completed;
      addHistoryEntry('dojo', 'Belt Unlock', `${item.completed ? 'Unlocked' : 'Locked'} ${item.name}`);
      save(); render();
    }
  }));
  document.querySelectorAll('[data-edit-belt-id]').forEach(b => b.addEventListener('click', e => {
    const num = Number(e.currentTarget.dataset.editBeltId);
    const item = STORE.dojo.belts.find(x => x.number === num);
    if(item) openEditBeltModal(item);
  }));

  document.getElementById('filterTaskAll')?.addEventListener('click', () => { dojoFilter = 'all'; render(); });
  document.getElementById('filterTaskProg')?.addEventListener('click', () => { dojoFilter = 'In Progress'; render(); });
  document.getElementById('filterTaskDone')?.addEventListener('click', () => { dojoFilter = 'Completed'; render(); });
  document.getElementById('filterTaskNot')?.addEventListener('click', () => { dojoFilter = 'Not Started'; render(); });

  const sInput = document.getElementById('dojoTaskSearchInput');
  if(sInput){
    sInput.addEventListener('input', e => { dojoSearch = e.target.value; });
    sInput.addEventListener('keyup', e => { if(e.key === 'Enter') render(); });
  }

  document.querySelectorAll('.task-status-select').forEach(sel => sel.addEventListener('change', e => {
    const id = e.target.dataset.taskId;
    const newStatus = e.target.value;
    const task = STORE.dojo.codingTasks.find(x => x.id === id);
    if(task){
      const prevStatus = task.status;
      task.status = newStatus;
      if(newStatus === 'Completed' && prevStatus !== 'Completed'){
        task.completedAt = todayStr();
        if(task.targetId){
          const bt = STORE.dojo.beltTargets.find(x => x.id === task.targetId);
          if(bt){ bt.problemsSolved = (bt.problemsSolved || 0) + 1; }
          const at = STORE.dojo.attempts.find(x => x.id === task.targetId);
          if(at){ at.attempted = (at.attempted || 0) + 1; }
        }
        addHistoryEntry('dojo', 'Completed Task', `Completed task: "${task.title}"`);
        toast('🎉 Task completed & target progress updated!');
      }
      save(); render();
    }
  }));

  document.querySelectorAll('[data-edit-task]').forEach(b => b.addEventListener('click', e => {
    const t = STORE.dojo.codingTasks.find(x => x.id === e.currentTarget.dataset.editTask);
    if(t) openCodingTaskModal(t);
  }));
  document.querySelectorAll('[data-delete-task]').forEach(b => b.addEventListener('click', e => {
    const id = e.currentTarget.dataset.deleteTask;
    if(confirm('Delete this coding task?')){
      STORE.dojo.codingTasks = STORE.dojo.codingTasks.filter(x => x.id !== id);
      addHistoryEntry('dojo', 'Delete Task', 'Deleted a coding task');
      save(); render();
    }
  }));
}

function openBeltTargetModal(t = null){
  const isEdit = !!t;
  openModal(isEdit ? 'Edit Belt Target' : 'New Belt Level Target', `
    <div class="form-row"><label>Target Language</label><input id="btLang" value="${t ? escapeHtml(t.language) : 'Python'}" placeholder="e.g. Python, C++, Java" /></div>
    <div class="form-row"><label>Current Belt</label><input id="btCur" value="${t ? escapeHtml(t.currentBelt) : 'Belt 1 (White)'}" /></div>
    <div class="form-row"><label>Target Belt Name</label><input id="btTgt" value="${t ? escapeHtml(t.targetBelt) : 'Belt 6 (Purple)'}" /></div>
    <div class="form-row"><label>Target Problems Count</label><input id="btProbs" type="number" value="${t ? t.targetProblems : 150}" /></div>
    <div class="form-row"><label>Target Date</label><input id="btDate" type="date" value="${t ? t.targetDate : addDays(todayStr(), 60)}" /></div>
    <div class="form-row"><label>Topics Focus</label><input id="btTopics" value="${t ? escapeHtml(t.topics) : 'Arrays, Recursion, Trees'}" /></div>
    <div class="form-row"><label>Notes / Strategy</label><textarea id="btNotes">${t ? escapeHtml(t.notes || '') : ''}</textarea></div>
    <div class="form-actions"><button class="btn btn-ghost" id="mCancel">Cancel</button><button class="btn btn-accent" id="mSave">${isEdit ? 'Save Changes' : 'Create Target'}</button></div>
  `, modal => {
    modal.querySelector('#mCancel')?.addEventListener('click', closeModal);
    modal.querySelector('#mSave')?.addEventListener('click', () => {
      const lang = modal.querySelector('#btLang').value.trim() || 'General';
      const cur = modal.querySelector('#btCur').value.trim() || 'White';
      const tgt = modal.querySelector('#btTgt').value.trim() || 'Black';
      const probs = Number(modal.querySelector('#btProbs').value) || 50;
      const date = modal.querySelector('#btDate').value || todayStr();
      const topics = modal.querySelector('#btTopics').value.trim();
      const notes = modal.querySelector('#btNotes').value.trim();

      if(isEdit){
        Object.assign(t, { language: lang, currentBelt: cur, targetBelt: tgt, targetProblems: probs, targetDate: date, topics, notes });
      } else {
        STORE.dojo.beltTargets.push({
          id: uid(),
          targetType: 'belt',
          language: lang,
          currentBelt: cur,
          targetBelt: tgt,
          beltsAchieved: 1,
          beltsTarget: 6,
          problemsSolved: 0,
          targetProblems: probs,
          targetDate: date,
          topics,
          notes,
          status: 'In Progress',
          createdAt: todayStr()
        });
      }
      addHistoryEntry('dojo', isEdit ? 'Edit Target' : 'New Target', `${isEdit ? 'Updated' : 'Created'} Belt Target for ${lang}`);
      save(); closeModal(); render();
    });
  });
}

