function generateWeeklyMarkdown(startDateStr, endDateStr) {
  const name = STORE.settings.name || 'Developer';
  const sched = getSchedule();
  const dayNum = currentDayNumber();
  const totalDays = scheduleTotalDays();
  const pct = overallCompletionPct();
  const streak = currentStreak();
  
  // Tasks completed in date range
  let tasksCompleted = 0;
  let totalTasks = 0;
  Object.entries(STORE.plannerData || {}).forEach(([date, plan]) => {
    if (date >= startDateStr && date <= endDateStr && plan.tasks) {
      plan.tasks.forEach(t => {
        totalTasks++;
        if (t.done) tasksCompleted++;
      });
    }
  });

  // Pomodoro Focus sessions in date range
  const rangePomos = (STORE.pomodoroHistory || []).filter(h => {
    if (!h.timestamp) return false;
    const d = h.timestamp.split('T')[0];
    return d >= startDateStr && d <= endDateStr && h.type === 'focus';
  });
  const pomoMinutes = rangePomos.reduce((sum, p) => sum + Number(p.minutes || 25), 0);
  const pomoHours = (pomoMinutes / 60).toFixed(1);

  // Habit completion rate
  let habitTotal = 0;
  let habitDone = 0;
  Object.entries(STORE.habitLogs || {}).forEach(([date, dayLog]) => {
    if (date >= startDateStr && date <= endDateStr) {
      Object.values(dayLog).forEach(status => {
        habitTotal++;
        if (status === 'done') habitDone++;
      });
    }
  });
  const habitRate = habitTotal ? Math.round((habitDone / habitTotal) * 100) : 0;

  // Dojo Belts
  const dojoBelts = (STORE.dojo && STORE.dojo.belts) || [];
  const activeBelt = dojoBelts.find(b => !b.completed) || dojoBelts[dojoBelts.length - 1];
  const beltsUnlocked = dojoBelts.filter(b => b.completed).length;

  // Journal entries & wins in range
  const journalEntries = (STORE.journal || []).filter(j => j.date >= startDateStr && j.date <= endDateStr);
  const winsList = journalEntries.filter(j => j.wins).map(j => `- **${j.date}:** ${j.wins}`).join('\n');
  const lessonsList = journalEntries.filter(j => j.lessons).map(j => `- **${j.date}:** ${j.lessons}`).join('\n');

  // Reading & Projects
  const activeBooks = (STORE.books || []).filter(b => b.status === 'reading').map(b => `- 📖 **${b.title}**: ${b.readPages || 0}/${b.totalPages || 0} pages`).join('\n');
  const activeProjects = (STORE.projects || []).filter(p => p.status === 'in_progress').map(p => `- 💻 **${p.name}**: ${p.progress || 0}% completed`).join('\n');

  return `# 🚀 DAYSTACK Weekly Progress Summary

**Author:** ${name}  
**Reporting Period:** ${startDateStr} → ${endDateStr}  
**Master Schedule:** Cycle ${sched.currentCycle} (Day ${dayNum} of ${totalDays} | ${pct}% Completed)  
**Cycle Goal:** ${sched.cycleGoal || 'Master Target Schedule'}  

---

## 📊 Focus & Productivity Highlights
- ⏱️ **Focus Time:** ${pomoHours} Hours (${rangePomos.length} Pomodoro Focus Sessions)
- ✅ **Planner Tasks Completed:** ${tasksCompleted} / ${totalTasks} Tasks
- 🔥 **Habit Consistency:** ${habitRate}% Completion Rate (${streak}-Day Active Streak)
- 🥋 **Dojo Belt Rank:** ${activeBelt ? activeBelt.name : 'Master'} (${beltsUnlocked} / 10 Belts Unlocked)

---

## 🌟 Top Victories & Evening Reflections
${winsList || '_No evening reflection wins logged for this week yet._'}

${lessonsList ? `\n### 💡 Lessons & Improvements\n${lessonsList}\n` : ''}
---

## 📚 Active Reading & Project Pipelines
${activeBooks || '_No active reading projects._'}
${activeProjects || '_No active software projects in progress._'}

---

## 🎯 Priorities & Focus Areas for Next Week
- [ ] Maintain daily target schedule time blocks
- [ ] Practice DSA Dojo topics & algorithmic challenges
- [ ] Sustain habit consistency & evening reflection reviews

---
*Generated by DAYSTACK Productivity Suite on ${todayStr()}*`;
}

function openWeeklySummaryModal(){
  const dEnd = todayStr();
  const dStartObj = new Date();
  dStartObj.setDate(dStartObj.getDate() - 7);
  const dStart = dStartObj.toISOString().split('T')[0];

  openModal('📧 Weekly Email & Markdown Summary Generator', `
    <div style="margin-bottom:12px; font-size:12px;" class="dim">Generate a formatted Markdown summary of your weekly achievements to copy, download, or email.</div>
    <div class="form-grid" style="margin-bottom:12px;">
      <div class="form-row">
        <label>Start Date</label>
        <input type="date" id="wkSumStart" value="${dStart}"/>
      </div>
      <div class="form-row">
        <label>End Date</label>
        <input type="date" id="wkSumEnd" value="${dEnd}"/>
      </div>
    </div>
    
    <div class="form-row">
      <div class="flex between items-center" style="margin-bottom:6px;">
        <label>Generated Markdown Output</label>
        <div class="flex gap-4">
          <button class="btn btn-xs btn-ghost" id="wkSumPreset7">Past 7 Days</button>
          <button class="btn btn-xs btn-ghost" id="wkSumPresetCycle">Full Cycle</button>
        </div>
      </div>
      <textarea id="wkSumMarkdownArea" rows="12" style="font-family:monospace; font-size:12px; line-height:1.4; white-space:pre; padding:10px; width:100%; box-sizing:border-box;"></textarea>
    </div>

    <div class="form-actions wrap" style="gap:8px;">
      <button class="btn btn-ghost" id="mCloseWkSum">Close</button>
      <button class="btn btn-ghost" id="mCopyWkSum">📋 Copy Markdown</button>
      <button class="btn btn-ghost" id="mDownloadWkSum">📥 Download .md</button>
      <button class="btn btn-accent" id="mEmailWkSum">📧 Open in Email Client</button>
    </div>
  `, modal => {
    const startInput = modal.querySelector('#wkSumStart');
    const endInput = modal.querySelector('#wkSumEnd');
    const textArea = modal.querySelector('#wkSumMarkdownArea');

    function updateMarkdown(){
      const s = startInput.value || todayStr();
      const e = endInput.value || todayStr();
      textArea.value = generateWeeklyMarkdown(s, e);
    }

    updateMarkdown();

    startInput.addEventListener('change', updateMarkdown);
    endInput.addEventListener('change', updateMarkdown);

    modal.querySelector('#wkSumPreset7')?.addEventListener('click', () => {
      const e = todayStr();
      const sObj = new Date();
      sObj.setDate(sObj.getDate() - 7);
      const s = sObj.toISOString().split('T')[0];
      startInput.value = s;
      endInput.value = e;
      updateMarkdown();
    });

    modal.querySelector('#wkSumPresetCycle')?.addEventListener('click', () => {
      const sched = getSchedule();
      startInput.value = sched.startDate;
      endInput.value = sched.endDate;
      updateMarkdown();
    });

    modal.querySelector('#mCloseWkSum')?.addEventListener('click', closeModal);

    modal.querySelector('#mCopyWkSum')?.addEventListener('click', () => {
      navigator.clipboard.writeText(textArea.value).then(() => {
        toast('📋 Markdown copied to clipboard!');
      }).catch(() => {
        textArea.select();
        document.execCommand('copy');
        toast('📋 Markdown copied to clipboard!');
      });
    });

    modal.querySelector('#mDownloadWkSum')?.addEventListener('click', () => {
      const blob = new Blob([textArea.value], { type: 'text/markdown;charset=utf-8;' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `DAYSTACK_Weekly_Summary_${startInput.value}_to_${endInput.value}.md`;
      a.click();
      toast('📥 Markdown file downloaded!');
    });

    modal.querySelector('#mEmailWkSum')?.addEventListener('click', () => {
      const subject = `DAYSTACK Weekly Progress Summary (${startInput.value} to ${endInput.value})`;
      const body = textArea.value;
      const mailtoUrl = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
      window.open(mailtoUrl, '_blank');
      toast('📧 Opening email client...');
    });
  });
}

