function openSnapshotManagerModal(){
  BackupManager.getSnapshots().then(snapshots => {
    const list = Array.isArray(snapshots) ? snapshots : [];
    openModal('📸 Local Backup Snapshots', `
      <div style="margin-bottom:12px; font-size:12px;" class="dim">Automated daily, weekly, and manual snapshots stored securely in your browser's IndexedDB.</div>
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
        <span style="font-weight:700; font-size:13px; color:var(--text-bright);">${list.length} Snapshots Saved</span>
        <button class="btn btn-sm btn-accent" id="createManualSnapBtn">➕ Create Snapshot Now</button>
      </div>
      <div class="table-wrap" style="max-height:300px; overflow-y:auto;">
        <table>
          <thead><tr><th>Time</th><th>Type &amp; Label</th><th>Data Summary</th><th style="text-align:right;">Actions</th></tr></thead>
          <tbody>
            ${list.length ? list.map(s => `
              <tr>
                <td class="mono" style="font-size:11px; white-space:nowrap;">${new Date(s.timestamp).toLocaleString([], { dateStyle:'short', timeStyle:'short' })}</td>
                <td>
                  <span class="pill ${s.type==='daily'?'pill-accent':s.type==='weekly'?'pill-accent2':s.type==='pre_import'?'pill-accent3':'pill-dim'}" style="font-size:10px;">${s.type}</span>
                  <div style="font-weight:600; font-size:12px; color:var(--text-bright); margin-top:2px;">${escapeHtml(s.label)}</div>
                </td>
                <td class="dim" style="font-size:11px;">
                  ${s.summary ? `${s.summary.habits} habits · ${s.summary.plannerDates} days · ${s.summary.exams} exams` : 'Snapshot data'}
                </td>
                <td style="text-align:right; white-space:nowrap;">
                  <button class="btn btn-sm btn-accent restore-snap-btn" data-snap-id="${s.id}" style="padding:3px 8px; font-size:11.5px;">↺ Restore</button>
                  <button class="btn btn-sm btn-ghost del-snap-btn" data-snap-id="${s.id}" style="padding:3px 6px; font-size:11.5px; color:var(--danger);">🗑</button>
                </td>
              </tr>
            `).join('') : `<tr><td colspan="4" class="dim" style="text-align:center; padding:16px;">No backup snapshots saved yet.</td></tr>`}
          </tbody>
        </table>
      </div>
      <div class="form-actions" style="margin-top:14px;">
        <button class="btn btn-ghost" id="closeSnapModalBtn">Close</button>
      </div>
    `, modal => {
      modal.querySelector('#closeSnapModalBtn')?.addEventListener('click', closeModal);
      modal.querySelector('#createManualSnapBtn')?.addEventListener('click', async () => {
        await BackupManager.createSnapshot(STORE, 'manual', 'Manual User Snapshot');
        toast('📸 Manual backup snapshot created!');
        openSnapshotManagerModal();
      });
      modal.querySelectorAll('.restore-snap-btn').forEach(btn => {
        btn.addEventListener('click', async () => {
          const snapId = btn.dataset.snapId;
          if (confirm('Restore this backup snapshot? Your current state will be safely snapshotted first.')) {
            await BackupManager.createSnapshot(STORE, 'pre_import', 'Safety backup before restoring snapshot');
            const restored = await BackupManager.restoreSnapshot(snapId);
            if (restored) {
              STORE = restored;
              save();
              closeModal();
              toast('✅ Backup snapshot restored successfully!');
              render();
            } else {
              toast('Could not restore snapshot');
            }
          }
        });
      });
      modal.querySelectorAll('.del-snap-btn').forEach(btn => {
        btn.addEventListener('click', async () => {
          const snapId = btn.dataset.snapId;
          if (confirm('Delete this backup snapshot?')) {
            await BackupManager.deleteSnapshot(snapId);
            toast('Snapshot deleted');
            openSnapshotManagerModal();
          }
        });
      });
    });
  });
}

