function openRecurringExpensesModal(){
  if (!Array.isArray(STORE.recurringExpenses)) {
    STORE.recurringExpenses = RecurringFinance.getDefaultRecurring();
  }
  openModal('🔄 Recurring Expenses Manager', RecurringFinance.renderModalContent(STORE.recurringExpenses), modal => {
    modal.querySelectorAll('.rec-toggle-chk').forEach(chk => {
      chk.addEventListener('change', e => {
        const item = STORE.recurringExpenses.find(r => r.id === e.target.dataset.recId);
        if (item) {
          item.active = e.target.checked;
          save();
          render();
        }
      });
    });
    modal.querySelectorAll('.rec-del-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        STORE.recurringExpenses = STORE.recurringExpenses.filter(r => r.id !== btn.dataset.delRecId);
        save();
        openRecurringExpensesModal();
        render();
      });
    });
    modal.querySelector('#saveNewRecBtn')?.addEventListener('click', () => {
      const name = modal.querySelector('#newRecName')?.value?.trim();
      const amount = Number(modal.querySelector('#newRecAmount')?.value);
      const category = modal.querySelector('#newRecCat')?.value || 'other';
      const dayOfMonth = Number(modal.querySelector('#newRecDay')?.value) || 1;
      if (!name) return toast('Please enter an expense name');
      if (!amount) return toast('Please enter an amount');
      STORE.recurringExpenses.push({
        id: 'rec_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
        name,
        amount,
        category,
        recurrence: 'monthly',
        dayOfMonth,
        active: true,
        note: `Monthly ${name}`
      });
      save();
      toast('Recurring expense added');
      openRecurringExpensesModal();
      render();
    });
  });
}

function handleSafeJsonImport(file){
  if (!file) return;
  const reader = new FileReader();
  reader.onload = async ev => {
    try {
      const rawData = JSON.parse(ev.target.result);
      if (!rawData || typeof rawData !== 'object') {
        return toast('Invalid JSON backup format');
      }
      // Sanitize all string fields
      const sanitized = sanitizeObject(rawData);
      
      const habitsCount = Array.isArray(sanitized.habits) ? sanitized.habits.length : 0;
      const planDates = sanitized.plannerData ? Object.keys(sanitized.plannerData).length : 0;
      const examsCount = (sanitized.exams?.subjects || []).length;
      const userName = sanitized.settings?.name || sanitized.user?.profile?.name || 'User';

      // Auto-save pre-import snapshot
      await BackupManager.createSnapshot(STORE, 'pre_import', 'Automatic backup before JSON import');

      openModal('📥 Confirm JSON Backup Import', `
        <div style="font-size:13.5px; color:var(--text); line-height:1.5; margin-bottom:12px;">
          You are about to import a DAYSTACK backup file for <strong>${escapeHtml(userName)}</strong>.
        </div>
        <div class="card" style="padding:12px; background:var(--glass); border:1px solid var(--border-soft); margin-bottom:14px;">
          <div style="font-size:11.5px; font-weight:700; text-transform:uppercase; color:var(--accent); margin-bottom:6px;">📦 Backup Contents:</div>
          <div class="grid grid-3" style="gap:8px; font-size:12px;">
            <div>• <strong>${habitsCount}</strong> Habits</div>
            <div>• <strong>${planDates}</strong> Planner Days</div>
            <div>• <strong>${examsCount}</strong> Exam Subjects</div>
          </div>
        </div>
        <div style="font-size:12px; color:var(--text-dim); margin-bottom:16px;">
          🛡️ A safety snapshot of your current state has been automatically preserved in IndexedDB.
        </div>
        <div class="form-actions">
          <button class="btn btn-ghost" id="mCancelImport">Cancel</button>
          <button class="btn btn-accent" id="mConfirmImport">Confirm &amp; Import</button>
        </div>
      `, modal => {
        modal.querySelector('#mCancelImport')?.addEventListener('click', closeModal);
        modal.querySelector('#mConfirmImport')?.addEventListener('click', () => {
          STORE = sanitized;
          save();
          closeModal();
          toast('✅ Backup imported and verified successfully!');
          render();
        });
      });
    } catch (err) {
      console.error('Import parse error:', err);
      toast('Could not parse backup file. Please ensure it is valid JSON.');
    }
  };
  reader.readAsText(file);
}


