const POPULAR_COLORS = [
  { id: 'blue', name: 'Electric Blue', hex: '#2d8eff', rgb: '45, 142, 255' },
  { id: 'cyan', name: 'Neon Cyan', hex: '#06b6d4', rgb: '6, 182, 212' },
  { id: 'indigo', name: 'Indigo Spark', hex: '#6366f1', rgb: '99, 102, 241' },
  { id: 'purple', name: 'Deep Violet', hex: '#8b5cf6', rgb: '139, 92, 246' },
  { id: 'emerald', name: 'Emerald Mint', hex: '#10b981', rgb: '16, 185, 129' },
  { id: 'teal', name: 'Vibrant Teal', hex: '#17e0b8', rgb: '23, 224, 184' },
  { id: 'rose', name: 'Rose Pink', hex: '#f43f5e', rgb: '244, 63, 94' },
  { id: 'amber', name: 'Amber Gold', hex: '#f59e0b', rgb: '245, 158, 11' },
  { id: 'orange', name: 'Sunset Orange', hex: '#f97316', rgb: '249, 115, 22' },
  { id: 'red', name: 'Ruby Red', hex: '#ef4444', rgb: '239, 68, 68' },
];

function applyThemeAndGlass(){
  _cachedAccentHex = null;
  const theme = (STORE.settings && STORE.settings.theme) || 'dark';
  const glass = (STORE.settings && STORE.settings.glassFx) || 'ultra';
  const colorId = (STORE.settings && STORE.settings.accentColor) || 'blue';
  const colorObj = POPULAR_COLORS.find(c => c.id === colorId) || POPULAR_COLORS[0];

  if(document && document.documentElement && document.documentElement.setAttribute){
    document.documentElement.setAttribute('data-theme', theme);
    document.documentElement.setAttribute('data-glass', glass);
    document.documentElement.setAttribute('data-color', colorId);

    if(colorObj){
      document.documentElement.style.setProperty('--accent', colorObj.hex);
      document.documentElement.style.setProperty('--accent-rgb', colorObj.rgb);
      document.documentElement.style.setProperty('--accent-dim', `rgba(${colorObj.rgb}, 0.16)`);
      document.documentElement.style.setProperty('--glass-glow', `0 8px 30px -8px rgba(${colorObj.rgb}, 0.35)`);
    }
  }

  const metaTheme = document.querySelector('meta[name="theme-color"]');
  if(metaTheme){
    metaTheme.setAttribute('content', theme === 'light' ? '#f0f4f9' : '#080a0f');
  }

  const themeBtns = document.querySelectorAll('#themeToggleBtn, #mobileThemeBtn');
  themeBtns.forEach(btn => {
    btn.textContent = theme === 'dark' ? '🌙 Dark' : '☀️ Light';
  });

  const glassBtns = document.querySelectorAll('#glassToggleBtn');
  glassBtns.forEach(btn => {
    btn.textContent = glass === 'ultra' ? '💎 Ultra Glass' : '✨ Glass FX';
  });
}

function toggleTheme(){
  if(!STORE.settings) STORE.settings = {};
  STORE.settings.theme = STORE.settings.theme === 'light' ? 'dark' : 'light';
  save();
  applyThemeAndGlass();
  toast(STORE.settings.theme === 'light' ? '☀️ Light Theme Activated' : '🌙 Dark Theme Activated');
}

function toggleGlassFx(){
  if(!STORE.settings) STORE.settings = {};
  STORE.settings.glassFx = STORE.settings.glassFx === 'ultra' ? 'normal' : 'ultra';
  save();
  applyThemeAndGlass();
  toast(STORE.settings.glassFx === 'ultra' ? '💎 Ultra Glass Mode Active' : '✨ Standard Glass Mode');
}

function openPaletteModal(){
  const curColor = (STORE.settings && STORE.settings.accentColor) || 'blue';
  openModal('🎨 Select Primary Accent Color', `
    <div style="font-size:12.5px; margin-bottom:14px;" class="dim">Select your major primary accent color. All charts, progress bars, glows, and interactive controls will update instantly.</div>
    
    <div class="color-swatch-grid">
      ${POPULAR_COLORS.map(c => `
        <button class="color-swatch-btn ${curColor === c.id ? 'active' : ''}" data-color-id="${c.id}">
          <span class="color-swatch-dot" style="background:${c.hex};"></span>
          <span>${c.name}</span>
        </button>
      `).join('')}
    </div>

    <div class="form-actions mt-16">
      <button class="btn btn-accent" id="closePaletteModalBtn">Done</button>
    </div>
  `, modal => {
    modal.querySelectorAll('.color-swatch-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-color-id');
        if(!STORE.settings) STORE.settings = {};
        STORE.settings.accentColor = id;
        save();
        applyThemeAndGlass();
        modal.querySelectorAll('.color-swatch-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        toast(`🎨 ${POPULAR_COLORS.find(c => c.id === id)?.name || id} Theme Set`);
      });
    });
    modal.querySelector('#closePaletteModalBtn')?.addEventListener('click', () => {
      closeModal();
      render();
    });
  });
}


/* ==========================================================================
   ADMIN CONTROL CENTER ENGINE
   ========================================================================== */
function isAdminUser(user){
  const u = user || STORE?.user;
  if (!u) return false;
  return u.role === 'admin';
}

function updateSidebarAdminNav(){
  const nav = document.querySelector('.sidebar nav');
  if(!nav) return;
  const existingAdminBtn = nav.querySelector('[data-section="admin"]');
  if(isAdminUser()){
    if(!existingAdminBtn){
      const settingsBtn = nav.querySelector('[data-section="settings"]');
      const adminBtn = document.createElement('button');
      adminBtn.className = 'nav-item' + (currentSection === 'admin' ? ' active' : '');
      adminBtn.dataset.section = 'admin';
      adminBtn.innerHTML = '<span class="ico">🛡️</span>Admin Center';
      adminBtn.addEventListener('click', () => {
        navigate('admin');
        if(window.innerWidth <= 900) closeMobileSidebar();
      });
      if(settingsBtn && settingsBtn.parentNode === nav){
        nav.insertBefore(adminBtn, settingsBtn);
      } else {
        nav.appendChild(adminBtn);
      }
    }
  } else {
    if(existingAdminBtn){
      existingAdminBtn.remove();
      if(currentSection === 'admin') navigate('dashboard');
    }
  }
}

