function getActiveOnboardingSteps(){
  return ONBOARDING_STEPS_MASTER.filter(step => {
    if(['dashboard', 'analytics', 'settings', 'notif'].includes(step.section)) return true;
    return isModuleEnabled(step.section);
  });
}

let onboardingCurrentStep = 0;

const TourEngine = {
  isActive: false,
  currentMode: 'main', // 'main' (16-step master) or 'section' (contextual section tour)
  currentSectionKey: '',
  currentStepIndex: 0,
  autoPlay: false,
  autoPlayTimer: null,
  autoPlayDurationMs: 6500,
  isTransitioning: false,
  boundKeyHandler: null,
  boundResizeHandler: null,

  getSteps() {
    if (this.currentMode === 'section' && this.currentSectionKey && SECTION_TOURS[this.currentSectionKey]) {
      return SECTION_TOURS[this.currentSectionKey];
    }
    return getActiveOnboardingSteps();
  },

  start(stepIndex = 0) {
    this.currentMode = 'main';
    this.currentSectionKey = '';
    this.isActive = true;
    this.currentStepIndex = Math.max(0, stepIndex);
    onboardingCurrentStep = this.currentStepIndex;
    this.autoPlay = false;
    this.clearAutoPlay();

    if (typeof closeModal === 'function') closeModal();

    this.createOverlayDom();
    this.bindGlobalEvents();
    this.renderStep(this.currentStepIndex);
  },

  startSectionTour(sectionKey, stepIndex = 0) {
    if (!SECTION_TOURS[sectionKey] || !SECTION_TOURS[sectionKey].length) return;
    this.currentMode = 'section';
    this.currentSectionKey = sectionKey;
    this.isActive = true;
    this.currentStepIndex = Math.max(0, stepIndex);
    onboardingCurrentStep = this.currentStepIndex;
    this.autoPlay = false;
    this.clearAutoPlay();

    if (typeof closeModal === 'function') closeModal();

    this.createOverlayDom();
    this.bindGlobalEvents();
    this.renderStep(this.currentStepIndex);
  },

  shouldAutoLaunchSectionTour(sectionKey) {
    if (this.isActive) return false;
    if (!STORE.onboarding || !STORE.onboarding.completed) return false;
    if (STORE.onboarding.sectionToursCompleted && STORE.onboarding.sectionToursCompleted[sectionKey]) return false;
    try {
      if (localStorage.getItem('orvyn_tour_sec_' + sectionKey) === 'true') {
        if (!STORE.onboarding.sectionToursCompleted) STORE.onboarding.sectionToursCompleted = {};
        STORE.onboarding.sectionToursCompleted[sectionKey] = true;
        return false;
      }
    } catch (_) {}
    return Boolean(SECTION_TOURS[sectionKey] && isModuleEnabled(sectionKey));
  },

  createOverlayDom() {
    let overlay = document.getElementById('onboardingTourOverlay');
    if (overlay) overlay.remove();

    overlay = document.createElement('div');
    overlay.id = 'onboardingTourOverlay';
    overlay.className = 'onboarding-tour-overlay';
    overlay.innerHTML = `
      <!-- Spotlight Cutout Box -->
      <div class="tour-spotlight-box" id="tourSpotlightBox"></div>

      <!-- Animated Virtual Mouse Cursor -->
      <div class="tour-virtual-cursor" id="tourVirtualCursor" style="transform: translate(-100px, -100px); opacity:0;">
        <div class="cursor-pointer-svg">
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M4.5 2.5L10.5 20.5L13.8 13.8L20.5 10.5L4.5 2.5Z" fill="var(--accent, #4f8cff)" stroke="#ffffff" stroke-width="1.6" stroke-linejoin="round"/>
          </svg>
        </div>
        <div class="cursor-click-ripple" id="tourClickRipple"></div>
        <div class="cursor-badge" id="tourCursorBadge">Click</div>
      </div>

      <!-- Floating Tour Card -->
      <div class="onboarding-tour-card" id="tourCard" role="dialog" aria-modal="true">
        <div class="tour-progress-track">
          <div class="tour-progress-fill" id="tourProgressFill" style="width: 0%;"></div>
        </div>

        <div class="tour-card-header flex between align-center mb-8">
          <div class="flex items-center gap-8">
            <span class="pill pill-accent" id="tourStepBadge" style="font-size:11px; font-weight:700;">Step 1 of 16</span>
            <span class="tour-section-pill" id="tourSectionPill">◈ Dashboard</span>
          </div>
          <div class="flex align-center gap-4">
            <button class="tour-icon-btn" id="tourAutoPlayBtn" title="Toggle Auto-Play (Space)" aria-label="Toggle Auto-Play">▶</button>
            <button class="tour-icon-btn" id="tourSkipBtn" title="Exit Tour (Esc)" aria-label="Exit Tour">✕</button>
          </div>
        </div>

        <div class="tour-card-body">
          <h3 id="tourTitle" style="font-size:15.5px; font-weight:700; color:var(--text-bright); margin-bottom:6px; line-height:1.35;">Tour Title</h3>
          <p id="tourDesc" style="font-size:13px; line-height:1.55; color:var(--text); margin-bottom:8px;">Description</p>
          <div class="tour-tip-box flex items-start gap-8" id="tourTipWrap">
            <span id="tourTipText">Pro tip</span>
          </div>
        </div>

        <div class="tour-card-footer flex between items-center pt-8" style="border-top:1px solid var(--border-soft);">
          <div class="flex gap-4">
            <button class="btn btn-xs btn-ghost" id="tourReplayBtn" title="Replay Cursor Click (r)">↺ Replay</button>
            <button class="btn btn-xs btn-ghost" id="tourPrevBtn" title="Previous Step (Left Arrow)">← Back</button>
          </div>
          <div class="flex align-center gap-6">
            <button class="btn btn-xs btn-ghost" id="tourExitBtn" style="color:var(--text-dim);">Skip Tour</button>
            <button class="btn btn-sm btn-accent" id="tourNextBtn" title="Next Step (Right Arrow)">Next Step →</button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);

    overlay.querySelector('#tourSkipBtn')?.addEventListener('click', () => this.finish());
    overlay.querySelector('#tourExitBtn')?.addEventListener('click', () => this.finish());
    overlay.querySelector('#tourPrevBtn')?.addEventListener('click', () => this.prev());
    overlay.querySelector('#tourNextBtn')?.addEventListener('click', () => this.next());
    overlay.querySelector('#tourReplayBtn')?.addEventListener('click', () => this.replay());
    overlay.querySelector('#tourAutoPlayBtn')?.addEventListener('click', () => this.toggleAutoPlay());
  },

  resolveTarget(step) {
    if (!step) return null;
    const findVisible = (selectorStr) => {
      if (!selectorStr) return null;
      const selectors = selectorStr.split(',').map(s => s.trim()).filter(Boolean);
      for (const sel of selectors) {
        try {
          const els = document.querySelectorAll(sel);
          for (const el of els) {
            if (el && el.isConnected) {
              const r = el.getBoundingClientRect();
              if (r.width > 0 || r.height > 0 || el.offsetParent !== null) {
                return el;
              }
            }
          }
        } catch (_) {}
      }
      return null;
    };

    let target = findVisible(step.targetSelector);
    if (!target && step.fallbackSelector) {
      target = findVisible(step.fallbackSelector);
    }
    if (!target) {
      target = findVisible('.section-hero, .hero, #content .card, #content');
    }
    return target;
  },

  renderStep(index) {
    const steps = this.getSteps();
    if (!steps.length || index >= steps.length) {
      this.finish();
      return;
    }
    if (index < 0) index = 0;

    this.currentStepIndex = index;
    onboardingCurrentStep = index;
    const step = steps[index];
    const isLast = index === steps.length - 1;
    const isFirst = index === 0;

    const isSectionMode = (this.currentMode === 'section');
    const secName = SECTION_TITLES[this.currentSectionKey]?.[0] || this.currentSectionKey;

    const stepBadge = document.getElementById('tourStepBadge');
    if (stepBadge) {
      stepBadge.textContent = isSectionMode
        ? `Step ${index + 1} of ${steps.length} · ${secName} Guide`
        : `Step ${index + 1} of ${steps.length}`;
    }

    const sectionPill = document.getElementById('tourSectionPill');
    if (sectionPill) {
      sectionPill.textContent = isSectionMode
        ? `🗺️ ${secName}`
        : `${step.icon || '◈'} ${step.sectionLabel || step.section}`;
    }

    const progressFill = document.getElementById('tourProgressFill');
    if (progressFill) {
      progressFill.style.width = `${Math.round(((index + 1) / steps.length) * 100)}%`;
    }

    const titleEl = document.getElementById('tourTitle');
    if (titleEl) titleEl.textContent = step.title;

    const descEl = document.getElementById('tourDesc');
    if (descEl) descEl.textContent = step.desc;

    const tipEl = document.getElementById('tourTipText');
    if (tipEl) tipEl.textContent = step.tip;

    const prevBtn = document.getElementById('tourPrevBtn');
    if (prevBtn) prevBtn.style.display = isFirst ? 'none' : 'inline-flex';

    const nextBtn = document.getElementById('tourNextBtn');
    if (nextBtn) {
      nextBtn.textContent = isLast ? (isSectionMode ? 'Finish Section Guide 🎉' : 'Finish Tour 🎉') : 'Next Step →';
      nextBtn.className = isLast ? 'btn btn-sm btn-accent2' : 'btn btn-sm btn-accent';
    }

    const autoBtn = document.getElementById('tourAutoPlayBtn');
    if (autoBtn) autoBtn.textContent = this.autoPlay ? '⏸' : '▶';

    if (step.section && currentSection !== step.section) {
      this.isTransitioning = true;
      navigate(step.section);
      setTimeout(() => {
        this.isTransitioning = false;
        this.positionAndAnimate(step);
      }, 200);
    } else {
      this.positionAndAnimate(step);
    }

    if (this.autoPlay && !isLast) {
      this.startAutoPlayTimer();
    }
  },

  positionAndAnimate(step) {
    const targetEl = this.resolveTarget(step);

    if (targetEl) {
      try {
        targetEl.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
      } catch (_) {}
    }

    setTimeout(() => {
      this.repositionCard(targetEl);
      this.animateCursorAndSpotlight(targetEl, step);
    }, 120);
  },

  animateCursorAndSpotlight(targetEl, step) {
    const cursor = document.getElementById('tourVirtualCursor');
    const spotlight = document.getElementById('tourSpotlightBox');
    if (!cursor || !spotlight) return;

    if (!targetEl) {
      spotlight.style.opacity = '0';
      cursor.style.opacity = '0';
      return;
    }

    spotlight.style.opacity = '1';
    cursor.style.opacity = '1';

    const rect = targetEl.getBoundingClientRect();
    const pad = Math.min(10, Math.max(5, Math.round(Math.min(rect.width, rect.height) * 0.05)));
    const sTop = Math.max(4, rect.top - pad);
    const sLeft = Math.max(4, rect.left - pad);
    const sWidth = Math.max(20, Math.min(window.innerWidth - sLeft - 4, rect.width + pad * 2));
    const sHeight = Math.max(20, Math.min(window.innerHeight - sTop - 4, rect.height + pad * 2));

    let computedRadius = 12;
    try {
      const br = parseInt(window.getComputedStyle(targetEl).borderRadius);
      if (!isNaN(br) && br > 0) computedRadius = Math.min(24, br + 2);
    } catch (_) {}

    spotlight.style.transform = 'none';
    spotlight.style.top = `${sTop}px`;
    spotlight.style.left = `${sLeft}px`;
    spotlight.style.width = `${sWidth}px`;
    spotlight.style.height = `${sHeight}px`;
    spotlight.style.borderRadius = `${computedRadius}px`;
    spotlight.classList.add('spotlight-pulsing');

    const targetX = Math.max(12, Math.min(window.innerWidth - 36, rect.left + Math.min(rect.width * 0.45, 32)));
    const targetY = Math.max(12, Math.min(window.innerHeight - 36, rect.top + Math.min(rect.height * 0.5, 24)));

    const badgeEl = document.getElementById('tourCursorBadge');
    if (badgeEl) badgeEl.textContent = step.cursorLabel || (step.cursorAction === 'click' ? 'Click' : 'Explore');

    cursor.classList.remove('cursor-clicking', 'cursor-show-badge');
    cursor.style.transform = `translate(${targetX}px, ${targetY}px)`;

    const isReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const moveDuration = isReduced ? 40 : 420;

    setTimeout(() => {
      cursor.classList.add('cursor-show-badge');

      if (step.cursorAction === 'click') {
        setTimeout(() => {
          cursor.classList.add('cursor-clicking');
          if (STORE && STORE.notificationsConfig && STORE.notificationsConfig.audioEnabled !== false) {
            playNotificationSound('pre');
          }
          setTimeout(() => {
            cursor.classList.remove('cursor-clicking');
          }, 400);
        }, 150);
      }
    }, moveDuration);
  },

  repositionCard(targetEl) {
    const card = document.getElementById('tourCard');
    if (!card) return;

    const cardRect = card.getBoundingClientRect();
    const cardWidth = Math.min(cardRect.width || 460, window.innerWidth - 24);
    const cardHeight = cardRect.height || 230;
    const margin = 14;

    if (window.innerWidth <= 680 || !targetEl) {
      card.style.position = 'fixed';
      card.style.bottom = '12px';
      card.style.left = '50%';
      card.style.transform = 'translateX(-50%)';
      card.style.top = 'auto';
      card.style.right = 'auto';
      card.style.width = 'calc(100vw - 24px)';
      return;
    }

    const rect = targetEl.getBoundingClientRect();
    const spaceBelow = window.innerHeight - (rect.bottom + margin);
    const spaceAbove = rect.top - margin;
    const spaceRight = window.innerWidth - (rect.right + margin);
    const spaceLeft = rect.left - margin;

    let top = 0;
    let left = 0;

    if (spaceBelow >= cardHeight) {
      top = rect.bottom + margin;
      left = Math.max(margin, Math.min(window.innerWidth - cardWidth - margin, rect.left));
    } else if (spaceAbove >= cardHeight) {
      top = rect.top - cardHeight - margin;
      left = Math.max(margin, Math.min(window.innerWidth - cardWidth - margin, rect.left));
    } else if (spaceRight >= cardWidth) {
      left = rect.right + margin;
      top = Math.max(margin, Math.min(window.innerHeight - cardHeight - margin, rect.top));
    } else if (spaceLeft >= cardWidth) {
      left = rect.left - cardWidth - margin;
      top = Math.max(margin, Math.min(window.innerHeight - cardHeight - margin, rect.top));
    } else {
      top = Math.max(margin, window.innerHeight - cardHeight - margin);
      left = Math.max(margin, (window.innerWidth - cardWidth) / 2);
    }

    // Strict screen boundary clamping
    top = Math.max(10, Math.min(window.innerHeight - cardHeight - 10, top));
    left = Math.max(10, Math.min(window.innerWidth - cardWidth - 10, left));

    card.style.position = 'fixed';
    card.style.top = `${top}px`;
    card.style.left = `${left}px`;
    card.style.bottom = 'auto';
    card.style.right = 'auto';
    card.style.transform = 'none';
    card.style.width = `${cardWidth}px`;
  },

  next() {
    const steps = this.getSteps();
    if (this.currentStepIndex >= steps.length - 1) {
      this.finish();
    } else {
      this.renderStep(this.currentStepIndex + 1);
    }
  },

  prev() {
    if (this.currentStepIndex > 0) {
      this.renderStep(this.currentStepIndex - 1);
    }
  },

  replay() {
    this.renderStep(this.currentStepIndex);
  },

  toggleAutoPlay() {
    this.autoPlay = !this.autoPlay;
    const autoBtn = document.getElementById('tourAutoPlayBtn');
    if (autoBtn) autoBtn.textContent = this.autoPlay ? '⏸' : '▶';

    if (this.autoPlay) {
      toast('▶ Auto-play active (Space to pause)');
      this.startAutoPlayTimer();
    } else {
      toast('⏸ Auto-play paused');
      this.clearAutoPlay();
    }
  },

  startAutoPlayTimer() {
    this.clearAutoPlay();
    this.autoPlayTimer = setTimeout(() => {
      if (this.isActive && this.autoPlay) {
        this.next();
      }
    }, this.autoPlayDurationMs);
  },

  clearAutoPlay() {
    if (this.autoPlayTimer) {
      clearTimeout(this.autoPlayTimer);
      this.autoPlayTimer = null;
    }
  },

  bindGlobalEvents() {
    this.unbindGlobalEvents();

    this.boundKeyHandler = (e) => {
      if (!this.isActive) return;
      if (e.key === 'ArrowRight' || e.key === 'Enter') {
        e.preventDefault();
        this.next();
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        this.prev();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        this.finish();
      } else if (e.key === ' ' && e.target.tagName !== 'INPUT' && e.target.tagName !== 'TEXTAREA') {
        e.preventDefault();
        this.toggleAutoPlay();
      } else if (e.key === 'r' || e.key === 'R') {
        e.preventDefault();
        this.replay();
      }
    };

    this.boundResizeHandler = () => {
      if (!this.isActive) return;
      const steps = this.getSteps();
      const step = steps[this.currentStepIndex];
      if (step) {
        const targetEl = this.resolveTarget(step);
        this.repositionCard(targetEl);
        if (targetEl) {
          const spotlight = document.getElementById('tourSpotlightBox');
          if (spotlight) {
            const rect = targetEl.getBoundingClientRect();
            const pad = Math.min(10, Math.max(5, Math.round(Math.min(rect.width, rect.height) * 0.05)));
            spotlight.style.top = `${Math.max(4, rect.top - pad)}px`;
            spotlight.style.left = `${Math.max(4, rect.left - pad)}px`;
            spotlight.style.width = `${Math.max(20, Math.min(window.innerWidth - (rect.left - pad) - 4, rect.width + pad * 2))}px`;
            spotlight.style.height = `${Math.max(20, Math.min(window.innerHeight - (rect.top - pad) - 4, rect.height + pad * 2))}px`;
          }
        }
      }
    };

    window.addEventListener('keydown', this.boundKeyHandler);
    window.addEventListener('resize', this.boundResizeHandler);
    window.addEventListener('scroll', this.boundResizeHandler, { passive: true });
  },

  unbindGlobalEvents() {
    if (this.boundKeyHandler) {
      window.removeEventListener('keydown', this.boundKeyHandler);
      this.boundKeyHandler = null;
    }
    if (this.boundResizeHandler) {
      window.removeEventListener('resize', this.boundResizeHandler);
      window.removeEventListener('scroll', this.boundResizeHandler);
      this.boundResizeHandler = null;
    }
  },

  finish(quiet = false) {
    this.isActive = false;
    this.clearAutoPlay();
    this.unbindGlobalEvents();

    const overlay = document.getElementById('onboardingTourOverlay');
    if (overlay) overlay.remove();

    if (!STORE.onboarding) STORE.onboarding = {};
    if (!STORE.onboarding.sectionToursCompleted) STORE.onboarding.sectionToursCompleted = {};

    if (this.currentMode === 'main') {
      STORE.onboarding.completed = true;
      STORE.onboarding.tourCompleted = true;
      STORE.onboarding.completedAt = new Date().toISOString();
      if (!STORE.user) STORE.user = {};
      STORE.user.onboardingCompleted = true;
      try {
        localStorage.setItem('orvyn_onboarding_completed', 'true');
        localStorage.setItem('orvyn_tour_completed', 'true');
      } catch (_) {}
      save();
      if (!quiet) {
        toast('🎉 Guided 16-Step Tour Complete! You know your way around DAYSTACK now.');
        playNotificationSound('post');
      }
    } else if (this.currentMode === 'section' && this.currentSectionKey) {
      STORE.onboarding.sectionToursCompleted[this.currentSectionKey] = true;
      try {
        localStorage.setItem('orvyn_tour_sec_' + this.currentSectionKey, 'true');
      } catch (_) {}
      save();
      if (!quiet) {
        const secTitle = SECTION_TITLES[this.currentSectionKey]?.[0] || this.currentSectionKey;
        toast(`🎉 ${secTitle} Onboarding Complete!`);
        playNotificationSound('post');
      }
    }
  }
};

