function openSelectSectionTourModal(){
  const sections = Object.keys(SECTION_TOURS).filter(s => isModuleEnabled(s));
  const modalHtml = `
    <div style="padding:4px;">
      <div class="dim" style="font-size:13px; margin-bottom:14px;">
        Choose a module to launch its dedicated interactive walkthrough:
      </div>
      <div class="grid grid-2" style="gap:10px; max-height:420px; overflow-y:auto; padding-right:4px;">
        ${sections.map(s => {
          const [title, sub] = SECTION_TITLES[s] || [s, ''];
          const isDone = STORE.onboarding?.sectionToursCompleted?.[s] || false;
          return `
            <div class="card p-12 flex between align-center" style="background:var(--bg-2); border:1px solid var(--border-soft); border-radius:10px; cursor:pointer;" data-tour-sec="${s}">
              <div>
                <strong style="color:var(--text-bright); font-size:13px; display:block;">${escapeHtml(title)}</strong>
                <div class="dim" style="font-size:11px;">${escapeHtml(sub ? sub.slice(0, 48) + '...' : '')}</div>
              </div>
              <span class="pill ${isDone ? 'pill-accent' : 'pill-ghost'}" style="font-size:10px; font-weight:700;">
                ${isDone ? '✓ Completed' : 'Start Tour →'}
              </span>
            </div>
          `;
        }).join('')}
      </div>
      <div class="modal-footer flex between align-center mt-16 pt-12" style="border-top:1px solid var(--border-soft);">
        <button type="button" class="btn btn-ghost" id="mReplayMain16Btn" style="color:var(--accent);">🎓 Replay Main 16-Step Tour</button>
        <button type="button" class="btn btn-ghost close-modal">Close</button>
      </div>
    </div>
  `;

  openModal('🗺️ Select Onboarding Tour', modalHtml, modal => {
    modal.querySelectorAll('[data-tour-sec]').forEach(card => {
      card.addEventListener('click', () => {
        const sec = card.dataset.tourSec;
        closeModal();
        if (currentSection !== sec) {
          navigate(sec);
        }
        setTimeout(() => {
          startSectionOnboardingTour(sec, 0);
        }, 220);
      });
    });

    modal.querySelector('#mReplayMain16Btn')?.addEventListener('click', () => {
      closeModal();
      startOnboardingTour(0);
    });
  });
}

function repositionTourCard(){
  const steps = TourEngine.getSteps();
  const step = steps[TourEngine.currentStepIndex];
  if (step) {
    const targetEl = step.targetSelector ? document.querySelector(step.targetSelector) : null;
    TourEngine.repositionCard(targetEl);
  }
}

function renderTourOverlay(){
  TourEngine.renderStep(TourEngine.currentStepIndex);
}

function finishOnboardingTour(){
  TourEngine.finish();
}

