function openGuardianVerificationModal(guardianEmail, onVerified){
  if(!guardianEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(guardianEmail)){
    toast('⚠️ Please enter a valid parent/guardian email address first.');
    return;
  }

  const studentName = (STORE?.user?.profile?.name) || (STORE?.settings?.name) || 'Student';
  const studentDob = STORE?.user?.profile?.dob || null;
  const studentAge = studentDob ? calculateAge(studentDob) : null;

  // Send real verification request to backend
  fetch('/api/guardian/send-verification', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      guardianEmail,
      studentName,
      studentAge,
      studentDob
    })
  }).then(r => r.json()).then(data => {
    if(!data.success){
      toast('⚠️ ' + (data.error || 'Failed to dispatch verification code.'));
      return;
    }
    toast(`✉️ 6-Digit verification code dispatched to ${guardianEmail}`);

    const modalHtml = `
      <div class="otp-container">
        <div style="font-size:38px; margin-bottom:4px;">🛡️</div>
        <strong style="color:var(--text-bright); font-size:16px;">Parent / Guardian Verification</strong>
        <div class="dim" style="font-size:12.5px; text-align:center; max-width:380px; line-height:1.5;">
          A 6-digit verification code has been dispatched to <strong>${escapeHtml(guardianEmail)}</strong>. Enter the code below to confirm guardian consent:
        </div>

        <div style="margin:14px 0 6px 0;">
          <input type="text" id="mOtpDigitInput" class="otp-input-field" maxlength="6" placeholder="______" autofocus autocomplete="one-time-code" />
        </div>

        ${data.previewCode ? `
          <div style="font-size:11px; padding:4px 10px; background:var(--accent-dim); border:1px dashed var(--accent); border-radius:6px; color:var(--text-bright);">
            💡 Verification Code Preview: <strong style="letter-spacing:1px;">${data.previewCode}</strong>
          </div>
        ` : ''}

        <div class="otp-timer-text" id="mOtpTimerText">Code valid for 15 minutes</div>

        <div class="flex gap-10 align-center wrap mt-12" style="width:100%; justify-content:center;">
          <button type="button" class="btn btn-ghost btn-sm" id="mOtpResendBtn" style="border:1px solid var(--border-soft);">
            🔄 Resend Code
          </button>
          <button type="button" class="btn btn-accent btn-sm" id="mOtpSubmitBtn" style="font-weight:700; padding:8px 22px;">
            ✓ Verify &amp; Confirm
          </button>
        </div>
      </div>
    `;

    openModal('🛡️ Guardian Verification', modalHtml, modal => {
      const input = modal.querySelector('#mOtpDigitInput');
      const submitBtn = modal.querySelector('#mOtpSubmitBtn');
      const resendBtn = modal.querySelector('#mOtpResendBtn');
      if(input) input.focus();

      const verifyCodeAction = async () => {
        const code = input?.value.trim();
        if(!code || code.length !== 6){
          toast('⚠️ Please enter the complete 6-digit verification code.');
          input?.focus();
          return;
        }

        try {
          const res = await fetch('/api/guardian/verify-code', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ guardianEmail, code })
          });
          const vData = await res.json();
          if(!vData.success){
            toast('❌ ' + (vData.error || 'Invalid verification code. Please check and retry.'));
            input?.focus();
            return;
          }

          // Verified successfully!
          if(!STORE.user) STORE.user = {};
          if(!STORE.user.profile) STORE.user.profile = {};
          STORE.user.profile.guardianEmail = guardianEmail;
          STORE.user.profile.guardianStatus = 'verified';
          STORE.user.profile.guardianConsentAt = new Date().toISOString();
          save();

          closeModal();
          toast('🎉 Parent/Guardian email verified successfully!');
          if(typeof onVerified === 'function'){
            onVerified({ verified: true, email: guardianEmail });
          }
        } catch(err){
          toast('⚠️ Verification network error. Please try again.');
        }
      };

      submitBtn?.addEventListener('click', verifyCodeAction);
      input?.addEventListener('keydown', (e) => {
        if(e.key === 'Enter') verifyCodeAction();
      });

      resendBtn?.addEventListener('click', () => {
        closeModal();
        openGuardianVerificationModal(guardianEmail, onVerified);
      });
    });
  }).catch(err => {
    toast('⚠️ Failed to connect to verification service. Please ensure the server is running.');
  });
}

